    fn validate_proof_attachment<'a>(
        attachment: &'a iroha_data_model::proof::ProofAttachment,
        proof: &'a iroha_data_model::proof::ProofBox,
        expects_envelope: bool,
        envelope_meta: Option<&'a ZkOpenVerifyEnvelope>,
    ) -> Result<Option<&'a ZkOpenVerifyEnvelope>, Error> {
        if attachment.backend != proof.backend {
            return Err(InstructionExecutionError::InvariantViolation(
                "proof backend mismatch".into(),
            ));
        }
        if attachment.vk_ref.backend != attachment.backend {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key backend mismatch".into(),
            ));
        }
        if crate::zk::is_production_claim_backend_label(attachment.backend.as_str()) {
            return Err(production_claim_proof_backend_error());
        }
        if crate::zk::is_trusted_setup_backend_label(attachment.backend.as_str()) {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "trusted-setup proof backends are not supported".into(),
                ),
            ));
        }
        if crate::zk::is_developer_only_backend_label(attachment.backend.as_str()) {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "developer-only proof backends are not supported".into(),
                ),
            ));
        }
        if !crate::zk::is_production_verify_backend_label(attachment.backend.as_str()) {
            return Err(unsupported_proof_backend_error());
        }
        if expects_envelope && envelope_meta.is_none() {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "proofs for this backend must use OpenVerifyEnvelope payload".into(),
                ),
            ));
        }
        if expects_envelope && let Some(envelope) = envelope_meta {
            ensure_open_verify_circuit_id_is_admitted_v1(
                attachment.backend.as_str(),
                &envelope.circuit_id,
            )?;
        }
        if expects_envelope
            && let Some(envelope) = envelope_meta
            && !open_verify_backend_tag_matches(attachment.backend.as_str(), envelope.backend)
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "OpenVerifyEnvelope backend tag mismatch".into(),
            ));
        }
        Ok(envelope_meta)
    }
    fn open_verify_backend_tag_matches(backend: &str, tag: BackendTag) -> bool {
        crate::zk::production_verify_backend_tag(backend).is_some_and(|expected| expected == tag)
    }
    fn backend_requires_open_verify_envelope(backend: &str) -> bool {
        matches!(
            crate::zk::production_verify_backend_tag(backend),
            Some(BackendTag::Halo2IpaPasta | BackendTag::Stark)
        )
    }
    struct ProofEventArgs<'a> {
        pid: &'a iroha_data_model::proof::ProofId,
        attachment: &'a iroha_data_model::proof::ProofAttachment,
        vk_commitment: Option<[u8; 32]>,
        call_hash: Option<[u8; 32]>,
        prune_outcome: Option<ProofPruneOutcome>,
        cap: usize,
        grace_blocks: u64,
        prune_batch: usize,
        height: u64,
        authority: &'a AccountId,
    }
    fn proof_events_for_result(
        ok: bool,
        args: ProofEventArgs<'_>,
    ) -> Vec<iroha_data_model::events::data::proof::ProofEvent> {
        use iroha_data_model::events::data::proof::{
            ProofEvent, ProofPruneOrigin, ProofPruned, ProofRejected, ProofVerified,
        };
        let mut events = Vec::new();
        if ok {
            events.push(ProofEvent::Verified(ProofVerified {
                id: args.pid.clone(),
                vk_ref: Some(args.attachment.vk_ref.clone()),
                vk_commitment: args.vk_commitment,
                call_hash: args.call_hash,
                envelope_hash: args.attachment.envelope_hash,
            }));
        } else {
            events.push(ProofEvent::Rejected(ProofRejected {
                id: args.pid.clone(),
                vk_ref: Some(args.attachment.vk_ref.clone()),
                vk_commitment: args.vk_commitment,
                call_hash: args.call_hash,
                envelope_hash: args.attachment.envelope_hash,
            }));
        }
        if let Some(outcome) = args.prune_outcome {
            events.push(ProofEvent::Pruned(ProofPruned {
                backend: outcome.backend,
                removed: outcome.removed,
                remaining: outcome.remaining,
                cap: args.cap as u64,
                grace_blocks: args.grace_blocks,
                prune_batch: args.prune_batch as u64,
                pruned_at_height: args.height,
                pruned_by: args.authority.clone(),
                origin: ProofPruneOrigin::Insert,
            }));
        }
        events
    }
    fn invalid_bridge_proof(message: impl Into<String>) -> Error {
        InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
            message.into(),
        ))
        .into()
    }
    fn invalid_bridge_receipt(message: impl Into<String>) -> Error {
        InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
            message.into(),
        ))
        .into()
    }
    fn canonical_bridge_proof_size_bytes(proof_size: usize) -> Result<u32, Error> {
        u32::try_from(proof_size).map_err(|_| {
            invalid_bridge_proof(
                "bridge proof encoded length exceeds the canonical u32 storage domain",
            )
        })
    }
    fn validate_sccp_finality_against_state(
        parsed: &iroha_sccp::SccpParsedDestinationProofV1,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<iroha_sccp::TairaBridgeFinalityProofV1, Error> {
        crate::bridge::verify_sccp_parsed_destination_proof_against_local_state(
            state_transaction,
            parsed,
        )
        .map_err(|err| {
            invalid_bridge_proof(format!(
                "SCCP finality proof is not locally anchored: {err}"
            ))
        })
    }
    fn sccp_local_sora_network_for_chain_id(
        chain_id: &iroha_data_model::ChainId,
    ) -> Option<iroha_data_model::bridge::SccpNetworkV1> {
        crate::state::sccp_local_sora_network_for_chain_id(chain_id)
    }
    fn validate_sccp_bridge_proof_range(
        proof: &iroha_data_model::bridge::BridgeProof,
        finality_height: u64,
    ) -> Result<(), Error> {
        if proof.range.start_height == finality_height && proof.range.end_height == finality_height
        {
            return Ok(());
        }
        Err(invalid_bridge_proof(format!(
            "SCCP message proof range must match finality height {finality_height}"
        )))
    }
    fn bridge_proof_uses_iroha_height_window(
        payload: &iroha_data_model::bridge::BridgeProofPayload,
    ) -> bool {
        matches!(
            payload,
            iroha_data_model::bridge::BridgeProofPayload::Ics(_)
                | iroha_data_model::bridge::BridgeProofPayload::TransparentZk(_)
        )
    }
    fn validate_bridge_proof_height_window(
        proof: &iroha_data_model::bridge::BridgeProof,
        current_height: u64,
        past_window: u64,
        future_window: u64,
    ) -> Result<(), Error> {
        if !bridge_proof_uses_iroha_height_window(&proof.payload) {
            return Ok(());
        }
        if past_window > 0 {
            let floor = current_height.saturating_sub(past_window);
            if proof.range.end_height < floor {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "bridge proof range ends before the allowed past window (end_height={} < floor={floor})",
                        proof.range.end_height
                    )),
                ));
            }
        }
        if future_window > 0 {
            let ceiling = current_height.saturating_add(future_window);
            if proof.range.end_height > ceiling {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "bridge proof range ends after the allowed future window (end_height={} > ceiling={ceiling})",
                        proof.range.end_height
                    )),
                ));
            }
        }
        Ok(())
    }
    #[derive(Clone, Copy, Debug)]
    struct ValidatedSccpOutboundProofV1 {
        key: iroha_data_model::bridge::SccpOutboundMessageKeyV1,
        payload_hash: [u8; 32],
        destination_binding_hash: [u8; 32],
        route_configuration_hash: [u8; 32],
        finality_height: u64,
        commitment_index: u32,
        finality_block_hash: [u8; 32],
    }
    impl ValidatedSccpOutboundProofV1 {
        fn descriptor(self) -> iroha_data_model::bridge::SccpOutboundMessageDescriptorV1 {
            iroha_data_model::bridge::SccpOutboundMessageDescriptorV1 {
                destination_binding_hash: self.destination_binding_hash,
                route_configuration_hash: self.route_configuration_hash,
                payload_hash: self.payload_hash,
                recorded_at_height: self.finality_height,
                commitment_index: self.commitment_index,
            }
        }

        fn is_well_formed_for_admission(
            self,
            destination_proof_commitment: [u8; 32],
            accepted_at_height: u64,
        ) -> bool {
            let hashes = [
                self.key.message_id,
                self.payload_hash,
                self.destination_binding_hash,
                self.route_configuration_hash,
                self.finality_block_hash,
                destination_proof_commitment,
            ];
            accepted_at_height >= self.finality_height
                && self.descriptor().is_well_formed_for_key(&self.key)
                && hashes.iter().all(|hash| hash.iter().any(|byte| *byte != 0))
                && hashes
                    .iter()
                    .enumerate()
                    .all(|(index, hash)| !hashes[index + 1..].contains(hash))
        }
    }
    #[derive(Clone, Debug)]
    struct PreparedSccpOutboundTerminalTransitionV1 {
        key: iroha_data_model::bridge::SccpOutboundMessageKeyV1,
        pending: iroha_data_model::bridge::SccpOutboundPendingMessageRecordV1,
        index: iroha_data_model::bridge::SccpOutboundMessageIndexKeyV1,
        next_usage: iroha_data_model::bridge::SccpOutboundPendingUsageV1,
    }
    fn validate_sccp_destination_bridge_proof(
        proof: &iroha_data_model::bridge::BridgeProof,
        destination_proof: &iroha_data_model::bridge::BridgeSccpDestinationProofV1,
        parsed: iroha_sccp::SccpParsedDestinationProofV1,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<ValidatedSccpOutboundProofV1, Error> {
        let bundle = parsed.bundle();
        if iroha_sccp::sccp_message_source_domain(&bundle.payload) != iroha_sccp::SCCP_DOMAIN_SORA {
            return Err(invalid_bridge_proof(
                "SCCP destination proof bundle is not a structurally valid SORA-origin message",
            ));
        }
        let iroha_sccp::SccpPayloadV1::Transfer(transfer) = &bundle.payload;
        let context = bundle.commitment.context;
        let local_network = sccp_local_sora_network_for_chain_id(&state_transaction.chain_id)
            .ok_or_else(|| {
                invalid_bridge_proof(format!(
                    "SCCP local chain id `{}` is not a canonical public SORA chain id",
                    state_transaction.chain_id
                ))
            })?;
        if context.lane.source != local_network {
            return Err(invalid_bridge_proof(
                "SCCP destination proof context does not originate on this exact SORA profile",
            ));
        }
        let key = state_transaction
            .world
            .sccp_outbound_message_locator
            .get(&bundle.commitment.message_id)
            .copied()
            .ok_or_else(|| {
                invalid_bridge_proof(
                    "SCCP destination proof has no finalized global outbound message locator",
                )
            })?;
        if key.lane != context.lane {
            return Err(invalid_bridge_proof(
                "SCCP destination proof lane differs from its global outbound locator",
            ));
        }
        let record = state_transaction
            .world
            .sccp_outbound_pending_messages
            .get(&key)
            .cloned()
            .ok_or_else(|| {
                invalid_bridge_proof(
                    "SCCP destination proof locator names no pending authoritative payload record",
                )
            })?;
        let outbox_projection = crate::bridge::validate_sccp_outbound_message_record_v1(
            &key, &record,
        )
        .ok_or_else(|| {
            invalid_bridge_proof(
                "SCCP destination proof names malformed authoritative outbox payload evidence",
            )
        })?;
        if outbox_projection.commitment != bundle.commitment
            || outbox_projection.payload != bundle.payload
            || destination_proof.route_configuration_hash != record.route_configuration_hash
        {
            return Err(invalid_bridge_proof(
                "SCCP destination proof does not match its durable payload, destination binding, or exact route configuration",
            ));
        }
        if !destination_proof.is_well_formed_for(
            record.destination_binding_hash,
            parsed.artifact().result.result_hash,
        ) {
            return Err(invalid_bridge_proof(
                "SCCP destination proof aliases its binding, route configuration, or artifact commitments",
            ));
        }
        let route = state_transaction
            .sccp_registry
            .historical_route_by_destination_binding(record.destination_binding_hash)
            .ok_or_else(|| {
                invalid_bridge_proof(
                    "SCCP destination proof binding has no retained historical governed route",
                )
            })?;
        let configuration_route = state_transaction
            .sccp_registry
            .historical_route_by_configuration(record.route_configuration_hash)
            .ok_or_else(|| {
                invalid_bridge_proof(
                    "SCCP destination proof configuration has no retained historical governed route",
                )
            })?;
        let expected_outbound_lane = iroha_data_model::bridge::SccpLaneIdV1 {
            source: route.lane_id.target,
            target: route.lane_id.source,
        };
        if configuration_route.key() != route.key()
            || expected_outbound_lane != context.lane
            || route.route_id.as_bytes() != transfer.route_id
            || route.asset_key.as_bytes() != transfer.asset_id
            || route.revision != transfer.route_revision
        {
            return Err(invalid_bridge_proof(
                "SCCP destination proof payload or configuration selects another route revision",
            ));
        }
        validate_sccp_bridge_proof_range(proof, parsed.finality().finality_artifact.height)?;
        let trusted_finality = validate_sccp_finality_against_state(&parsed, state_transaction)?;
        let artifact = iroha_sccp::verify_parsed_sccp_destination_proof_v1(
            parsed,
            route,
            &trusted_finality,
        )
        .ok_or_else(|| {
            invalid_bridge_proof(
                "SCCP destination artifact failed exact governed request, key, pairing, finality, proof, or material validation",
            )
        })?;
        if record.recorded_at_height != artifact.public_inputs().finality_height {
            return Err(invalid_bridge_proof(
                "SCCP destination proof finality height differs from the authoritative outbound record height",
            ));
        }
        Ok(ValidatedSccpOutboundProofV1 {
            key,
            payload_hash: record.payload_hash,
            destination_binding_hash: record.destination_binding_hash,
            route_configuration_hash: record.route_configuration_hash,
            finality_height: artifact.public_inputs().finality_height,
            commitment_index: record.commitment_index,
            finality_block_hash: artifact.public_inputs.finality_block_hash,
        })
    }
    #[derive(Debug)]
    enum SccpInboundSettlementV1 {
        Transfer(crate::smartcontracts::isi::asset::isi::PreparedSccpInboundNumericAssetRelease),
    }
    #[derive(Debug)]
    struct ValidatedSccpNativeBridgeMessageV1 {
        admission: iroha_sccp::ValidatedSccpNativeInboundMessageV1,
        route_configuration_hash: [u8; 32],
        settlement: SccpInboundSettlementV1,
        replay_accumulator_id: iroha_data_model::bridge::SccpReplayAccumulatorIdV1,
        replay_domain: iroha_data_model::bridge::SccpReplayDomainV1,
        replay_record: iroha_data_model::bridge::SccpReplayRecordV1,
    }
    fn parse_sccp_taira_recipient_v1(recipient_literal: &str) -> Result<AccountId, Error> {
        let recipient_address = iroha_data_model::account::AccountAddress::parse_encoded(
            recipient_literal,
            Some(iroha_sccp::SCCP_TAIRA_I105_DISCRIMINANT_V1),
        )
        .map_err(|error| {
            invalid_bridge_proof(format!(
                "SCCP inbound SORA recipient is not an exact Taira I105 address: {error}"
            ))
        })?;
        let canonical_recipient = recipient_address
            .to_i105_for_discriminant(iroha_sccp::SCCP_TAIRA_I105_DISCRIMINANT_V1)
            .map_err(|error| {
                invalid_bridge_proof(format!(
                    "SCCP inbound SORA recipient cannot be rendered canonically: {error}"
                ))
            })?;
        if canonical_recipient != recipient_literal {
            return Err(invalid_bridge_proof(
                "SCCP inbound SORA recipient must use its exact canonical Taira I105 spelling",
            ));
        }
        let recipient = recipient_address.to_account_id().map_err(|error| {
            invalid_bridge_proof(format!(
                "SCCP inbound SORA recipient controller is invalid: {error}"
            ))
        })?;
        let Some(recipient_key) = recipient.try_signatory() else {
            return Err(invalid_bridge_proof(
                "SCCP inbound SORA recipient must use a single-key Ed25519 controller",
            ));
        };
        if recipient_key.algorithm() != Algorithm::Ed25519 {
            return Err(invalid_bridge_proof(
                "SCCP inbound SORA recipient must use a single-key Ed25519 controller",
            ));
        }
        Ok(recipient)
    }
    fn validate_sccp_native_protocol_bridge_proof(
        proof: &iroha_data_model::bridge::BridgeProof,
        native: &iroha_data_model::bridge::BridgeNativeProtocolProofV1,
        decoded: iroha_sccp::SccpNativeInboundMessageProofV1,
        proof_size: usize,
        verifier_work: crate::state::SccpVerifierWorkV1,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<ValidatedSccpNativeBridgeMessageV1, Error> {
        let decoded_backend = decoded.source.proof.backend();
        if native.backend != decoded_backend {
            return Err(invalid_bridge_proof(
                "SCCP native bridge container backend does not match its typed proof variant",
            ));
        }
        let local_network = sccp_local_sora_network_for_chain_id(&state_transaction.chain_id)
            .ok_or_else(|| {
                invalid_bridge_proof(format!(
                    "SCCP native settlement is unavailable on non-canonical chain id `{}`",
                    state_transaction.chain_id
                ))
            })?;
        if decoded.source.lane.target != local_network {
            return Err(invalid_bridge_proof(
                "SCCP native proof targets a different exact SORA profile",
            ));
        }
        if !decoded.source.lane.is_well_formed()
            || !decoded.source.lane.source.is_external()
            || !decoded.source.lane.target.is_sora()
            || decoded.source.message_id.iter().all(|byte| *byte == 0)
        {
            return Err(invalid_bridge_proof(
                "SCCP native message cannot form an exact replay identity",
            ));
        }
        let iroha_sccp::SccpPayloadV1::Transfer(transfer) = &decoded.payload;
        let governed_lane = state_transaction
            .sccp_registry
            .lane(decoded.source.lane)
            .ok_or_else(|| {
                invalid_bridge_proof(format!(
                    "SCCP native proof lane {} -> {} is not active in the on-chain registry",
                    decoded.source.lane.source.profile_key(),
                    decoded.source.lane.target.profile_key(),
                ))
            })?;
        let submitted_anchor = decoded.source.trust_anchor;
        let (governed_anchor, inclusive_successor_boundary) = state_transaction
            .sccp_registry
            .native_trust_anchor_interval(decoded.source.lane, submitted_anchor.anchor_hash)
            .ok_or_else(|| {
                invalid_bridge_proof(
                    "SCCP native proof names an unknown historical lane trust anchor",
                )
            })?;
        if *governed_anchor != submitted_anchor {
            return Err(invalid_bridge_proof(
                "SCCP native proof forges governed historical trust-anchor material",
            ));
        }
        if governed_anchor.backend != native.backend {
            return Err(invalid_bridge_proof(
                "SCCP native proof backend does not match its governed historical lane anchor",
            ));
        }
        let route = resolve_sccp_settlement_route(
            state_transaction.sccp_registry.as_ref(),
            &state_transaction.network_id,
            governed_lane.lane_id,
            &transfer.route_id,
            &transfer.asset_id,
            transfer.route_revision,
            true,
            Some(decoded.source.source_identity_hash),
            local_network,
        )?;
        if native.route_configuration_hash == decoded.source.source_identity_hash
            || native.route_configuration_hash == governed_anchor.anchor_hash
            || native.route_configuration_hash == decoded.source.message_id
            || native.route_configuration_hash == decoded.source.payload_hash
            || native.route_configuration_hash == decoded.source.source_event_digest
            || native.route_configuration_hash == decoded.source.source_finality.block_hash
        {
            return Err(invalid_bridge_proof(
                "SCCP native route configuration aliases another authenticated hash role",
            ));
        }
        if native.route_configuration_hash != route.route_configuration_hash {
            return Err(invalid_bridge_proof(
                "SCCP native bridge proof binding does not equal the exact historical route configuration",
            ));
        }
        let governed_route = (*state_transaction
            .sccp_registry
            .route(&route.route_key)
            .expect("resolved historical route exists in the validated registry"))
        .clone();
        let governed_anchor = *governed_anchor;
        let (settlement, replay_principal) = {
            validate_sccp_route_fields_match_manifest(
                transfer.route_id_codec,
                &transfer.route_id,
                transfer.asset_id_codec,
                &transfer.asset_id,
                transfer.route_revision,
                &route,
            )?;
            if transfer.source_domain != decoded.source.lane.source.domain_id()
                || transfer.dest_domain != iroha_sccp::SCCP_DOMAIN_SORA
                || transfer.asset_home_domain != iroha_sccp::SCCP_DOMAIN_SORA
            {
                return Err(invalid_bridge_proof(
                    "first-release SCCP inbound transfer must move a SORA-home asset from the exact external lane to SORA",
                ));
            }
            let local_account_codec =
                iroha_sccp::sccp_counterparty_account_codec(iroha_sccp::SCCP_DOMAIN_SORA)
                    .expect("SORA account codec is defined by the SCCP profile");
            if transfer.sender_codec != route.counterparty_account_codec
                || transfer.recipient_codec != local_account_codec
            {
                return Err(invalid_bridge_proof(
                    "SCCP inbound sender/recipient codecs do not match the exact external and SORA profiles",
                ));
            }
            let recipient_literal = core::str::from_utf8(&transfer.recipient).map_err(|_| {
                invalid_bridge_proof("SCCP inbound SORA recipient is not valid UTF-8")
            })?;
            let recipient = parse_sccp_taira_recipient_v1(recipient_literal)?;
            if recipient == route.escrow_account_id {
                return Err(invalid_bridge_proof(
                    "SCCP inbound recipient must differ from the route protocol escrow",
                ));
            }
            state_transaction
                .world
                .asset_definition(&route.settlement_asset_definition_id)?;
            state_transaction.world.account(&route.escrow_account_id)?;
            let amount = sccp_payload_amount(transfer.amount, &route)?;
            let prepared =
                crate::smartcontracts::isi::asset::isi::prepare_sccp_inbound_numeric_asset_release(
                    state_transaction,
                    &route.route_key,
                    recipient.clone(),
                    transfer.amount,
                    amount,
                )?;
            (SccpInboundSettlementV1::Transfer(prepared), recipient)
        };
        // Ledger-domain failures are completely determined before this reservation. From this
        // point onward, rejected source proofs intentionally consume their deterministic work
        // allowance so repeated invalid cryptography cannot bypass transaction quotas.
        state_transaction.register_sccp_proof(proof_size, verifier_work)?;
        let validated = iroha_sccp::verify_sccp_native_inbound_message_proof_v1(
            &decoded,
            &governed_route.source_identity,
            governed_anchor,
        )
        .map_err(|error| {
            invalid_bridge_proof(format!("SCCP native source verification failed: {error}"))
        })?;
        if !governed_anchor.admits_anchor_interval_height(
            validated.anchor_interval_height,
            inclusive_successor_boundary,
        ) {
            return Err(invalid_bridge_proof(format!(
                "SCCP native proof consensus progress {} is outside the governed trust-anchor interval",
                validated.anchor_interval_height
            )));
        }
        if !governed_route.allows_inbound_at(validated.anchor_interval_height) {
            return Err(invalid_bridge_proof(
                "SCCP native proof is above the retired route's authenticated anchor-interval cutoff",
            ));
        }
        if proof.range.start_height != validated.source_finality.height
            || proof.range.end_height != validated.source_finality.height
        {
            return Err(invalid_bridge_proof(format!(
                "SCCP native proof range must equal authenticated event/source finality height {}",
                validated.source_finality.height
            )));
        }
        let replay_accumulator_id = iroha_data_model::bridge::SccpReplayAccumulatorIdV1 {
            route_key: route.route_key.clone(),
            boundary: iroha_data_model::bridge::SccpReplayBoundaryV1::SoraInboundRelease,
        };
        let replay_domain = iroha_data_model::bridge::SccpReplayDomainV1 {
            source_network: decoded.source.lane.source,
            target_network: decoded.source.lane.target,
            boundary: iroha_data_model::bridge::SccpReplayBoundaryV1::SoraInboundRelease,
            route_revision: route.route_key.revision,
            route_configuration_hash: route.route_configuration_hash,
            actor: iroha_data_model::bridge::SccpReplayActorV1::Route,
        };
        let canonical_payload_bytes = iroha_sccp::canonical_sccp_payload_bytes(&decoded.payload)
            .map_err(|_| {
                invalid_bridge_proof(
                    "verified SCCP native payload could not be re-encoded canonically",
                )
            })?;
        let replay_record = iroha_data_model::bridge::SccpReplayRecordV1 {
            operation: iroha_data_model::bridge::SccpReplayBoundaryV1::SoraInboundRelease,
            replay_id: validated.message_id,
            payload_sha256: sha2::Sha256::digest(canonical_payload_bytes).into(),
            amount: transfer.amount,
            principal: iroha_data_model::bridge::SccpReplayPrincipalV1::SoraAccount(
                replay_principal,
            ),
            auxiliary_identity_sha256: sha2::Sha256::digest(validated.source_event_digest).into(),
        };
        Ok(ValidatedSccpNativeBridgeMessageV1 {
            admission: validated,
            route_configuration_hash: route.route_configuration_hash,
            settlement,
            replay_accumulator_id,
            replay_domain,
            replay_record,
        })
    }
    fn sccp_bsc_native_verifier_work(
        estimate: iroha_sccp::BscNativeFinalityWorkEstimateV1,
    ) -> crate::state::SccpVerifierWorkV1 {
        crate::state::SccpVerifierWorkV1 {
            native_headers: u64::from(estimate.continuation_headers),
            native_header_bytes: u64::from(estimate.framed_header_bytes),
            secp256k1_recoveries: u64::from(estimate.secp256k1_recoveries),
            bls_aggregate_checks: u64::from(estimate.bls_aggregate_checks_upper_bound),
            bls_signer_contributions: u64::from(estimate.bls_signer_contributions_upper_bound),
            ..crate::state::SccpVerifierWorkV1::default()
        }
    }
    /// Project BSC verifier-work counters through the production mapper for isolated tests.
    #[cfg(any(test, feature = "iroha-core-tests"))]
    #[doc(hidden)]
    #[must_use]
    pub fn sccp_bsc_native_verifier_work_fields_for_testing(
        estimate: iroha_sccp::BscNativeFinalityWorkEstimateV1,
    ) -> [u64; 5] {
        let work = sccp_bsc_native_verifier_work(estimate);
        [
            work.native_headers,
            work.native_header_bytes,
            work.secp256k1_recoveries,
            work.bls_aggregate_checks,
            work.bls_signer_contributions,
        ]
    }
    fn sccp_native_verifier_work(
        decoded: &iroha_sccp::SccpNativeInboundMessageProofV1,
        encoded_envelope_len: usize,
    ) -> Result<crate::state::SccpVerifierWorkV1, Error> {
        use iroha_sccp::SccpNativeSourceProofV1;
        match &decoded.source.proof {
            SccpNativeSourceProofV1::EthereumBeacon(proof) => {
                let updates = u64::try_from(proof.updates.len()).map_err(|_| {
                    invalid_bridge_proof("SCCP Ethereum light-client update count overflows u64")
                })?;
                if proof.updates.len() > iroha_sccp::ETHEREUM_NATIVE_MAX_LIGHT_CLIENT_UPDATES {
                    return Err(invalid_bridge_proof(format!(
                        "SCCP Ethereum native proof has too many light-client updates ({} > {})",
                        proof.updates.len(),
                        iroha_sccp::ETHEREUM_NATIVE_MAX_LIGHT_CLIENT_UPDATES,
                    )));
                }
                // A trusted anchor validates 512 committee keys plus its aggregate key. Every
                // update validates another complete next committee and may aggregate all 512
                // current-committee participants. Reserve the upper bound before entering the
                // light-client verifier; malformed short committees cannot increase this cost.
                let bls_signer_contributions = updates
                    .checked_mul(1_025)
                    .and_then(|value| value.checked_add(513))
                    .ok_or_else(|| {
                        invalid_bridge_proof("SCCP Ethereum BLS work estimate overflow")
                    })?;
                let native_header_bytes = u64::try_from(encoded_envelope_len).map_err(|_| {
                    invalid_bridge_proof("SCCP Ethereum native proof byte count overflows u64")
                })?;
                Ok(crate::state::SccpVerifierWorkV1 {
                    ethereum_light_client_updates: updates,
                    native_header_bytes,
                    bls_aggregate_checks: updates,
                    bls_signer_contributions,
                    ..crate::state::SccpVerifierWorkV1::default()
                })
            }
            SccpNativeSourceProofV1::BscParlia(proof) => {
                let estimate = iroha_sccp::bsc_native_finality_work_estimate(&proof.finality)
                    .map_err(|error| {
                        invalid_bridge_proof(format!(
                            "SCCP BSC native proof exceeds verifier work bounds: {error:?}"
                        ))
                    })?;
                Ok(sccp_bsc_native_verifier_work(estimate))
            }
            SccpNativeSourceProofV1::TronDpos(proof) => {
                let estimate = iroha_sccp::tron_native_finality_work_estimate(&proof.finality)
                    .map_err(|error| {
                        invalid_bridge_proof(format!(
                            "SCCP TRON native proof exceeds verifier work bounds: {error:?}"
                        ))
                    })?;
                Ok(crate::state::SccpVerifierWorkV1 {
                    native_headers: u64::from(estimate.continuation_headers),
                    native_header_bytes: u64::from(estimate.framed_header_bytes),
                    secp256k1_recoveries: u64::from(estimate.secp256k1_recoveries),
                    ..crate::state::SccpVerifierWorkV1::default()
                })
            }
            SccpNativeSourceProofV1::TonMasterchain(proof) => {
                let estimate =
                    iroha_sccp::ton_native_source_work_estimate(proof).map_err(|error| {
                        invalid_bridge_proof(format!(
                            "SCCP TON native proof exceeds verifier work bounds: {error:?}"
                        ))
                    })?;
                Ok(crate::state::SccpVerifierWorkV1 {
                    native_headers: u64::from(estimate.continuation_blocks),
                    native_header_bytes: u64::from(estimate.framed_boc_bytes),
                    ed25519_signature_checks: u64::from(estimate.ed25519_signature_checks),
                    ed25519_validator_key_checks: u64::from(
                        estimate.validator_key_checks_upper_bound,
                    ),
                    ..crate::state::SccpVerifierWorkV1::default()
                })
            }
        }
    }
    struct ValidatedBridgeProof {
        encoded: Vec<u8>,
        size_bytes: u32,
        outbound_proof: Option<ValidatedSccpOutboundProofV1>,
        native_message: Option<ValidatedSccpNativeBridgeMessageV1>,
    }
    fn find_bridge_range_overlap_conflict(
        state_transaction: &StateTransaction<'_, '_>,
        backend: &str,
        new_range: &iroha_data_model::bridge::BridgeProofRange,
        is_closed_sccp: bool,
    ) -> Option<iroha_data_model::proof::ProofId> {
        if is_closed_sccp {
            return None;
        }
        find_overlapping_bridge_range(state_transaction, backend, new_range)
    }
    fn encode_bridge_proof_identity(
        proof: &iroha_data_model::bridge::BridgeProof,
    ) -> Result<Vec<u8>, Error> {
        norito::encode_canonical(proof).map_err(|err| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                format!("failed to encode bridge proof: {err}"),
            ))
            .into()
        })
    }
    fn encode_and_validate_bridge_proof(
        proof: &iroha_data_model::bridge::BridgeProof,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<ValidatedBridgeProof, Error> {
        let zk_cfg = &state_transaction.zk;
        let current_height = state_transaction._curr_block.height.get();
        if !proof.range.is_valid() {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "bridge proof range must satisfy start_height <= end_height".into(),
                ),
            ));
        }
        if !proof.binding().is_well_formed() {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "bridge proof payload binding must not be all zeros".into(),
                ),
            ));
        }
        let range_len = proof.range.len();
        let max_range = zk_cfg.bridge_proof_max_range_len;
        if max_range > 0 && range_len > max_range {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(format!(
                    "bridge proof range too large ({range_len} > {max_range})"
                )),
            ));
        }
        // Closed SCCP proofs carry heights whose validity is established by their own exact
        // finality anchors. Native heights live in an external chain's namespace; destination
        // proofs may legitimately settle an old, finalized SORA outbox record long after the
        // generic proof window. Comparing either with the current admission height would reject
        // valid proofs as the ledgers advance independently. Their variant-specific validation
        // below binds the range to authenticated finality and durable local records. Only generic
        // ICS/ZK proofs retain the Iroha-relative age policy.
        validate_bridge_proof_height_window(
            proof,
            current_height,
            zk_cfg.bridge_proof_max_past_age_blocks,
            zk_cfg.bridge_proof_max_future_drift_blocks,
        )?;
        let encoded = encode_bridge_proof_identity(proof)?;
        let proof_size = encoded.len();
        let size_bytes = canonical_bridge_proof_size_bytes(proof_size)?;
        let is_closed_sccp = matches!(
            &proof.payload,
            iroha_data_model::bridge::BridgeProofPayload::SccpDestination(_)
                | iroha_data_model::bridge::BridgeProofPayload::NativeProtocol(_)
        );
        let max_bytes = if is_closed_sccp {
            usize::try_from(zk_cfg.sccp.max_proof_bytes_per_proof.get()).unwrap_or(usize::MAX)
        } else {
            zk_cfg.max_proof_size_bytes as usize
        };
        if max_bytes > 0 && proof_size > max_bytes {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(format!(
                    "bridge proof exceeds its configured per-proof byte cap ({proof_size} > {max_bytes})"
                )),
            ));
        }
        let backend_label = proof.backend_label();
        let proof_id = iroha_data_model::proof::ProofId {
            backend: backend_label.clone(),
            proof_hash: hash_bridge_proof(&backend_label, &encoded),
        };
        if state_transaction.world.proofs.get(&proof_id).is_some() {
            let message = match &proof.payload {
                iroha_data_model::bridge::BridgeProofPayload::SccpDestination(_) => {
                    "an SCCP destination proof for this exact outbound lane and message has already been accepted"
                }
                iroha_data_model::bridge::BridgeProofPayload::NativeProtocol(_) => {
                    "SCCP native message has already been admitted on this exact lane"
                }
                iroha_data_model::bridge::BridgeProofPayload::Ics(_)
                | iroha_data_model::bridge::BridgeProofPayload::TransparentZk(_) => {
                    "bridge proof has already been recorded"
                }
            };
            return Err(invalid_bridge_proof(message));
        }
        if is_closed_sccp {
            // Reject exhausted count/byte quotas before any proof-controlled canonical decode.
            // Full registration repeats this check atomically with the derived crypto work.
            state_transaction.preflight_sccp_proof(proof_size)?;
        }
        let (outbound_proof, native_message) = match &proof.payload {
            iroha_data_model::bridge::BridgeProofPayload::Ics(_) => {
                return Err(invalid_bridge_proof(
                    "generic ICS bridge proof submission is unavailable until an authoritative on-chain verifier is implemented",
                ));
            }
            iroha_data_model::bridge::BridgeProofPayload::TransparentZk(_) => {
                return Err(invalid_bridge_proof(
                    "generic transparent bridge proof submission is unavailable until an authoritative on-chain verifier is implemented",
                ));
            }
            iroha_data_model::bridge::BridgeProofPayload::SccpDestination(destination) => {
                let parsed = iroha_sccp::parse_sccp_destination_proof_v1(destination)
                    .ok_or_else(|| {
                        invalid_bridge_proof(
                            "SCCP destination proof or its embedded message/finality bundle is non-canonical or internally inconsistent",
                        )
                    })?;
                // Reserve two full Taira-roster passes before validating proof-controlled keys:
                // one for key/hash reconstruction, one for worst-case signer PoP/aggregation.
                // Bounded parsing exposes the replay key, so exact replay consumes no verifier work.
                // The one-proof transaction cap prevents this conservative reservation from
                // crowding out another legitimate proof.
                let (bn254_pairing_checks, bls12_381_pairing_checks) = match parsed.crypto_work() {
                    iroha_sccp::SccpDestinationProofCryptoWorkV1::Groth16Bn254Pairing => (1, 0),
                    iroha_sccp::SccpDestinationProofCryptoWorkV1::Groth16Bls12381Pairing => (0, 1),
                };
                state_transaction.register_sccp_proof(
                    proof_size,
                    crate::state::SccpVerifierWorkV1 {
                        bls_aggregate_checks: 1,
                        bls_signer_contributions: u64::try_from(
                            iroha_sccp::SCCP_TAIRA_MAX_FINALITY_VALIDATORS_V1,
                        )
                        .ok()
                        .and_then(|value| value.checked_mul(2))
                        .ok_or_else(|| {
                            invalid_bridge_proof("SCCP Taira validator work bound overflows u64")
                        })?,
                        bn254_pairing_checks,
                        bls12_381_pairing_checks,
                        ..crate::state::SccpVerifierWorkV1::default()
                    },
                )?;
                let validated_proof = validate_sccp_destination_bridge_proof(
                    proof,
                    destination,
                    parsed,
                    state_transaction,
                )?;
                (Some(validated_proof), None)
            }
            iroha_data_model::bridge::BridgeProofPayload::NativeProtocol(native) => {
                let decoded = iroha_sccp::decode_sccp_native_inbound_message_proof_v1(
                    &native.encoded_envelope,
                )
                .map_err(|error| {
                    invalid_bridge_proof(format!(
                        "SCCP native protocol proof is not canonical: {error}"
                    ))
                })?;
                let work = sccp_native_verifier_work(&decoded, native.encoded_envelope.len())?;
                let validated = validate_sccp_native_protocol_bridge_proof(
                    proof,
                    native,
                    decoded,
                    proof_size,
                    work,
                    state_transaction,
                )?;
                (None, Some(validated))
            }
        };
        Ok(ValidatedBridgeProof {
            encoded,
            size_bytes,
            outbound_proof,
            native_message,
        })
    }
    struct BridgeProofEventArgs<'a> {
        pid: &'a iroha_data_model::proof::ProofId,
        call_hash: Option<[u8; 32]>,
        envelope_hash: Option<[u8; 32]>,
        prune_outcome: Option<ProofPruneOutcome>,
        cap: usize,
        grace_blocks: u64,
        prune_batch: usize,
        height: u64,
        authority: &'a AccountId,
    }
    fn bridge_proof_events(
        args: BridgeProofEventArgs<'_>,
    ) -> Vec<iroha_data_model::events::data::proof::ProofEvent> {
        use iroha_data_model::events::data::proof::{
            ProofEvent, ProofPruneOrigin, ProofPruned, ProofVerified,
        };
        let mut events = Vec::new();
        events.push(ProofEvent::Verified(ProofVerified {
            id: args.pid.clone(),
            vk_ref: None,
            vk_commitment: None,
            call_hash: args.call_hash,
            envelope_hash: args.envelope_hash,
        }));
        if let Some(outcome) = args.prune_outcome {
            events.push(ProofEvent::Pruned(ProofPruned {
                backend: outcome.backend,
                removed: outcome.removed,
                remaining: outcome.remaining,
                cap: args.cap as u64,
                grace_blocks: args.grace_blocks,
                prune_batch: args.prune_batch as u64,
                pruned_at_height: args.height,
                pruned_by: args.authority.clone(),
                origin: ProofPruneOrigin::Insert,
            }));
        }
        events
    }
    fn execute_sccp_inbound_settlement(
        settlement: SccpInboundSettlementV1,
        submitting_authority: &AccountId,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        match settlement {
            SccpInboundSettlementV1::Transfer(prepared) =>
                crate::smartcontracts::isi::asset::isi::apply_prepared_sccp_inbound_numeric_asset_release(
                    state_transaction,
                    submitting_authority,
                    prepared,
                ),
        }
    }
    impl Execute for zk::VerifyProof {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let attachment = self.attachment().clone();
            let proof = attachment.proof.clone();
            let envelope_meta = decode_open_verify_envelope(&proof);
            let backend_label = attachment.backend.as_str();
            let expects_envelope = backend_requires_open_verify_envelope(backend_label);
            let envelope_ref = validate_proof_attachment(
                &attachment,
                &proof,
                expects_envelope,
                envelope_meta.as_ref(),
            )?;
            state_transaction.register_confidential_proof(proof.bytes.len())?;
            let vk_commitment =
                resolve_vk_commitment(&attachment, envelope_ref, state_transaction)?;
            let pid = iroha_data_model::proof::ProofId {
                backend: attachment.backend.clone(),
                proof_hash: crate::zk::hash_proof(&proof),
            };
            ensure_unique_proof(state_transaction, &pid)?;
            let (ok, verify_elapsed) =
                verify_proof_backend(&attachment, &proof, state_transaction)?;
            let status = if ok {
                iroha_data_model::proof::ProofStatus::Verified
            } else {
                iroha_data_model::proof::ProofStatus::Rejected
            };
            #[cfg(feature = "telemetry")]
            {
                let latency_ms = u64::try_from(verify_elapsed.as_millis()).unwrap_or(u64::MAX);
                let proof_bytes = proof.bytes.len();
                state_transaction.telemetry.record_zk_verify(
                    attachment.backend.as_str(),
                    status,
                    proof_bytes,
                    latency_ms,
                );
            }
            #[cfg(not(feature = "telemetry"))]
            let _ = &verify_elapsed;
            index_proof_tags(&mut state_transaction.world, &pid, &proof.bytes);
            let height = state_transaction._curr_block.height.get();
            let call_hash_opt: Option<[u8; 32]> = state_transaction
                .tx_call_hash
                .as_ref()
                .map(|h| <[u8; 32]>::from(*h));
            let record = iroha_data_model::proof::ProofRecord {
                id: pid.clone(),
                vk_ref: Some(attachment.vk_ref.clone()),
                vk_commitment,
                status,
                verified_at_height: Some(height),
                bridge: None,
            };
            state_transaction.world.insert_proof_record(record);
            let cap = state_transaction.zk.proof_history_cap;
            let prune_outcome = enforce_proof_history_cap(
                state_transaction,
                backend_label,
                cap,
                state_transaction.zk.proof_retention_grace_blocks,
                state_transaction.zk.proof_prune_batch,
                height,
            );
            let events = proof_events_for_result(
                ok,
                ProofEventArgs {
                    pid: &pid,
                    attachment: &attachment,
                    vk_commitment,
                    call_hash: call_hash_opt,
                    prune_outcome,
                    cap,
                    grace_blocks: state_transaction.zk.proof_retention_grace_blocks,
                    prune_batch: state_transaction.zk.proof_prune_batch,
                    height,
                    authority,
                },
            );
            state_transaction.world.emit_events(events);
            Ok(())
        }
    }
    impl Execute for zk::PruneProofs {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::events::data::proof::{
                ProofEvent, ProofPruneOrigin, ProofPruned,
            };
            use std::collections::BTreeSet;
            let cap = state_transaction.zk.proof_history_cap;
            let grace = state_transaction.zk.proof_retention_grace_blocks;
            let prune_batch = state_transaction.zk.proof_prune_batch;
            let height = state_transaction._curr_block.height.get();
            let mut backends: BTreeSet<String> = BTreeSet::new();
            if let Some(spec) = &self.backend {
                backends.insert(spec.clone());
            } else {
                for (id, _) in state_transaction.world.proofs.iter() {
                    backends.insert(id.backend.clone());
                }
            }
            let mut events = Vec::new();
            for backend in backends {
                if let Some(outcome) = enforce_proof_history_cap(
                    state_transaction,
                    &backend,
                    cap,
                    grace,
                    prune_batch,
                    height,
                ) {
                    events.push(ProofEvent::Pruned(ProofPruned {
                        backend: outcome.backend,
                        removed: outcome.removed,
                        remaining: outcome.remaining,
                        cap: cap as u64,
                        grace_blocks: grace,
                        prune_batch: prune_batch as u64,
                        pruned_at_height: height,
                        pruned_by: authority.clone(),
                        origin: ProofPruneOrigin::Manual,
                    }));
                }
            }
            if !events.is_empty() {
                state_transaction.world.emit_events(events);
            }
            Ok(())
        }
    }
    impl Execute for bridge::SubmitBridgeProof {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let is_native_sccp = matches!(
                &self.proof.payload,
                iroha_data_model::bridge::BridgeProofPayload::NativeProtocol(_)
            );
            if is_native_sccp {
                let replay_witness = self.replay_witness.as_ref().ok_or_else(|| {
                    invalid_bridge_proof(
                        "SCCP native claim requires a canonical replay non-membership witness",
                    )
                })?;
                if replay_witness.prior_record_digest != [0; 32]
                    || replay_witness.validate().is_err()
                {
                    return Err(invalid_bridge_proof(
                        "SCCP native claim requires a canonical replay non-membership witness",
                    ));
                }
                state_transaction
                    .require_transfer_transcript_identity("SCCP native inbound settlement")?;
            } else if self.replay_witness.is_some() {
                return Err(invalid_bridge_proof(
                    "only an SCCP native claim may carry a replay witness",
                ));
            }
            let current_height = state_transaction._curr_block.height.get();
            let validated = encode_and_validate_bridge_proof(&self.proof, state_transaction)?;
            let proof_size = validated.size_bytes;
            let outbound_proof = validated.outbound_proof;
            let native_message = validated.native_message;
            let is_closed_sccp = outbound_proof.is_some() || native_message.is_some();
            let backend_label = self.proof.backend_label();
            let commitment = hash_bridge_proof(&backend_label, &validated.encoded);
            let pid = iroha_data_model::proof::ProofId {
                backend: backend_label.clone(),
                proof_hash: commitment,
            };
            if state_transaction.world.proofs.get(&pid).is_some() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "bridge proof has already been recorded".into(),
                    ),
                ));
            }
            let outbound_proof_descriptor = if let Some(validated_proof) = outbound_proof {
                if !validated_proof.is_well_formed_for_admission(commitment, current_height) {
                    return Err(invalid_bridge_proof(
                        "validated SCCP destination proof produced an invalid terminal descriptor",
                    ));
                }
                Some((validated_proof.key, validated_proof.descriptor()))
            } else {
                None
            };
            let outbound_terminal_transition = if let Some((key, descriptor)) =
                outbound_proof_descriptor
            {
                let pending = state_transaction
                    .world
                    .sccp_outbound_pending_messages
                    .get(&key)
                    .cloned()
                    .ok_or_else(|| {
                        InstructionExecutionError::InvariantViolation(
                            "validated SCCP destination proof lost its pending payload record"
                                .into(),
                        )
                    })?;
                if pending.descriptor() != descriptor {
                    return Err(InstructionExecutionError::InvariantViolation(
                            "validated SCCP destination proof descriptor changed before terminal transition"
                                .into(),
                        ));
                }
                let expected_index =
                    iroha_data_model::bridge::SccpOutboundMessageIndexKeyV1::new(key, &pending)
                        .ok_or_else(|| {
                            InstructionExecutionError::InvariantViolation(
                                "validated SCCP pending payload cannot form its ordered index"
                                    .into(),
                            )
                        })?;
                if state_transaction
                    .world
                    .sccp_outbound_message_locator
                    .get(&key.message_id)
                    != Some(&key)
                    || state_transaction
                        .world
                        .sccp_outbound_message_index
                        .get(&expected_index)
                        .is_none()
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "validated SCCP pending payload lost its global locator or ordered index"
                            .into(),
                    ));
                }
                let current_usage = *state_transaction.world.sccp_outbound_pending_usage.get();
                if !current_usage.is_structurally_valid() {
                    return Err(InstructionExecutionError::InvariantViolation(
                            "SCCP pending outbound usage is structurally corrupt during terminal transition"
                                .into(),
                        ));
                }
                let next_usage = current_usage
                    .checked_remove_payload(pending.payload_bytes.len())
                    .ok_or_else(|| {
                        InstructionExecutionError::InvariantViolation(
                            "SCCP pending outbound usage underflow during terminal transition"
                                .into(),
                        )
                    })?;
                if !next_usage.is_structurally_valid() {
                    return Err(InstructionExecutionError::InvariantViolation(
                            "SCCP pending outbound usage became structurally corrupt during terminal transition"
                                .into(),
                        ));
                }
                Some(PreparedSccpOutboundTerminalTransitionV1 {
                    key,
                    pending,
                    index: expected_index,
                    next_usage,
                })
            } else {
                None
            };
            let native_high_water = if let Some(native) = native_message.as_ref() {
                let admission = &native.admission;
                if !admission.lane.is_well_formed()
                    || !admission.lane.source.is_external()
                    || !admission.lane.target.is_sora()
                    || admission.message_id.iter().all(|byte| *byte == 0)
                {
                    return Err(invalid_bridge_proof(
                        "validated SCCP native message produced an invalid replay identity",
                    ));
                }
                let high_water_key =
                    iroha_data_model::bridge::SccpInboundAnchorHighWaterKeyV1::new(
                        admission.lane,
                        admission.trust_anchor.anchor_hash,
                    )
                    .ok_or_else(|| {
                        invalid_bridge_proof(
                            "validated SCCP native message produced an invalid anchor high-water key",
                        )
                    })?;
                Some((high_water_key, admission.anchor_interval_height))
            } else {
                None
            };
            if let Some(conflict) = find_bridge_range_overlap_conflict(
                state_transaction,
                &backend_label,
                &self.proof.range,
                is_closed_sccp,
            ) {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "bridge proof range overlaps existing proof {conflict}"
                    )),
                ));
            }
            ensure_unique_proof(state_transaction, &pid)?;
            let replay_mutation = native_message
                .as_ref()
                .map(|native| {
                    state_transaction.prepare_sccp_replay_leaf(
                        native.replay_accumulator_id.clone(),
                        &native.replay_domain,
                        &native.replay_record,
                        self.replay_witness
                            .as_ref()
                            .expect("native SCCP witness was required before validation"),
                    )
                })
                .transpose()?;
            if let Some(native) = native_message {
                execute_sccp_inbound_settlement(native.settlement, authority, state_transaction)?;
            }
            if let Some(replay_mutation) = replay_mutation {
                state_transaction.apply_sccp_replay_leaf(replay_mutation)?;
            }
            let height = current_height;
            let call_hash_opt: Option<[u8; 32]> = state_transaction
                .tx_call_hash
                .as_ref()
                .map(|h| <[u8; 32]>::from(*h));
            let envelope_hash: Option<[u8; 32]> = Some(<[u8; 32]>::from(iroha_crypto::Hash::new(
                &validated.encoded,
            )));
            let record = iroha_data_model::proof::ProofRecord {
                id: pid.clone(),
                vk_ref: None,
                vk_commitment: None,
                status: iroha_data_model::proof::ProofStatus::Verified,
                verified_at_height: Some(height),
                bridge: Some(iroha_data_model::bridge::BridgeProofRecord {
                    proof: self.proof,
                    commitment,
                    size_bytes: proof_size,
                }),
            };
            state_transaction.world.insert_proof_record(record);
            if let Some(transition) = outbound_terminal_transition {
                let removed = state_transaction
                    .world
                    .sccp_outbound_pending_messages
                    .remove(transition.key);
                debug_assert_eq!(removed.as_ref(), Some(&transition.pending));
                *state_transaction
                    .world
                    .sccp_outbound_pending_usage
                    .get_mut() = transition.next_usage;
                state_transaction
                    .world
                    .sccp_outbound_message_locator
                    .remove(transition.key.message_id);
                state_transaction
                    .world
                    .sccp_outbound_message_index
                    .remove(transition.index);
            }
            if let Some((high_water_key, anchor_interval_height)) = native_high_water {
                let high_water = state_transaction
                    .world
                    .sccp_inbound_anchor_high_water
                    .get(&high_water_key)
                    .copied()
                    .unwrap_or_default()
                    .max(anchor_interval_height);
                state_transaction
                    .world
                    .sccp_inbound_anchor_high_water
                    .insert(high_water_key, high_water);
            }
            state_transaction
                .bridge_receipt_proofs_available_in_tx
                .insert(commitment);
            let cap = state_transaction.zk.proof_history_cap;
            let prune_outcome = enforce_bridge_history_cap(
                state_transaction,
                &backend_label,
                cap,
                state_transaction.zk.proof_retention_grace_blocks,
                state_transaction.zk.proof_prune_batch,
                height,
            );
            let events = bridge_proof_events(BridgeProofEventArgs {
                pid: &pid,
                call_hash: call_hash_opt,
                envelope_hash,
                prune_outcome,
                cap,
                grace_blocks: state_transaction.zk.proof_retention_grace_blocks,
                prune_batch: state_transaction.zk.proof_prune_batch,
                height,
                authority,
            });
            state_transaction.world.emit_events(events);
            Ok(())
        }
    }
    fn verified_bridge_proof_record_for_receipt<'a>(
        receipt: &iroha_data_model::bridge::BridgeReceipt,
        state_transaction: &'a StateTransaction<'_, '_>,
    ) -> Option<(
        &'a iroha_data_model::proof::ProofId,
        &'a iroha_data_model::bridge::BridgeProofRecord,
    )> {
        state_transaction
            .world
            .proofs
            .iter()
            .find_map(|(id, record)| {
                if record.status != iroha_data_model::proof::ProofStatus::Verified {
                    return None;
                }
                if record.id != *id || id.proof_hash != receipt.proof_hash {
                    return None;
                }
                let Some(bridge_record) = &record.bridge else {
                    return None;
                };
                if bridge_record.commitment == receipt.proof_hash
                    && bridge_record.proof.backend_label() == id.backend
                {
                    Some((id, bridge_record))
                } else {
                    None
                }
            })
    }
    fn derive_sccp_bridge_receipt_projection(
        lane: iroha_data_model::nexus::LaneId,
        proof_hash: [u8; 32],
        message: &iroha_sccp::SccpPayloadV1,
        message_id: [u8; 32],
    ) -> iroha_data_model::bridge::BridgeReceipt {
        let iroha_sccp::SccpPayloadV1::Transfer(payload) = message;
        let direction = if payload.asset_home_domain == iroha_sccp::SCCP_DOMAIN_SORA {
            b"release".to_vec()
        } else {
            b"mint".to_vec()
        };
        // Spell every field out so adding another caller-controlled receipt field is a compile
        // error until its authenticated projection is defined here. SCCP V1 authenticates no
        // destination transaction hash, so accepting any `dest_tx` would forge proof provenance.
        iroha_data_model::bridge::BridgeReceipt {
            lane,
            direction,
            source_tx: message_id,
            dest_tx: None,
            proof_hash,
            amount: payload.amount.into(),
            asset_id: payload.asset_id.clone(),
            recipient: payload.recipient.clone(),
        }
    }
    fn derive_bridge_receipt_projection(
        lane: iroha_data_model::nexus::LaneId,
        proof_hash: [u8; 32],
        proof: &iroha_data_model::bridge::BridgeProof,
    ) -> Result<iroha_data_model::bridge::BridgeReceipt, Error> {
        match &proof.payload {
            iroha_data_model::bridge::BridgeProofPayload::NativeProtocol(native) => {
                let decoded = iroha_sccp::decode_bridge_native_protocol_proof_v1(native).map_err(
                    |error| {
                        invalid_bridge_receipt(format!(
                            "SCCP native bridge receipt proof could not be decoded: {error}"
                        ))
                    },
                )?;
                Ok(derive_sccp_bridge_receipt_projection(
                    lane,
                    proof_hash,
                    &decoded.payload,
                    decoded.source.message_id,
                ))
            }
            iroha_data_model::bridge::BridgeProofPayload::SccpDestination(destination) => {
                let parsed =
                    iroha_sccp::parse_sccp_destination_proof_v1(destination).ok_or_else(|| {
                        invalid_bridge_receipt(
                            "SCCP destination receipt proof artifact could not be decoded",
                        )
                    })?;
                let bundle = parsed.bundle();
                Ok(derive_sccp_bridge_receipt_projection(
                    lane,
                    proof_hash,
                    &bundle.payload,
                    bundle.commitment.message_id,
                ))
            }
            iroha_data_model::bridge::BridgeProofPayload::Ics(_)
            | iroha_data_model::bridge::BridgeProofPayload::TransparentZk(_) => {
                Err(invalid_bridge_receipt(
                    "generic bridge proofs have no authenticated receipt projection; only closed SCCP proof variants may emit bridge receipts",
                ))
            }
        }
    }
    fn validate_bridge_receipt_lane_matches_transaction(
        receipt: &iroha_data_model::bridge::BridgeReceipt,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<iroha_data_model::nexus::LaneId, Error> {
        let Some(current_lane_id) = state_transaction.current_lane_id else {
            return Err(invalid_bridge_receipt(
                "bridge receipt requires an active transaction lane",
            ));
        };
        if nexus_active_lane_dataspace(current_lane_id, &state_transaction.nexus).is_none() {
            return Err(invalid_bridge_receipt(format!(
                "bridge receipt requires active Nexus lane {current_lane_id}"
            )));
        }
        if receipt.lane != current_lane_id {
            return Err(invalid_bridge_receipt(format!(
                "bridge receipt lane {} does not match transaction lane {current_lane_id}",
                receipt.lane
            )));
        }
        Ok(current_lane_id)
    }
    fn consume_bridge_receipt_proof(
        receipt: &iroha_data_model::bridge::BridgeReceipt,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let current_lane =
            validate_bridge_receipt_lane_matches_transaction(receipt, state_transaction)?;
        {
            let (proof_id, bridge_record) =
                verified_bridge_proof_record_for_receipt(receipt, state_transaction).ok_or_else(
                    || {
                        invalid_bridge_receipt(
                            "bridge receipt proof_hash does not reference a verified bridge proof",
                        )
                    },
                )?;
            let expected = derive_bridge_receipt_projection(
                current_lane,
                proof_id.proof_hash,
                &bridge_record.proof,
            )?;
            if receipt != &expected {
                return Err(invalid_bridge_receipt(
                    "SCCP bridge receipt does not exactly match the complete proof-derived projection",
                ));
            }
        }
        if !state_transaction
            .bridge_receipt_proofs_available_in_tx
            .remove(&receipt.proof_hash)
        {
            return Err(invalid_bridge_receipt(
                "bridge receipt requires a newly recorded bridge proof in the same transaction",
            ));
        }
        Ok(())
    }
    fn commit_sccp_registry_action(
        state_transaction: &mut StateTransaction<'_, '_>,
        payload: crate::state::SccpOnChainRegistryV1,
        operation: SccpRegistryOperation,
        lane_id: iroha_data_model::bridge::SccpLaneIdV1,
        route: Option<iroha_data_model::bridge::SccpRouteKeyV1>,
    ) -> Result<(), Error> {
        payload.validate().map_err(|error| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                error.to_string(),
            ))
        })?;
        let next_registry = crate::state::ValidatedSccpRegistryV1::try_from_wire(payload.clone())
            .map_err(|message| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                message,
            ))
        })?;
        crate::state::validate_sccp_registry_local_profile(
            next_registry.as_ref(),
            &state_transaction.chain_id,
        )
        .map_err(|message| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                message,
            ))
        })?;
        let old_digest = state_transaction.sccp_registry.event_digest();
        let new_digest = next_registry.event_digest();
        // Persist the already-validated canonical aggregate, not the caller's
        // presentation order.  The typed cell is consensus state and must be
        // byte-stable so subsequent readers can reuse the validated registry
        // without repeating curve and subgroup checks.
        *state_transaction.world.sccp_registry.get_mut() = next_registry.to_wire();
        state_transaction.sccp_registry = next_registry;
        state_transaction
            .world
            .emit_events(Some(ConfigurationEvent::SccpRegistryChanged(
                SccpRegistryChanged {
                    operation,
                    lane_id,
                    route,
                    old_digest,
                    new_digest,
                },
            )));
        Ok(())
    }
    fn sccp_route_has_durable_history(
        route: &iroha_data_model::bridge::SccpGovernedRouteV1,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<bool, Error> {
        if state_transaction
            .world
            .sccp_route_liabilities
            .get(&route.key())
            .is_some()
        {
            return Ok(true);
        }
        if state_transaction
            .world
            .sccp_ton_breaker_observations
            .get(&route.key())
            .is_some()
        {
            return Ok(true);
        }
        let escrow = iroha_data_model::bridge::sccp_route_escrow_account_id_v1(
            &state_transaction.network_id,
            &route.key(),
            &route.settlement.asset_definition_id,
        );
        if state_transaction.world.account(&escrow).is_ok() {
            // Once the deterministic account exists, the route has admitted
            // liquidity or a settlement attempt. Retain the immutable route
            // forever so generic account/asset guards cannot lose its binding.
            return Ok(true);
        }
        let configuration_hash = route.route_configuration_hash().map_err(|error| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                error.to_string(),
            ))
        })?;
        Ok(state_transaction
            .world
            .sccp_replay_forests
            .iter()
            .any(|(id, forest)| id.route_key == route.key() && forest.leaf_count != 0)
            || state_transaction
                .world
                .sccp_outbound_pending_messages
                .iter()
                .any(|(key, record)| {
                    key.lane.source == route.lane_id.target
                        && key.lane.target == route.lane_id.source
                        && record.route_configuration_hash == configuration_hash
                }))
    }
    fn validate_sccp_route_registration_resources(
        route: &iroha_data_model::bridge::SccpGovernedRouteV1,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let verifying_key_is_well_formed = match route.destination {
            iroha_data_model::bridge::SccpDestinationDeploymentV1::Evm(deployment) => {
                iroha_sccp::sccp_groth16_bn254_verifying_key_is_well_formed_v1(
                    &deployment.verifying_key,
                )
            }
            iroha_data_model::bridge::SccpDestinationDeploymentV1::Tron(deployment) => {
                iroha_sccp::sccp_groth16_bn254_verifying_key_is_well_formed_v1(
                    &deployment.verifying_key,
                )
            }
            iroha_data_model::bridge::SccpDestinationDeploymentV1::Ton(deployment) => {
                iroha_sccp::sccp_groth16_bls12381_verifying_key_is_well_formed_v1(
                    &deployment.verifying_key,
                )
            }
        };
        if !verifying_key_is_well_formed {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "SCCP governed Groth16 key contains an invalid curve, infinity, or subgroup point"
                        .to_owned(),
                ),
            )
            .into());
        }
        let definition = state_transaction
            .world
            .asset_definition(&route.settlement.asset_definition_id)
            .map_err(|error| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    format!("SCCP settlement asset definition is not registered: {error}"),
                ))
            })?;
        if definition.balance_scope_policy() != AssetBalancePolicy::Global {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(format!(
                    "SCCP settlement asset definition `{}` must use Global balance policy because SCCP custody and liability use canonical global AssetId",
                    definition.id()
                )),
            )
            .into());
        }
        if definition
            .spec()
            .scale()
            .is_some_and(|scale| scale < route.settlement.payload_amount_scale)
        {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "SCCP settlement asset numeric precision cannot represent payload amounts"
                        .to_owned(),
                ),
            )
            .into());
        }
        let escrow = iroha_data_model::bridge::sccp_route_escrow_account_id_v1(
            &state_transaction.network_id,
            &route.key(),
            &route.settlement.asset_definition_id,
        );
        if state_transaction.world.account(&escrow).is_ok() {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "SCCP route registration requires its deterministic protocol escrow account to be absent"
                        .to_owned(),
                ),
            )
            .into());
        }
        Ok(())
    }
    fn ensure_sccp_route_escrow_account(
        route_key: &iroha_data_model::bridge::SccpRouteKeyV1,
        asset_definition_id: &AssetDefinitionId,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<AccountId, Error> {
        let escrow = iroha_data_model::bridge::sccp_route_escrow_account_id_v1(
            &state_transaction.network_id,
            route_key,
            asset_definition_id,
        );
        crate::smartcontracts::isi::domain::isi::ensure_controller_capabilities(
            escrow.controller(),
            &state_transaction.crypto.allowed_signing,
            &state_transaction.crypto.allowed_curve_ids,
        )?;
        if state_transaction.world.account(&escrow).is_err() {
            let account = Account::new(escrow.clone()).build(&escrow);
            let (id, account) = iroha_data_model::IntoKeyValue::into_key_value(account);
            state_transaction.world.accounts.insert(id, account);
        }
        Ok(escrow)
    }
    fn apply_sccp_route_governance_action(
        action: bridge::SccpRouteGovernanceActionV1,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        action.validate_static().map_err(|error| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                error.to_string(),
            ))
        })?;
        let mut payload = state_transaction.sccp_registry.to_wire();
        let (operation, lane_id, event_route) = match action {
            bridge::SccpRouteGovernanceActionV1::Register(registration) => {
                let route = registration.route;
                validate_sccp_route_registration_resources(&route, state_transaction)?;
                let key = route.key();
                if let Some(lane) = payload
                    .lanes
                    .iter_mut()
                    .find(|lane| lane.lane_id == route.lane_id)
                {
                    if lane.current_native_trust_anchor() != registration.native_trust_anchor {
                        return Err(InstructionExecutionError::InvalidParameter(
                                InvalidParameterError::SmartContract(
                                    "SCCP route registration anchor does not match the existing lane's current anchor"
                                        .to_owned(),
                                ),
                            )
                            .into());
                    }
                    let previous_revision = lane
                        .routes
                        .iter()
                        .filter(|existing| {
                            existing.route_id == route.route_id
                                && existing.asset_key == route.asset_key
                        })
                        .map(|existing| existing.revision)
                        .max();
                    let expected_revision = match previous_revision {
                        Some(revision) => revision.checked_add(1).ok_or_else(|| {
                            InstructionExecutionError::InvalidParameter(
                                InvalidParameterError::SmartContract(
                                    "SCCP route revision overflow has no valid successor"
                                        .to_owned(),
                                ),
                            )
                        })?,
                        None => 1,
                    };
                    if route.revision != expected_revision {
                        return Err(InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP route revision is not the monotonic lineage successor"
                                    .to_owned(),
                            ),
                        )
                        .into());
                    }
                    lane.routes.push(route);
                } else {
                    if route.revision != 1 {
                        return Err(InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "the first SCCP route revision on a lane must be 1".to_owned(),
                            ),
                        )
                        .into());
                    }
                    let native_trust_anchors =
                        registration.native_trust_anchor.into_iter().collect();
                    payload
                        .lanes
                        .push(iroha_data_model::bridge::SccpGovernedLaneV1 {
                            lane_id: route.lane_id,
                            native_trust_anchors,
                            current_native_trust_anchor_hash: registration
                                .native_trust_anchor
                                .map(|anchor| anchor.anchor_hash),
                            routes: vec![route],
                        });
                }
                (SccpRegistryOperation::RegisterRoute, key.lane_id, Some(key))
            }
            bridge::SccpRouteGovernanceActionV1::SetActivation(update) => {
                let lane = payload
                    .lanes
                    .iter_mut()
                    .find(|lane| lane.lane_id == update.key.lane_id)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP activation lane was not found".to_owned(),
                            ),
                        )
                    })?;
                if update
                    .inbound_finality_cutoff
                    .is_some_and(|cutoff| !lane.is_complete_inbound_finality_interval(cutoff))
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "SCCP retirement cutoff must equal one complete closed historical anchor interval"
                                .to_owned(),
                        ),
                    )
                    .into());
                }
                let route = lane
                    .routes
                    .iter_mut()
                    .find(|route| route.key() == update.key)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP activation target was not found".to_owned(),
                            ),
                        )
                    })?;
                if route.activation != update.expected_current
                    || !route.activation.can_transition_to(update.next)
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "stale or illegal SCCP activation compare-and-swap".to_owned(),
                        ),
                    )
                    .into());
                }
                if update.next.allows_outbound() {
                    ensure_fresh_ton_breaker_observation_for_outbound(
                        &update.key,
                        state_transaction,
                    )?;
                }
                route.activation = update.next;
                route.inbound_finality_cutoff = update.inbound_finality_cutoff;
                (
                    SccpRegistryOperation::SetRouteActivation,
                    update.key.lane_id,
                    Some(update.key),
                )
            }
            bridge::SccpRouteGovernanceActionV1::SwitchRevision(update) => {
                let lane = payload
                    .lanes
                    .iter_mut()
                    .find(|lane| lane.lane_id == update.previous_key.lane_id)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP revision-switch lane was not found".to_owned(),
                            ),
                        )
                    })?;
                let previous_index = lane
                    .routes
                    .iter()
                    .position(|route| route.key() == update.previous_key)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP previous revision was not found".to_owned(),
                            ),
                        )
                    })?;
                let successor_index = lane
                    .routes
                    .iter()
                    .position(|route| route.key() == update.successor_key)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP successor revision was not found".to_owned(),
                            ),
                        )
                    })?;
                if previous_index == successor_index
                    || lane.routes[previous_index].activation != update.expected_previous
                    || lane.routes[successor_index].activation
                        != iroha_data_model::bridge::SccpRouteActivationV1::Staged
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "stale SCCP revision-switch compare-and-swap".to_owned(),
                        ),
                    )
                    .into());
                }
                if update
                    .previous_inbound_finality_cutoff
                    .is_some_and(|cutoff| !lane.is_complete_inbound_finality_interval(cutoff))
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "SCCP atomic cutover cutoff must equal one complete closed historical anchor interval"
                                .to_owned(),
                        ),
                    )
                    .into());
                }
                if update.successor_next.allows_outbound() {
                    ensure_fresh_ton_breaker_observation_for_outbound(
                        &update.successor_key,
                        state_transaction,
                    )?;
                }
                lane.routes[previous_index].activation = update.previous_next;
                lane.routes[previous_index].inbound_finality_cutoff =
                    update.previous_inbound_finality_cutoff;
                lane.routes[successor_index].activation = update.successor_next;
                (
                    SccpRegistryOperation::SwitchRouteRevision,
                    update.successor_key.lane_id,
                    Some(update.successor_key),
                )
            }
            bridge::SccpRouteGovernanceActionV1::InitializeTrustAnchor(update) => {
                let lane = payload
                    .lanes
                    .iter_mut()
                    .find(|lane| lane.lane_id == update.lane_id)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP anchor-initialization lane was not found".to_owned(),
                            ),
                        )
                    })?;
                if lane.current_native_trust_anchor() != update.expected_current
                    || update.expected_current.is_some()
                    || !lane.native_trust_anchors.is_empty()
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "stale SCCP trust-anchor initialization compare-and-swap".to_owned(),
                        ),
                    )
                    .into());
                }
                lane.native_trust_anchors.push(update.initial);
                lane.current_native_trust_anchor_hash = Some(update.initial.anchor_hash);
                (
                    SccpRegistryOperation::InitializeLaneTrustAnchor,
                    update.lane_id,
                    None,
                )
            }
            bridge::SccpRouteGovernanceActionV1::AdvanceTrustAnchor(update) => {
                let lane = payload
                    .lanes
                    .iter_mut()
                    .find(|lane| lane.lane_id == update.lane_id)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP anchor-advance lane was not found".to_owned(),
                            ),
                        )
                    })?;
                if lane.current_native_trust_anchor() != Some(update.expected_current) {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "stale SCCP trust-anchor compare-and-swap".to_owned(),
                        ),
                    )
                    .into());
                }
                let high_water_key =
                    iroha_data_model::bridge::SccpInboundAnchorHighWaterKeyV1::new(
                        update.lane_id,
                        update.expected_current.anchor_hash,
                    )
                    .ok_or_else(|| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP trust-anchor advance cannot form a valid high-water key"
                                    .to_owned(),
                            ),
                        )
                    })?;
                if state_transaction
                    .world
                    .sccp_inbound_anchor_high_water
                    .get(&high_water_key)
                    .is_some_and(|high_water| update.next.checkpoint_height < *high_water)
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "SCCP successor checkpoint is below already-admitted consensus progress for the current anchor"
                                .to_owned(),
                        ),
                    )
                    .into());
                }
                if lane
                    .native_trust_anchor_by_hash(update.next.anchor_hash)
                    .is_some()
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "SCCP trust-anchor advance cannot reuse a historical anchor hash"
                                .to_owned(),
                        ),
                    )
                    .into());
                }
                lane.native_trust_anchors.push(update.next);
                lane.current_native_trust_anchor_hash = Some(update.next.anchor_hash);
                (
                    SccpRegistryOperation::AdvanceLaneTrustAnchor,
                    update.lane_id,
                    None,
                )
            }
            bridge::SccpRouteGovernanceActionV1::Remove(key) => {
                let lane_index = payload
                    .lanes
                    .iter()
                    .position(|lane| lane.lane_id == key.lane_id)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP removal lane was not found".to_owned(),
                            ),
                        )
                    })?;
                let route_index = payload.lanes[lane_index]
                    .routes
                    .iter()
                    .position(|route| route.key() == key)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(
                                "SCCP removal target was not found".to_owned(),
                            ),
                        )
                    })?;
                let route = &payload.lanes[lane_index].routes[route_index];
                if matches!(
                    route.source_identity.emitter,
                    iroha_data_model::bridge::SccpSourceEmitterV1::Tron(_)
                ) {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "registered TRON SCCP route revisions cannot be removed because their immutable addresses remain replay boundaries"
                                .to_owned(),
                        ),
                    )
                    .into());
                }
                if route.activation != iroha_data_model::bridge::SccpRouteActivationV1::Staged
                    || sccp_route_has_durable_history(route, state_transaction)?
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "only a never-used staged SCCP route revision can be removed"
                                .to_owned(),
                        ),
                    )
                    .into());
                }
                payload.lanes[lane_index].routes.remove(route_index);
                if payload.lanes[lane_index].routes.is_empty() {
                    payload.lanes.remove(lane_index);
                }
                (
                    SccpRegistryOperation::RemoveStagedRoute,
                    key.lane_id,
                    Some(key),
                )
            }
        };
        commit_sccp_registry_action(state_transaction, payload, operation, lane_id, event_route)
    }
    /// Exercise the production SCCP route-removal path from isolated integration tests.
    #[cfg(any(test, feature = "iroha-core-tests"))]
    #[doc(hidden)]
    pub fn remove_sccp_route_for_testing(
        key: iroha_data_model::bridge::SccpRouteKeyV1,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        apply_sccp_route_governance_action(
            bridge::SccpRouteGovernanceActionV1::Remove(key),
            state_transaction,
        )
    }
    impl Execute for bridge::ApplySccpRouteGovernance {
        fn execute(
            self,
            _authority: &AccountId,
            _state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let _ = self;
            Err(InstructionExecutionError::InvariantViolation(
                "direct SCCP route mutation is retired; only an exact due Parliament certificate may apply an action"
                    .into(),
            ))
        }
    }
    fn ton_breaker_block_id_readback(
        block: iroha_sccp::TonBlockIdExtV1,
    ) -> iroha_data_model::bridge::SccpTonBlockIdExtV1 {
        iroha_data_model::bridge::SccpTonBlockIdExtV1 {
            workchain: block.workchain,
            shard: block.shard,
            seqno: block.seqno,
            root_hash: block.root_hash,
            file_hash: block.file_hash,
        }
    }
    fn ton_breaker_account_readback(
        account: iroha_sccp::TonAccountStateReadbackV1,
    ) -> iroha_data_model::bridge::SccpTonAccountStateReadbackV1 {
        iroha_data_model::bridge::SccpTonAccountStateReadbackV1 {
            address: account.address,
            shard_block: ton_breaker_block_id_readback(account.shard_block_id),
            registered_masterchain_seqno: account.registered_masterchain_seqno,
            shard_state_hash: account.shard_state_root_hash,
            account_state_hash: account.account_state_hash,
            code_hash: account.code_hash,
            data_hash: account.data_hash,
        }
    }
    fn ton_breaker_replay_readback(
        replay: iroha_sccp::TonReplayForestReadbackV1,
    ) -> iroha_data_model::bridge::SccpTonReplayForestReadbackV1 {
        iroha_data_model::bridge::SccpTonReplayForestReadbackV1 {
            root_hash: replay.nonempty_shard_roots_hash,
            leaf_count: replay.leaf_count,
            update_sequence: replay.update_sequence,
        }
    }
    fn ton_breaker_pending_readback(
        mints: iroha_sccp::TonPendingMapReadbackV1,
        burns: iroha_sccp::TonPendingMapReadbackV1,
    ) -> iroha_data_model::bridge::SccpTonBridgePendingReadbackV1 {
        iroha_data_model::bridge::SccpTonBridgePendingReadbackV1 {
            mint_root_hash: mints.dictionary_root_hash,
            burn_root_hash: burns.dictionary_root_hash,
            mint_count: mints.count,
            burn_count: burns.count,
        }
    }
    fn ton_breaker_deployment_readback(
        route_address: iroha_data_model::bridge::SccpTonAddressV1,
        jetton_master_address: iroha_data_model::bridge::SccpTonAddressV1,
        deployment: iroha_sccp::TonDeploymentReadbackV1,
    ) -> iroha_data_model::bridge::SccpTonDeploymentReadbackV1 {
        iroha_data_model::bridge::SccpTonDeploymentReadbackV1 {
            jetton_master_address,
            route_address,
            expected_global_id: deployment.expected_global_id,
            route_revision: deployment.route_revision,
            taira_to_ton_multiplier: deployment.taira_to_ton_multiplier,
            max_wrapped_supply: deployment.max_wrapped_supply,
            source_lane_bytes: deployment.source_lane_bytes,
            destination_lane_bytes: deployment.destination_lane_bytes,
            source_lane_hash: deployment.source_lane_hash,
            destination_lane_hash: deployment.destination_lane_hash,
            route_configuration_hash: deployment.route_configuration_hash,
            destination_binding_hash: deployment.destination_binding_hash,
            bridge_config_cell_hash: deployment.bridge_config_cell_hash,
            jetton_master_code_hash: deployment.jetton_master_code_hash,
            jetton_master_initial_data_hash: deployment.jetton_master_initial_data_hash,
            jetton_wallet_code_hash: deployment.jetton_wallet_code_hash,
            route_code_hash: deployment.route_code_hash,
            route_initial_data_hash: deployment.route_initial_data_hash,
            embedded_verifier_code_hash: deployment.embedded_verifier_code_hash,
            verifier_circuit_hash: deployment.verifier_circuit_hash,
            verifying_key_hash: deployment.verifying_key_hash,
            verifying_key_cell_hash: deployment.verifying_key_cell_hash,
            proof_profile_commitment: deployment.proof_profile_commitment,
            semantic_proof_profile_hash: deployment.semantic_proof_profile_hash,
            sora_finality_anchor_hash: deployment.sora_finality_anchor_hash,
            mint_breaker_guardian_keys: deployment.mint_breaker_guardian_keys,
            master_metadata_hash: deployment.master_metadata_hash,
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    struct TonBreakerPriorTransitionV1 {
        observation_digest: [u8; 32],
        masterchain_seqno: u32,
        masterchain_gen_utime: u32,
        disabled_latched: bool,
    }

    fn ton_breaker_disabled_latch_transition_v1(
        expected_prior_observation_digest: [u8; 32],
        prior: Option<TonBreakerPriorTransitionV1>,
        masterchain_seqno: u32,
        masterchain_gen_utime: u32,
        effective_disabled: bool,
    ) -> Result<bool, &'static str> {
        let Some(prior) = prior else {
            if expected_prior_observation_digest != [0; 32] {
                return Err("first TON breaker observation must compare-and-swap from absence");
            }
            return Ok(effective_disabled);
        };
        if expected_prior_observation_digest != prior.observation_digest {
            return Err("TON breaker observation prior-record digest compare-and-swap failed");
        }
        if masterchain_seqno <= prior.masterchain_seqno {
            return Err("TON breaker observation masterchain sequence must strictly increase");
        }
        if masterchain_gen_utime < prior.masterchain_gen_utime {
            return Err("TON breaker observation authenticated time must not decrease");
        }
        Ok(prior.disabled_latched || effective_disabled)
    }

    fn ton_breaker_anchor_matches_current_governance_v1(
        lane_id: iroha_data_model::bridge::SccpLaneIdV1,
        anchor: iroha_data_model::bridge::SccpNativeTrustAnchorV1,
        proof_checkpoint_seqno: u32,
    ) -> bool {
        lane_id.source == iroha_data_model::bridge::SccpNetworkV1::TonMainnet
            && lane_id.target == iroha_data_model::bridge::SccpNetworkV1::SoraTaira
            && anchor.backend
                == iroha_data_model::bridge::BridgeNativeProofBackendV1::TonMasterchain
            && anchor.backend.supports_source_network(lane_id.source)
            && u64::from(proof_checkpoint_seqno) == anchor.checkpoint_height
    }

    impl Execute for bridge::SubmitSccpTonBreakerObservationV1 {
        fn execute(
            self,
            _authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let proof_size = self.encoded_observation.len();
            state_transaction.preflight_sccp_proof(proof_size)?;
            let proof = norito::decode_canonical::<iroha_sccp::SccpTonBreakerObservationProofV1>(
                &self.encoded_observation,
            )
            .map_err(|error| {
                invalid_bridge_proof(format!(
                    "TON breaker observation is not canonical Norito: {error}"
                ))
            })?;
            if proof.route_key != self.route_key {
                return Err(invalid_bridge_proof(
                    "TON breaker observation route key differs from the instruction key",
                ));
            }
            let work =
                iroha_sccp::ton_breaker_observation_work_estimate(&proof).map_err(|error| {
                    invalid_bridge_proof(format!(
                        "TON breaker observation exceeds native verifier bounds: {error}"
                    ))
                })?;
            state_transaction.register_sccp_proof(
                proof_size,
                crate::state::SccpVerifierWorkV1 {
                    native_headers: u64::from(work.continuation_blocks),
                    native_header_bytes: u64::from(work.framed_boc_bytes),
                    ed25519_signature_checks: u64::from(work.ed25519_signature_checks),
                    ed25519_validator_key_checks: u64::from(work.validator_key_checks_upper_bound),
                    ..crate::state::SccpVerifierWorkV1::default()
                },
            )?;
            let governed_route = state_transaction
                .sccp_registry
                .route(&self.route_key)
                .cloned()
                .ok_or_else(|| {
                    invalid_bridge_proof(
                        "TON breaker observation has no retained governed route revision",
                    )
                })?;
            let governed_anchor = state_transaction
                .sccp_registry
                .lane(self.route_key.lane_id)
                .and_then(|lane| lane.current_native_trust_anchor())
                .ok_or_else(|| {
                    invalid_bridge_proof(
                        "TON breaker observation requires the lane's current native trust anchor",
                    )
                })?;
            if !ton_breaker_anchor_matches_current_governance_v1(
                self.route_key.lane_id,
                governed_anchor,
                proof.finality.anchor.checkpoint.seqno,
            ) {
                return Err(invalid_bridge_proof(
                    "TON breaker observation anchor checkpoint differs from exact current governance",
                ));
            }
            let expected_anchor_hash = governed_anchor.anchor_hash;
            let verified = iroha_sccp::verify_sccp_ton_breaker_observation_v1(
                &proof,
                &governed_route,
                expected_anchor_hash,
            )
            .map_err(|error| {
                invalid_bridge_proof(format!("TON breaker observation rejected: {error}"))
            })?;
            let now_ms = state_transaction.block_unix_timestamp_ms();
            let ton_time_ms = u64::from(verified.masterchain_gen_utime)
                .checked_mul(1_000)
                .ok_or_else(|| {
                    invalid_bridge_proof("TON breaker observation timestamp overflows milliseconds")
                })?;
            if !iroha_data_model::bridge::observation_is_fresh_at(ton_time_ms, now_ms) {
                return Err(invalid_bridge_proof(
                    "TON breaker observation is stale or too far in the future at consensus time",
                ));
            }
            let prior = state_transaction
                .world
                .sccp_ton_breaker_observations
                .get(&self.route_key)
                .cloned();
            let disabled_latched = ton_breaker_disabled_latch_transition_v1(
                self.expected_prior_observation_digest,
                prior.as_ref().map(|prior| TonBreakerPriorTransitionV1 {
                    observation_digest: prior.observation_digest,
                    masterchain_seqno: prior.masterchain.block_id.seqno,
                    masterchain_gen_utime: prior.masterchain.gen_utime,
                    disabled_latched: prior.disabled_latched,
                }),
                verified.masterchain_block_id.seqno,
                verified.masterchain_gen_utime,
                verified.effective_disabled,
            )
            .map_err(invalid_bridge_proof)?;
            let route_storage = verified.route_storage;
            let master_storage = verified.master_storage;
            let mut record = iroha_data_model::bridge::SccpTonBreakerObservationRecordV1 {
                route_key: self.route_key.clone(),
                authenticated_native_anchor_hash: expected_anchor_hash,
                masterchain: iroha_data_model::bridge::SccpTonFinalizedMasterchainBlockV1 {
                    block_id: ton_breaker_block_id_readback(verified.masterchain_block_id),
                    gen_utime: verified.masterchain_gen_utime,
                },
                route_account: ton_breaker_account_readback(verified.route_account),
                jetton_master_account: ton_breaker_account_readback(verified.jetton_master_account),
                deployment: ton_breaker_deployment_readback(
                    verified.route_account.address,
                    verified.jetton_master_account.address,
                    verified.deployment,
                ),
                route_storage: iroha_data_model::bridge::SccpTonRouteStorageReadbackV1 {
                    storage_version: iroha_data_model::bridge::SCCP_V1_TON_STORAGE_VERSION,
                    route_configuration_hash: route_storage.route_configuration_hash,
                    bridge_config_cell_hash: route_storage.bridge_config_cell_hash,
                    inbound_mint_replay: ton_breaker_replay_readback(
                        route_storage.inbound_mint_replay,
                    ),
                    outbound_burn_replay: ton_breaker_replay_readback(
                        route_storage.outbound_burn_replay,
                    ),
                    pending: ton_breaker_pending_readback(
                        route_storage.pending_mints,
                        route_storage.pending_burns,
                    ),
                    minting_disabled: route_storage.minting_disabled,
                },
                master_storage: iroha_data_model::bridge::SccpTonMasterStorageReadbackV1 {
                    storage_version: iroha_data_model::bridge::SCCP_V1_TON_STORAGE_VERSION,
                    route_configuration_hash: master_storage.route_configuration_hash,
                    bridge_config_cell_hash: master_storage.bridge_config_cell_hash,
                    total_supply: master_storage.total_supply,
                    metadata_hash: master_storage.metadata_hash,
                    route_address: master_storage.bridge_address,
                    mint_replay: ton_breaker_replay_readback(master_storage.mint_replay),
                    burn_replay: ton_breaker_replay_readback(master_storage.burn_replay),
                    pending_mint_root_hash: master_storage.pending_mints.dictionary_root_hash,
                    pending_mint_count: master_storage.pending_mints.count,
                    minting_disabled: master_storage.minting_disabled,
                },
                effective_disabled: verified.effective_disabled,
                disabled_latched,
                proof_sha256: verified.canonical_proof_sha256,
                proof_size_bytes: verified.canonical_proof_byte_len,
                accepted_at_height: state_transaction.block_height(),
                accepted_at_unix_ms: now_ms,
                observation_digest: [0; 32],
            };
            let encoded_observation_sha256: [u8; 32] =
                sha2::Sha256::digest(&self.encoded_observation).into();
            if usize::try_from(record.proof_size_bytes).ok() != Some(proof_size)
                || record.proof_sha256 != encoded_observation_sha256
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "TON breaker verifier reported different canonical proof bytes".into(),
                ));
            }
            record.observation_digest = record.computed_digest();
            if !record.is_well_formed() {
                return Err(InstructionExecutionError::InvariantViolation(
                    "verified TON breaker observation could not form a canonical state record"
                        .into(),
                ));
            }
            state_transaction
                .world
                .sccp_ton_breaker_observations
                .insert(self.route_key, record);
            // Do not emit a triggerable `BridgeEvent` here. Data-trigger failure rejects the
            // surrounding transaction, which would let an unrelated trigger veto a valid
            // emergency disable observation. The committed route-keyed readback is the
            // consensus audit channel for this fail-safe transition.
            Ok(())
        }
    }
    impl Execute for bridge::RecordBridgeReceipt {
        fn execute(
            self,
            _authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::events::data::prelude::BridgeEvent;
            consume_bridge_receipt_proof(&self.receipt, state_transaction)?;
            state_transaction
                .world
                .emit_events(Some(BridgeEvent::Emitted(self.receipt)));
            Ok(())
        }
    }
    fn ensure_sccp_outbound_lane_is_active(
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        let Some(lane_id) = state_transaction.current_lane_id else {
            return Err(InstructionExecutionError::InvariantViolation(
                "SCCP message recording requires an active transaction lane".into(),
            ));
        };
        let Some(active_dataspace_id) = nexus_active_lane_dataspace_at_height(
            lane_id,
            &state_transaction.nexus,
            state_transaction.block_height(),
        ) else {
            return Err(InstructionExecutionError::InvariantViolation(
                format!("SCCP message recording requires active Nexus lane {lane_id}").into(),
            ));
        };
        let Some(dataspace_id) = state_transaction.current_dataspace_id else {
            return Err(InstructionExecutionError::InvariantViolation(
                "SCCP message recording requires an active transaction dataspace".into(),
            ));
        };
        if let Some(world_dataspace_id) = state_transaction.world.current_dataspace_id
            && world_dataspace_id != dataspace_id
        {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "SCCP message recording transaction dataspace {} does not match world dataspace {}",
                    dataspace_id.as_u64(),
                    world_dataspace_id.as_u64()
                )
                .into(),
            ));
        }
        if dataspace_id != active_dataspace_id {
            return Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "SCCP message recording transaction dataspace {} does not match active Nexus lane {} dataspace {}",
                    dataspace_id.as_u64(),
                    lane_id.as_u32(),
                    active_dataspace_id.as_u64()
                )
                .into(),
            ));
        }
        Ok(())
    }
    #[derive(Clone, Debug)]
    struct ResolvedSccpSettlementRouteV1 {
        route_key: iroha_data_model::bridge::SccpRouteKeyV1,
        route_id: String,
        asset_key: String,
        route_configuration_hash: [u8; 32],
        destination: iroha_data_model::bridge::SccpDestinationDeploymentV1,
        sora_outbound_execution_policy: iroha_data_model::bridge::SccpSoraOutboundExecutionPolicyV1,
        settlement_asset_definition_id: AssetDefinitionId,
        escrow_account_id: AccountId,
        payload_amount_scale: u32,
        counterparty_account_codec: u8,
    }
    fn resolve_sccp_settlement_route(
        registry: &crate::state::ValidatedSccpRegistryV1,
        network_id: &iroha_data_model::NetworkId,
        lane_id: iroha_data_model::bridge::SccpLaneIdV1,
        route_id: &[u8],
        asset_key: &[u8],
        route_revision: u32,
        inbound: bool,
        source_identity_hash: Option<[u8; 32]>,
        local_network: iroha_data_model::bridge::SccpNetworkV1,
    ) -> Result<ResolvedSccpSettlementRouteV1, Error> {
        if !lane_id.source.is_external() || lane_id.target != local_network {
            return Err(invalid_bridge_proof(
                "SCCP settlement requires an active exact external-to-local-SORA lane",
            ));
        }
        if inbound && source_identity_hash.is_none() {
            return Err(invalid_bridge_proof(
                "SCCP inbound settlement requires authenticated source identity",
            ));
        }
        let route_id = core::str::from_utf8(route_id)
            .map_err(|_| invalid_bridge_proof("SCCP route id is not canonical UTF-8"))?;
        let asset_key = core::str::from_utf8(asset_key)
            .map_err(|_| invalid_bridge_proof("SCCP asset key is not canonical UTF-8"))?;
        let key = iroha_data_model::bridge::SccpRouteKeyV1::new(
            lane_id,
            route_id.to_owned(),
            asset_key.to_owned(),
            route_revision,
        )
        .map_err(|error| invalid_bridge_proof(format!("invalid SCCP route key: {error}")))?;
        let route = registry
            .route(&key)
            .filter(|route| {
                (!inbound
                    || iroha_data_model::bridge::sccp_source_identity_hash_v1(
                        &route.source_identity,
                    ) == source_identity_hash)
                    && (inbound || route.activation.allows_outbound())
            })
            .ok_or_else(|| {
                invalid_bridge_proof("SCCP settlement has no enabled exact route revision")
            })?;
        let expected_codec = iroha_sccp::sccp_counterparty_account_codec(
            lane_id.source.domain_id(),
        )
        .ok_or_else(|| invalid_bridge_proof("SCCP settlement lane account codec is unknown"))?;
        let route_configuration_hash = route.route_configuration_hash().map_err(|error| {
            invalid_bridge_proof(format!("SCCP route configuration is invalid: {error}"))
        })?;
        let route_key = route.key();
        let escrow_account_id = iroha_data_model::bridge::sccp_route_escrow_account_id_v1(
            network_id,
            &route_key,
            &route.settlement.asset_definition_id,
        );
        Ok(ResolvedSccpSettlementRouteV1 {
            route_key,
            route_id: route.route_id.clone(),
            asset_key: route.asset_key.clone(),
            route_configuration_hash,
            destination: route.destination,
            sora_outbound_execution_policy: route.sora_outbound_execution_policy.clone(),
            settlement_asset_definition_id: route.settlement.asset_definition_id.clone(),
            escrow_account_id,
            payload_amount_scale: route.settlement.payload_amount_scale,
            counterparty_account_codec: expected_codec,
        })
    }
    fn validate_current_sccp_outbound_record_governance(
        context: iroha_data_model::bridge::SccpOutboundMessageContextV1,
        transfer: &iroha_sccp::TransferPayloadV1,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<ResolvedSccpSettlementRouteV1, Error> {
        let local_network = sccp_local_sora_network_for_chain_id(&state_transaction.chain_id)
            .ok_or_else(|| {
                invalid_bridge_proof(format!(
                    "SCCP local chain id `{}` is not one of the canonical public SORA chain ids",
                    state_transaction.chain_id
                ))
            })?;
        if context.lane.source != local_network {
            return Err(invalid_bridge_proof(format!(
                "SCCP outbound context source profile `{}` does not match local profile `{}`",
                context.lane.source.profile_key(),
                local_network.profile_key()
            )));
        }
        let governed_lane_id = iroha_data_model::bridge::SccpLaneIdV1 {
            source: context.lane.target,
            target: context.lane.source,
        };
        let lane = state_transaction
            .sccp_registry
            .lane(governed_lane_id)
            .ok_or_else(|| {
                invalid_bridge_proof(format!(
                    "SCCP outbound context has no active exact governed reverse lane {} -> {}",
                    governed_lane_id.source.profile_key(),
                    governed_lane_id.target.profile_key()
                ))
            })?;
        let settlement = resolve_sccp_settlement_route(
            state_transaction.sccp_registry.as_ref(),
            &state_transaction.network_id,
            lane.lane_id,
            &transfer.route_id,
            &transfer.asset_id,
            transfer.route_revision,
            false,
            None,
            local_network,
        )?;
        ensure_fresh_ton_breaker_observation_for_outbound(
            &settlement.route_key,
            state_transaction,
        )?;
        let route_binding_hash = settlement
            .destination
            .destination_binding_hash(governed_lane_id)
            .map_err(|error| invalid_bridge_proof(error.to_string()))?;
        if route_binding_hash != context.destination_binding_hash {
            return Err(invalid_bridge_proof(
                "SCCP outbound context destination binding is stale or belongs to another exact lane",
            ));
        }
        if settlement.route_configuration_hash != context.route_configuration_hash {
            return Err(invalid_bridge_proof(
                "SCCP outbound context route configuration is stale or belongs to another exact route revision",
            ));
        }
        Ok(settlement)
    }
    fn ensure_fresh_ton_breaker_observation_for_outbound(
        route_key: &iroha_data_model::bridge::SccpRouteKeyV1,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        if route_key.lane_id.source != iroha_data_model::bridge::SccpNetworkV1::TonMainnet {
            return Ok(());
        }
        let observation = state_transaction
            .world
            .sccp_ton_breaker_observations
            .get(route_key);
        ton_breaker_observation_allows_outbound_v1(
            route_key,
            observation,
            state_transaction.block_unix_timestamp_ms(),
        )
        .map_err(invalid_bridge_proof)
    }
    fn ton_breaker_observation_allows_outbound_v1(
        route_key: &iroha_data_model::bridge::SccpRouteKeyV1,
        observation: Option<&iroha_data_model::bridge::SccpTonBreakerObservationRecordV1>,
        now_ms: u64,
    ) -> Result<(), &'static str> {
        let observation = observation.ok_or(
            "TonMainnet outbound admission requires a proof-authenticated breaker observation",
        )?;
        if !observation.is_well_formed() || observation.route_key != *route_key {
            return Err("TonMainnet breaker observation is not self-consistent");
        }
        if observation.disabled_latched {
            return Err(
                "TonMainnet outbound admission is permanently disabled for this route revision",
            );
        }
        if !observation.is_fresh_at(now_ms) {
            return Err("TonMainnet breaker observation is stale at the consensus block time");
        }
        Ok(())
    }
    fn validate_sccp_route_fields_match_manifest(
        route_id_codec: u8,
        route_id: &[u8],
        asset_id_codec: u8,
        asset_id: &[u8],
        route_revision: u32,
        settlement: &ResolvedSccpSettlementRouteV1,
    ) -> Result<(), Error> {
        if route_id_codec != iroha_sccp::SCCP_CODEC_CANONICAL_TEXT
            || asset_id_codec != iroha_sccp::SCCP_CODEC_CANONICAL_TEXT
            || route_id != settlement.route_id.as_bytes()
            || asset_id != settlement.asset_key.as_bytes()
            || route_revision != settlement.route_key.revision
        {
            return Err(invalid_bridge_proof(
                "SCCP payload route_id, asset_id, and revision must exactly match the governed route configuration",
            ));
        }
        Ok(())
    }
    fn sccp_payload_amount(
        amount: u128,
        settlement: &ResolvedSccpSettlementRouteV1,
    ) -> Result<Quantity, Error> {
        if amount == 0 {
            return Err(invalid_bridge_proof(
                "SCCP settlement amount must be non-zero",
            ));
        }
        let amount = Numeric::try_new(amount, settlement.payload_amount_scale).map_err(|error| {
            invalid_bridge_proof(format!(
                "SCCP settlement amount is not exactly representable at governed scale {}: {error}",
                settlement.payload_amount_scale
            ))
        })?;
        Quantity::from_canonical_numeric(amount).map_err(|error| {
            invalid_bridge_proof(format!(
                "SCCP settlement amount is outside the non-negative quantity domain: {error}"
            ))
        })
    }
    fn validate_sccp_outbound_transfer_and_lock(
        transfer: &iroha_sccp::TransferPayloadV1,
        authority: &AccountId,
        settlement: &ResolvedSccpSettlementRouteV1,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        validate_sccp_route_fields_match_manifest(
            transfer.route_id_codec,
            &transfer.route_id,
            transfer.asset_id_codec,
            &transfer.asset_id,
            transfer.route_revision,
            settlement,
        )?;
        if transfer.asset_home_domain != iroha_sccp::SCCP_DOMAIN_SORA {
            return Err(invalid_bridge_proof(
                "first-release SCCP settlement only supports SORA-home assets",
            ));
        }
        let local_account_codec =
            iroha_sccp::sccp_counterparty_account_codec(iroha_sccp::SCCP_DOMAIN_SORA)
                .expect("SORA account codec is defined by the SCCP profile");
        if transfer.sender_codec != local_account_codec {
            return Err(invalid_bridge_proof(
                "SCCP outbound sender must use the canonical SORA account codec",
            ));
        }
        let sender_literal = core::str::from_utf8(&transfer.sender)
            .map_err(|_| invalid_bridge_proof("SCCP outbound sender is not valid UTF-8"))?;
        let sender_address = iroha_data_model::account::AccountAddress::parse_encoded(
            sender_literal,
            Some(iroha_sccp::SCCP_TAIRA_I105_DISCRIMINANT_V1),
        )
        .map_err(|error| {
            invalid_bridge_proof(format!(
                "SCCP outbound sender is not an exact Taira I105 account: {error}"
            ))
        })?;
        let canonical_sender = sender_address
            .to_i105_for_discriminant(iroha_sccp::SCCP_TAIRA_I105_DISCRIMINANT_V1)
            .map_err(|error| {
                invalid_bridge_proof(format!(
                    "SCCP outbound sender cannot be rendered canonically: {error}"
                ))
            })?;
        let sender = sender_address.to_account_id().map_err(|error| {
            invalid_bridge_proof(format!(
                "SCCP outbound sender controller is invalid: {error}"
            ))
        })?;
        if canonical_sender != sender_literal || &sender != authority {
            return Err(invalid_bridge_proof(
                "SCCP outbound sender must be the exact canonical transaction authority",
            ));
        }
        if !iroha_sccp::sccp_destination_contract_supports_account_v1(authority) {
            return Err(invalid_bridge_proof(
                "SCCP outbound sender controller is not supported by the V1 destination contracts",
            ));
        }
        if transfer.recipient_codec != settlement.counterparty_account_codec {
            return Err(invalid_bridge_proof(
                "SCCP outbound recipient codec does not match the exact external profile",
            ));
        }
        if settlement.escrow_account_id == *authority {
            return Err(invalid_bridge_proof(
                "SCCP route protocol escrow must differ from the outbound sender",
            ));
        }
        state_transaction
            .world
            .asset_definition(&settlement.settlement_asset_definition_id)?;
        ensure_sccp_route_escrow_account(
            &settlement.route_key,
            &settlement.settlement_asset_definition_id,
            state_transaction,
        )?;
        let amount = sccp_payload_amount(transfer.amount, settlement)?;
        state_transaction.require_transfer_transcript_identity("SCCP message recording")?;
        crate::smartcontracts::isi::asset::isi::execute_sccp_outbound_route_lock(
            state_transaction,
            authority,
            &settlement.route_key,
            &settlement.settlement_asset_definition_id,
            transfer.amount,
            amount,
        )
    }
    impl Execute for bridge::RecordSccpMessage {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let execution_binding = state_transaction
                .sccp_ivm_proved_execution_binding
                .clone()
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "SCCP message recording requires a structured verified IVM execution binding"
                            .into(),
                    )
                })?;
            ensure_sccp_outbound_lane_is_active(state_transaction)?;
            let validated = match crate::bridge::validate_recorded_sccp_message_payload_bytes(
                self.context,
                &self.payload_bytes,
            ) {
                Ok(validated) => validated,
                Err(crate::bridge::RecordedSccpMessageValidationError::InvalidPayload) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "SCCP payload bytes could not be decoded".into(),
                        ),
                    ));
                }
                Err(crate::bridge::RecordedSccpMessageValidationError::InvalidContext) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "SCCP outbound context must be an exact SORA-to-external lane with distinct nonzero destination-binding and route-configuration hashes".into(),
                        ),
                    ));
                }
                Err(crate::bridge::RecordedSccpMessageValidationError::NonSoraSource {
                    ..
                }) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "SCCP message recording only accepts SORA-origin payloads; submit non-SORA source messages with a verified source-chain proof envelope".into(),
                        ),
                    ));
                }
                Err(crate::bridge::RecordedSccpMessageValidationError::TargetProfileMismatch {
                    target,
                    payload_target_domain,
                }) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!(
                            "SCCP outbound payload target domain {payload_target_domain} does not match exact context profile `{}`",
                            target.profile_key()
                        )),
                    ));
                }
                Err(crate::bridge::RecordedSccpMessageValidationError::HashRoleCollision) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "SCCP outbound destination binding, route configuration, message id, and payload hash must be pairwise distinct".into(),
                        ),
                    ));
                }
                Err(crate::bridge::RecordedSccpMessageValidationError::RouteBinding { error }) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!(
                            "SORA-origin SCCP outbound payload {error}"
                        )),
                    ));
                }
            };
            let iroha_sccp::SccpPayloadV1::Transfer(transfer) = &validated.payload;
            let settlement = validate_current_sccp_outbound_record_governance(
                validated.context,
                transfer,
                state_transaction,
            )?;
            let execution_policy = &settlement.sora_outbound_execution_policy;
            if execution_binding.contract_artifact_sha256
                != execution_policy.contract_artifact_sha256
                || !execution_policy.vk_ref.matches(
                    &execution_binding.vk_ref,
                    execution_binding.vk_version,
                    execution_binding.vk_commitment,
                )
                || execution_binding.gas_limit != execution_policy.gas_limit
                || execution_binding.gas_used > execution_binding.gas_limit
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "SCCP message recording proved execution does not match the enabled route's governed contract artifact, verification key, and gas policy"
                        .into(),
                ));
            }
            let key = validated.key.clone();
            if state_transaction
                .world
                .sccp_outbound_pending_messages
                .get(&key)
                .is_some()
                || state_transaction
                    .world
                    .sccp_outbound_message_locator
                    .get(&key.message_id)
                    .is_some()
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "SCCP outbound message has already been recorded".into(),
                    ),
                ));
            }
            let recorded_at_height = state_transaction._curr_block.height.get();
            let commitment_index = match crate::bridge::next_sccp_outbound_commitment_index(
                &state_transaction.world.sccp_outbound_message_index,
                recorded_at_height,
            ) {
                Ok(Some(index)) => index,
                Ok(None) => {
                    return Err(InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(format!(
                                "SCCP outbound messages at block height {recorded_at_height} reached the fixed {}-message limit",
                                iroha_data_model::bridge::SCCP_OUTBOUND_MESSAGES_MAX_PER_BLOCK_V1
                            ))
                            .into(),
                        ));
                }
                Err(reason) => {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "SCCP outbound commitment index is corrupt before insertion: {reason}"
                        )
                        .into(),
                    ));
                }
            };
            let record = validated
                .outbound_record(recorded_at_height, commitment_index)
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                    "validated SCCP outbound message could not form its durable canonical record"
                        .into(),
                )
                })?;
            let index_key =
                iroha_data_model::bridge::SccpOutboundMessageIndexKeyV1::new(key, &record)
                    .ok_or_else(|| {
                        InstructionExecutionError::InvariantViolation(
                            "validated SCCP outbound message could not form its ordered locator"
                                .into(),
                        )
                    })?;
            let current_usage = *state_transaction.world.sccp_outbound_pending_usage.get();
            if !current_usage.is_structurally_valid() {
                return Err(InstructionExecutionError::InvariantViolation(
                    "SCCP pending outbound usage is structurally corrupt before insertion".into(),
                ));
            }
            let next_usage = current_usage
                .checked_add_payload(record.payload_bytes.len())
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "SCCP pending outbound usage overflow before insertion".into(),
                    )
                })?;
            let limits = state_transaction.zk.sccp;
            if next_usage.message_count > limits.max_pending_outbound_messages.get()
                || next_usage.payload_bytes > limits.max_pending_outbound_payload_bytes.get()
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "SCCP pending outbound capacity exceeded: requested messages={} bytes={}, configured maxima messages={} bytes={}",
                        next_usage.message_count,
                        next_usage.payload_bytes,
                        limits.max_pending_outbound_messages,
                        limits.max_pending_outbound_payload_bytes,
                    )),
                ));
            }
            let replay_accumulator_id = iroha_data_model::bridge::SccpReplayAccumulatorIdV1 {
                route_key: settlement.route_key.clone(),
                boundary: iroha_data_model::bridge::SccpReplayBoundaryV1::SoraOutboundLock,
            };
            let replay_domain = iroha_data_model::bridge::SccpReplayDomainV1 {
                source_network: validated.context.lane.source,
                target_network: validated.context.lane.target,
                boundary: iroha_data_model::bridge::SccpReplayBoundaryV1::SoraOutboundLock,
                route_revision: settlement.route_key.revision,
                route_configuration_hash: settlement.route_configuration_hash,
                actor: iroha_data_model::bridge::SccpReplayActorV1::Route,
            };
            let replay_record = iroha_data_model::bridge::SccpReplayRecordV1 {
                operation: iroha_data_model::bridge::SccpReplayBoundaryV1::SoraOutboundLock,
                replay_id: key.message_id,
                payload_sha256: sha2::Sha256::digest(&record.payload_bytes).into(),
                amount: transfer.amount,
                principal: iroha_data_model::bridge::SccpReplayPrincipalV1::SoraAccount(
                    authority.clone(),
                ),
                auxiliary_identity_sha256: sha2::Sha256::digest(record.destination_binding_hash)
                    .into(),
            };
            let replay_mutation = state_transaction.prepare_sccp_replay_leaf(
                replay_accumulator_id,
                &replay_domain,
                &replay_record,
                &self.replay_witness,
            )?;
            validate_sccp_outbound_transfer_and_lock(
                transfer,
                authority,
                &settlement,
                state_transaction,
            )?;
            state_transaction
                .world
                .sccp_outbound_pending_messages
                .insert(key, record);
            state_transaction
                .world
                .sccp_outbound_message_locator
                .insert(key.message_id, key);
            state_transaction
                .world
                .sccp_outbound_message_index
                .insert(index_key, ());
            *state_transaction
                .world
                .sccp_outbound_pending_usage
                .get_mut() = next_usage;
            state_transaction.apply_sccp_replay_leaf(replay_mutation)?;
            Ok(())
        }
    }
    fn resolve_vk_commitment(
        attachment: &iroha_data_model::proof::ProofAttachment,
        envelope: Option<&ZkOpenVerifyEnvelope>,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<Option<[u8; 32]>, Error> {
        let id = &attachment.vk_ref;
        let Some(rec) = state_transaction.world.verifying_keys.get(id) else {
            return Err(InstructionExecutionError::InvariantViolation(
                "proof must reference a registered verifying key reference; inline verifying keys are not supported"
                    .into(),
            )
            .into());
        };
        if !rec.is_active_at(state_transaction.block_height()) {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key is not active".into(),
            ));
        }
        if rec.gas_schedule_id.is_none() {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key missing gas_schedule_id".into(),
            ));
        }
        let circuit_key = (rec.circuit_id.clone(), rec.version);
        match state_transaction
            .world
            .verifying_keys_by_circuit
            .get(&circuit_key)
        {
            Some(mapped) if mapped == id => {}
            _ => {
                return Err(InstructionExecutionError::InvariantViolation(
                    "verifying key circuit/version not active".into(),
                ));
            }
        }
        if let Some(env) = envelope {
            validate_open_verify_envelope_metadata("proof", attachment.backend.as_str(), env, rec)?;
        }
        Ok(Some(rec.commitment))
    }
    fn ensure_unique_proof(
        state_transaction: &StateTransaction<'_, '_>,
        pid: &ProofId,
    ) -> Result<(), Error> {
        if state_transaction.world.proofs.get(pid).is_some() {
            return Err(RepetitionError {
                instruction: InstructionType::Register,
                id: IdBox::Permission(Permission::new(
                    "Proof".into(),
                    iroha_primitives::json::Json::from(
                        format!("{}:{:x?}", &pid.backend, &pid.proof_hash[..4]).as_str(),
                    ),
                )),
            }
            .into());
        }
        Ok(())
    }
    fn verify_proof_backend(
        attachment: &iroha_data_model::proof::ProofAttachment,
        proof: &iroha_data_model::proof::ProofBox,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(bool, Duration), Error> {
        if crate::zk::is_stark_fri_v1_backend(attachment.backend.as_str())
            && !state_transaction.zk.stark.enabled
        {
            return Err(InstructionExecutionError::InvariantViolation(
                "stark verification is disabled in node configuration".into(),
            ));
        }
        let record = state_transaction
            .world
            .verifying_keys
            .get(&attachment.vk_ref)
            .cloned()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation("verifying key not found".into())
            })?;
        crate::zk::validate_and_prepare_verifying_key_record_v1(&attachment.vk_ref, &record)
            .map_err(|err| {
                InstructionExecutionError::InvariantViolation(
                    format!("invalid stored verifying-key record: {err}").into(),
                )
            })?;
        let vk_box = record.key.clone().ok_or_else(|| {
            InstructionExecutionError::InvariantViolation("verifying key bytes missing".into())
        })?;
        let commitment = hash_vk(&vk_box);
        if record.commitment != commitment {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key commitment mismatch".into(),
            ));
        }
        if vk_box.backend != attachment.backend {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key backend mismatch".into(),
            ));
        }
        let report = crate::zk::verify_backend_with_timing_checked(
            attachment.backend.as_str(),
            proof,
            Some(&vk_box),
            &state_transaction.zk,
        );
        Ok((report.ok, report.elapsed))
    }
    fn index_proof_tags(world: &mut WorldTransaction<'_, '_>, pid: &ProofId, proof_bytes: &[u8]) {
        let mut tags = zk1_list_tags(proof_bytes);
        if tags.is_empty() {
            return;
        }
        tags.sort_unstable();
        tags.dedup();
        world.proof_tags.insert(pid.clone(), tags.clone());
        for tag in tags {
            let tag_slice: &[u8] = &tag;
            let mut ids = world
                .proofs_by_tag
                .get(tag_slice)
                .cloned()
                .unwrap_or_default();
            if !ids.iter().any(|existing| existing == pid) {
                ids.push(pid.clone());
                ids.sort();
            }
            world.proofs_by_tag.insert(tag, ids);
        }
    }
    fn proof_retention_removals(
        mut items: Vec<(ProofId, u64)>,
        cap: usize,
        grace_blocks: u64,
        prune_batch: usize,
        current_height: u64,
    ) -> Vec<ProofId> {
        if items.is_empty() {
            return Vec::new();
        }
        items.sort_by_key(|(_, height)| *height);
        let retention_floor =
            (grace_blocks > 0).then(|| current_height.saturating_sub(grace_blocks));
        // Always keep at least this many newest entries even if they fall outside the grace window
        // so we do not prune the entire registry when all proofs are old.
        let min_keep = if cap == 0 {
            usize::try_from(grace_blocks).unwrap_or(usize::MAX)
        } else {
            let cap_u64 = u64::try_from(cap).unwrap_or(u64::MAX);
            let bounded = grace_blocks.min(cap_u64);
            usize::try_from(bounded).unwrap_or(usize::MAX)
        };
        let mut retained: Vec<(ProofId, u64)> = Vec::new();
        let mut stale: Vec<(ProofId, u64)> = Vec::new();
        for (id, height) in items {
            if let Some(floor) = retention_floor {
                if height < floor {
                    stale.push((id, height));
                } else {
                    retained.push((id, height));
                }
            } else {
                retained.push((id, height));
            }
        }
        if retained.len() < min_keep {
            let deficit = min_keep - retained.len();
            let keep_from_stale = stale.split_off(stale.len().saturating_sub(deficit));
            retained.extend(keep_from_stale);
        }
        retained.sort_by_key(|(_, height)| *height);
        let mut removals: Vec<ProofId> = stale.into_iter().map(|(id, _)| id).collect();
        if cap > 0 && retained.len() > cap {
            let overflow = retained.len() - cap;
            removals.extend(retained.into_iter().take(overflow).map(|(id, _)| id));
        }
        if prune_batch > 0 && removals.len() > prune_batch {
            removals.truncate(prune_batch);
        }
        removals
    }
    #[cfg(test)]
    mod retention_tests {
        use super::*;
        #[test]
        fn retention_prunes_entries_older_than_grace_window() {
            let backend = "halo2/ipa";
            let items: Vec<_> = (1u64..=4)
                .map(|height| {
                    let proof_height = u8::try_from(height).unwrap_or(u8::MAX);
                    (
                        ProofId {
                            backend: backend.into(),
                            proof_hash: [proof_height; 32],
                        },
                        height,
                    )
                })
                .collect();
            let removals = proof_retention_removals(items, 10, 2, 10, 9);
            assert_eq!(removals.len(), 2);
            let hashes: Vec<u8> = removals.iter().map(|id| id.proof_hash[0]).collect();
            assert!(hashes.contains(&1));
            assert!(hashes.contains(&2));
        }
        #[test]
        fn retention_respects_prune_batch_limit() {
            let backend = "halo2/ipa";
            let items: Vec<_> = (0u64..5)
                .map(|height| {
                    let proof_height = u8::try_from(height).unwrap_or(u8::MAX);
                    (
                        ProofId {
                            backend: backend.into(),
                            proof_hash: [proof_height; 32],
                        },
                        height,
                    )
                })
                .collect();
            let removals = proof_retention_removals(items, 1, 0, 2, 5);
            assert_eq!(removals.len(), 2);
            let hashes: Vec<u8> = removals.iter().map(|id| id.proof_hash[0]).collect();
            assert!(hashes.contains(&0));
            assert!(hashes.contains(&1));
        }
        #[test]
        fn retention_keeps_minimum_entries_when_all_are_stale() {
            let backend = "halo2/ipa";
            let items: Vec<_> = (1u64..=6)
                .map(|height| {
                    let proof_height = u8::try_from(height).unwrap_or(u8::MAX);
                    (
                        ProofId {
                            backend: backend.into(),
                            proof_hash: [proof_height; 32],
                        },
                        height,
                    )
                })
                .collect();
            // Everything is older than the grace window; we still keep the newest three
            // entries because grace_blocks acts as a floor when cap=0.
            let removals = proof_retention_removals(items, 0, 3, 10, 20);
            let hashes: Vec<u8> = removals.iter().map(|id| id.proof_hash[0]).collect();
            assert_eq!(hashes.len(), 3);
            assert!(hashes.contains(&1));
            assert!(hashes.contains(&2));
            assert!(hashes.contains(&3));
            assert!(!hashes.contains(&4));
            assert!(!hashes.contains(&5));
            assert!(!hashes.contains(&6));
        }
    }
    struct ProofPruneOutcome {
        backend: String,
        removed: Vec<ProofId>,
        remaining: u64,
    }
    fn prune_proof_entries(state_transaction: &mut StateTransaction<'_, '_>, removals: &[ProofId]) {
        for old_id in removals {
            if let Some(existing_tags) = state_transaction.world.proof_tags.get(old_id) {
                for tag in existing_tags {
                    let tag_slice: &[u8] = &tag[..];
                    let mut ids = state_transaction
                        .world
                        .proofs_by_tag
                        .get(tag_slice)
                        .cloned()
                        .unwrap_or_default();
                    ids.retain(|entry| entry != old_id);
                    if ids.is_empty() {
                        state_transaction.world.proofs_by_tag.remove(*tag);
                    } else {
                        state_transaction.world.proofs_by_tag.insert(*tag, ids);
                    }
                }
            }
            state_transaction.world.proof_tags.remove(old_id.clone());
            state_transaction.world.remove_proof_record(old_id);
        }
    }
    fn enforce_proof_history_cap(
        state_transaction: &mut StateTransaction<'_, '_>,
        backend: &str,
        cap: usize,
        grace_blocks: u64,
        prune_batch: usize,
        current_height: u64,
    ) -> Option<ProofPruneOutcome> {
        let items: Vec<(ProofId, u64)> = state_transaction
            .world
            .proofs
            .iter()
            .filter(|(id, _)| id.backend == backend)
            .map(|(id, rec)| (id.clone(), rec.verified_at_height.unwrap_or(0)))
            .collect();
        let removals =
            proof_retention_removals(items, cap, grace_blocks, prune_batch, current_height);
        if removals.is_empty() {
            return None;
        }
        iroha_logger::info!(
            backend,
            removed = removals.len(),
            cap,
            grace_blocks,
            prune_batch,
            "pruned proof registry entries for retention"
        );
        let removed = removals;
        prune_proof_entries(state_transaction, &removed);
        let remaining = state_transaction
            .world
            .proofs
            .iter()
            .filter(|(id, _)| id.backend == backend)
            .count() as u64;
        Some(ProofPruneOutcome {
            backend: backend.to_owned(),
            removed,
            remaining,
        })
    }
    fn enforce_bridge_history_cap(
        state_transaction: &mut StateTransaction<'_, '_>,
        backend: &str,
        cap: usize,
        grace_blocks: u64,
        prune_batch: usize,
        current_height: u64,
    ) -> Option<ProofPruneOutcome> {
        let items: Vec<(ProofId, u64)> = state_transaction
            .world
            .proofs
            .iter()
            .filter(|(id, rec)| id.backend == backend && rec.bridge.is_some())
            .map(|(id, rec)| (id.clone(), rec.verified_at_height.unwrap_or(0)))
            .collect();
        let removals =
            proof_retention_removals(items, cap, grace_blocks, prune_batch, current_height);
        if removals.is_empty() {
            return None;
        }
        iroha_logger::info!(
            backend,
            removed = removals.len(),
            cap,
            grace_blocks,
            prune_batch,
            "pruned bridge proof registry entries for retention"
        );
        let removed = removals;
        prune_proof_entries(state_transaction, &removed);
        let remaining = state_transaction
            .world
            .proofs
            .iter()
            .filter(|(id, rec)| id.backend == backend && rec.bridge.is_some())
            .count() as u64;
        Some(ProofPruneOutcome {
            backend: backend.to_owned(),
            removed,
            remaining,
        })
    }
    fn hash_bridge_proof(backend: &str, payload: &[u8]) -> [u8; 32] {
        crate::zk::hash_proof(&iroha_data_model::proof::ProofBox::new(
            backend.to_owned(),
            payload.to_vec(),
        ))
    }
    fn find_overlapping_bridge_range(
        state_transaction: &StateTransaction<'_, '_>,
        backend: &str,
        new_range: &iroha_data_model::bridge::BridgeProofRange,
    ) -> Option<ProofId> {
        state_transaction.world.proofs.iter().find_map(|(id, rec)| {
            let bridge = rec.bridge.as_ref()?;
            if id.backend != backend {
                return None;
            }
            if ranges_overlap(&bridge.proof.range, new_range) {
                Some(id.clone())
            } else {
                None
            }
        })
    }
    fn ranges_overlap(
        a: &iroha_data_model::bridge::BridgeProofRange,
        b: &iroha_data_model::bridge::BridgeProofRange,
    ) -> bool {
        a.start_height <= b.end_height && b.start_height <= a.end_height
    }
    fn zk1_list_tags(bytes: &[u8]) -> Vec<[u8; 4]> {
        if bytes.len() < 8 {
            return Vec::new();
        }
        if &bytes[..4] != b"ZK1\0" {
            return Vec::new();
        }
        let mut pos = 4usize;
        let mut out = Vec::new();
        while pos + 8 <= bytes.len() {
            let mut tag = [0u8; 4];
            tag.copy_from_slice(&bytes[pos..pos + 4]);
            let len = u32::from_le_bytes([
                bytes[pos + 4],
                bytes[pos + 5],
                bytes[pos + 6],
                bytes[pos + 7],
            ]) as usize;
            pos += 8;
            if pos + len > bytes.len() {
                break;
            }
            out.push(tag);
            pos += len;
        }
        out
    }
    // --- ZK Asset policy & ledger ---
    #[derive(Clone)]
    struct PolicyMetadataContext {
        vk_unshield: Option<iroha_data_model::proof::VerifyingKeyId>,
        vk_unshield_commitment: Option<[u8; 32]>,
        vk_shield: Option<iroha_data_model::proof::VerifyingKeyId>,
        vk_shield_commitment: Option<[u8; 32]>,
    }
    fn metadata_context_from_state(
        state: Option<&crate::state::ZkAssetState>,
    ) -> PolicyMetadataContext {
        state.map_or(
            PolicyMetadataContext {
                vk_unshield: None,
                vk_unshield_commitment: None,
                vk_shield: None,
                vk_shield_commitment: None,
            },
            |st| PolicyMetadataContext {
                vk_unshield: st.vk_unshield.as_ref().map(|binding| binding.id.clone()),
                vk_unshield_commitment: st.vk_unshield.as_ref().map(|binding| binding.commitment),
                vk_shield: st.vk_shield.as_ref().map(|binding| binding.id.clone()),
                vk_shield_commitment: st.vk_shield.as_ref().map(|binding| binding.commitment),
            },
        )
    }
    fn persist_policy_metadata(
        state_transaction: &mut StateTransaction<'_, '_>,
        asset_def_id: &AssetDefinitionId,
        policy: &AssetConfidentialPolicy,
        context: &PolicyMetadataContext,
    ) -> Result<(), Error> {
        let mut policy_map = BTreeMap::new();
        policy_map.insert(
            "mode".into(),
            norito::json::native::Value::from(format!("{:?}", policy.mode())),
        );
        let vk_to_value =
            |vk: Option<iroha_data_model::proof::VerifyingKeyId>| -> norito::json::native::Value {
                vk.map_or(norito::json::native::Value::Null, |id| {
                    norito::json::native::Value::from(format!("{}::{}", id.backend, id.name))
                })
            };
        policy_map.insert(
            "vk_unshield".into(),
            vk_to_value(context.vk_unshield.clone()),
        );
        policy_map.insert(
            "vk_unshield_commitment".into(),
            context
                .vk_unshield_commitment
                .map_or(norito::json::native::Value::Null, |commitment| {
                    norito::json::native::Value::from(hex::encode(commitment))
                }),
        );
        policy_map.insert("vk_shield".into(), vk_to_value(context.vk_shield.clone()));
        policy_map.insert(
            "vk_shield_commitment".into(),
            context
                .vk_shield_commitment
                .map_or(norito::json::native::Value::Null, |commitment| {
                    norito::json::native::Value::from(hex::encode(commitment))
                }),
        );
        let pending_value =
            policy
                .pending_transition()
                .map_or(norito::json::native::Value::Null, |pending| {
                    let mut pending_map = BTreeMap::new();
                    pending_map.insert(
                        "new_mode".into(),
                        norito::json::native::Value::from(format!("{:?}", pending.new_mode())),
                    );
                    pending_map.insert(
                        "effective_height".into(),
                        norito::json::native::Value::from(pending.effective_height()),
                    );
                    pending_map.insert(
                        "previous_mode".into(),
                        norito::json::native::Value::from(format!("{:?}", pending.previous_mode())),
                    );
                    pending_map.insert(
                        "transition_id".into(),
                        norito::json::native::Value::from(hex::encode(
                            pending.transition_id().as_ref(),
                        )),
                    );
                    if let Some(window) = pending.conversion_window() {
                        pending_map.insert(
                            "conversion_window".into(),
                            norito::json::native::Value::from(*window),
                        );
                    }
                    norito::json::native::Value::Object(pending_map)
                });
        policy_map.insert("pending_transition".into(), pending_value);
        let features_digest_hex = hex::encode(policy.features_digest().as_ref());
        policy_map.insert(
            "features_digest".into(),
            norito::json::native::Value::from(features_digest_hex),
        );
        let policy_json =
            iroha_primitives::json::Json::from(norito::json::native::Value::Object(policy_map));
        let key: Name = "zk.policy".parse().unwrap();
        {
            let asset_definition = state_transaction
                .world
                .asset_definition_mut(asset_def_id)
                .map_err(Error::from)?;
            asset_definition
                .metadata_mut()
                .insert(key.clone(), policy_json.clone());
        }
        state_transaction.world.emit_events(Some(
            iroha_data_model::prelude::AssetDefinitionEvent::MetadataInserted(
                iroha_data_model::prelude::MetadataChanged {
                    target: asset_def_id.clone(),
                    key,
                    value: policy_json,
                },
            ),
        ));
        Ok(())
    }
    pub(crate) fn apply_policy_if_due(
        state_transaction: &mut StateTransaction<'_, '_>,
        asset_def_id: &AssetDefinitionId,
    ) -> Result<AssetConfidentialPolicy, Error> {
        let block_height = state_transaction.block_height();
        let mut changed = false;
        let current_policy = {
            let asset_definition = state_transaction
                .world
                .asset_definition(asset_def_id)
                .map_err(Error::from)?;
            *asset_definition.confidential_policy()
        };
        let mut working_policy = current_policy;
        let mut aborted = false;
        let pending_transition = working_policy.pending_transition;
        if let Some(transition) = pending_transition {
            let transition_matches_active_mode =
                transition.previous_mode() == working_policy.mode();
            let transition_is_supported = matches!(
                (working_policy.mode(), transition.new_mode()),
                (
                    ConfidentialPolicyMode::Convertible,
                    ConfidentialPolicyMode::ShieldedOnly
                ) | (
                    ConfidentialPolicyMode::ShieldedOnly,
                    ConfidentialPolicyMode::Convertible
                )
            );
            if !transition_matches_active_mode || !transition_is_supported {
                aborted = true;
                working_policy.pending_transition = None;
                iroha_logger::warn!(
                    asset = %asset_def_id,
                    current_mode = %working_policy.mode(),
                    previous_mode = %transition.previous_mode(),
                    new_mode = %transition.new_mode(),
                    "discarding confidential policy transition outside the ABI V1 state machine"
                );
            } else if block_height >= transition.effective_height()
                && transition.new_mode() == ConfidentialPolicyMode::ShieldedOnly
            {
                let transparent_total = state_transaction
                    .world
                    .asset_total_amount(asset_def_id)
                    .map_err(Error::from)?;
                if transparent_total > Quantity::zero() {
                    aborted = true;
                    working_policy.pending_transition = None;
                    iroha_logger::warn!(
                        asset = %asset_def_id,
                        total = %transparent_total,
                        "aborting confidential policy transition: non-zero transparent supply"
                    );
                }
            }
        }
        let (candidate_policy, did_change) = if aborted {
            let changed_flag = working_policy != current_policy;
            (working_policy, changed_flag)
        } else {
            working_policy.apply_if_due(block_height)
        };
        let applied_policy = if did_change {
            if let Some(transition) = pending_transition {
                state_transaction
                    .world
                    .untrack_confidential_policy_transition(
                        asset_def_id,
                        transition.effective_height(),
                    );
            }
            {
                let asset_definition = state_transaction
                    .world
                    .asset_definition_mut(asset_def_id)
                    .map_err(Error::from)?;
                asset_definition.set_confidential_policy(candidate_policy);
            }
            changed = true;
            candidate_policy
        } else {
            current_policy
        };
        if changed {
            let context =
                metadata_context_from_state(state_transaction.world.zk_assets.get(asset_def_id));
            persist_policy_metadata(state_transaction, asset_def_id, &applied_policy, &context)?;
        }
        Ok(applied_policy)
    }
    struct PolicyTransitionValidation {
        current_mode: ConfidentialPolicyMode,
        new_mode: ConfidentialPolicyMode,
        block_height: u64,
        effective_height: u64,
        delay_blocks: u64,
        window_blocks: u64,
        requested_window: Option<u64>,
    }
    fn validate_policy_transition(args: &PolicyTransitionValidation) -> Result<(), Error> {
        ensure_mode_change(args)?;
        ensure_transition_allowed(args)?;
        let lead_time = ensure_effective_height(args)?;
        ensure_notice_window(args, lead_time)?;
        Ok(())
    }
    fn ensure_mode_change(args: &PolicyTransitionValidation) -> Result<(), Error> {
        if args.new_mode == args.current_mode {
            Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "confidential policy transition keeps the same mode".into(),
                ),
            ))
        } else {
            Ok(())
        }
    }
    fn ensure_effective_height(args: &PolicyTransitionValidation) -> Result<u64, Error> {
        if args.effective_height <= args.block_height {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "effective height must be in the future".into(),
                ),
            ));
        }
        let lead_time = args.effective_height.saturating_sub(args.block_height);
        if lead_time < args.delay_blocks {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(format!(
                    "effective height must be at least {delay_blocks} blocks ahead",
                    delay_blocks = args.delay_blocks,
                )),
            ));
        }
        Ok(lead_time)
    }
    fn ensure_notice_window(
        args: &PolicyTransitionValidation,
        lead_time: u64,
    ) -> Result<(), Error> {
        if args.new_mode == ConfidentialPolicyMode::ShieldedOnly
            && args.window_blocks > 0
            && lead_time < args.window_blocks
        {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(format!(
                    "confidential policy transition must provide at least {window_blocks} blocks of notice",
                    window_blocks = args.window_blocks,
                )),
            ));
        }
        if args.new_mode == ConfidentialPolicyMode::ShieldedOnly {
            let window = args.requested_window.ok_or_else(|| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    "conversion window is required when transitioning to ShieldedOnly".into(),
                ))
            })?;
            if window == 0 {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "conversion window must be greater than zero".into(),
                    ),
                ));
            }
            if window < args.window_blocks {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "conversion window must be at least {window_blocks} blocks",
                        window_blocks = args.window_blocks,
                    )),
                ));
            }
            if window > lead_time {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "conversion window cannot exceed lead time before effective height".into(),
                    ),
                ));
            }
            Ok(())
        } else {
            if args.requested_window.is_some() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "conversion window is only supported for ShieldedOnly transitions".into(),
                    ),
                ));
            }
            Ok(())
        }
    }
    fn ensure_transition_allowed(args: &PolicyTransitionValidation) -> Result<(), Error> {
        match (args.current_mode, args.new_mode) {
            (ConfidentialPolicyMode::TransparentOnly, _) => {
                Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "a TransparentOnly asset must activate confidentiality by registering at least one canonical verifier role"
                            .into(),
                    ),
                ))
            }
            (ConfidentialPolicyMode::Convertible, ConfidentialPolicyMode::ShieldedOnly)
            | (ConfidentialPolicyMode::ShieldedOnly, ConfidentialPolicyMode::Convertible) => Ok(()),
            (
                ConfidentialPolicyMode::Convertible | ConfidentialPolicyMode::ShieldedOnly,
                ConfidentialPolicyMode::TransparentOnly,
            ) => Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "confidentiality is irreversible in ABI V1; a confidential asset cannot transition back to TransparentOnly"
                        .into(),
                ),
            )),
            _ => Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "unsupported confidential policy transition".into(),
                ),
            )),
        }
    }
    fn ensure_can_modify_confidential_policy(
        authority: &AccountId,
        state_transaction: &StateTransaction<'_, '_>,
        asset_def_id: &AssetDefinitionId,
    ) -> Result<(), Error> {
        let asset_definition = state_transaction
            .world
            .asset_definition(asset_def_id)
            .map_err(Error::from)?;
        let asset_definition_owner = asset_definition.owned_by();
        let required: Permission = CanManageAssetDefinitionConfidentialPolicy {
            asset_definition: asset_def_id.clone(),
        }
        .into();
        if asset_definition_owner == authority
            || has_exact_permission(&state_transaction.world, authority, &required)
        {
            Ok(())
        } else {
            Err(InstructionExecutionError::InvariantViolation(
                "not permitted: asset-definition owner or exact CanManageAssetDefinitionConfidentialPolicy grant required"
                    .into(),
            ))
        }
    }
    fn ensure_committed_unshield_binding_is_preserved(
        existing_state: Option<&crate::state::ZkAssetState>,
        next_unshield: Option<&crate::state::ZkAssetVerifierBinding>,
    ) -> Result<(), Error> {
        let Some(existing_state) = existing_state.filter(|state| !state.commitments.is_empty())
        else {
            return Ok(());
        };
        let existing_unshield = existing_state.vk_unshield.as_ref().ok_or_else(|| {
            InstructionExecutionError::InvariantViolation(
                "confidential commitments exist without a bound unshield verifier".into(),
            )
        })?;
        let next_unshield = next_unshield.ok_or_else(|| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                "vk_unshield cannot be cleared while confidential commitments exist".into(),
            ))
        })?;
        if next_unshield.commitment != existing_unshield.commitment {
            return Err(InstructionExecutionError::InvalidParameter(
                InvalidParameterError::SmartContract(
                    "vk_unshield commitment cannot change while confidential commitments exist"
                        .into(),
                ),
            ));
        }
        Ok(())
    }
    impl Execute for zk::RegisterZkAsset {
        #[allow(clippy::too_many_lines)]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let asset_def_id = self.asset().clone();
            ensure_can_modify_confidential_policy(authority, state_transaction, &asset_def_id)?;
            self.validate_verifier_roles().map_err(|message| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    message.into(),
                ))
            })?;
            // Derive the canonical policy from the two verifier roles. Optional
            // binding presence is the sole enablement signal in ABI V1.
            let current_policy = *state_transaction
                .world
                .asset_definition(&asset_def_id)
                .map_err(Error::from)?
                .confidential_policy();
            let has_confidential_role = self.vk_shield().is_some() || self.vk_unshield().is_some();
            let policy_mode = match current_policy.mode() {
                ConfidentialPolicyMode::TransparentOnly if has_confidential_role => {
                    ConfidentialPolicyMode::Convertible
                }
                mode => mode,
            };
            let resolve_binding = |vk: &Option<iroha_data_model::proof::VerifyingKeyId>| -> Result<
                Option<crate::state::ZkAssetVerifierBinding>,
                Error,
            > {
                let Some(id) = vk.clone() else {
                    return Ok(None);
                };
                let Some(rec) = state_transaction.world.verifying_keys.get(&id) else {
                    return Err(FindError::Permission(Box::new(Permission::new(
                        "VerifyingKeyMissing".into(),
                        iroha_primitives::json::Json::from(
                            format!("{}::{}", id.backend, id.name).as_str(),
                        ),
                    )))
                    .into());
                };
                if !rec.is_active_at(state_transaction.block_height()) {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "verifying key is not active".into(),
                    ));
                }
                Ok(Some(crate::state::ZkAssetVerifierBinding {
                    id,
                    commitment: rec.commitment,
                }))
            };
            let vk_unshield_binding = resolve_binding(self.vk_unshield())?;
            let vk_shield_binding = resolve_binding(self.vk_shield())?;
            let existing_state = state_transaction
                .world
                .zk_assets
                .get(&asset_def_id)
                .cloned();
            ensure_committed_unshield_binding_is_preserved(
                existing_state.as_ref(),
                vk_unshield_binding.as_ref(),
            )?;
            if let Some(binding) = vk_unshield_binding.as_ref() {
                let record = state_transaction
                    .world
                    .verifying_keys
                    .get(&binding.id)
                    .expect("binding was resolved from the verifying-key registry");
                let is_v2 = crate::zk::confidential_v2::is_confidential_unshield_v2_circuit_id(
                    &record.circuit_id,
                );
                let is_v3 = crate::zk::confidential_v2::is_confidential_unshield_v3_circuit_id(
                    &record.circuit_id,
                );
                if !is_v2 && !is_v3 {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "vk_unshield must name a confidential-unshield-v2 or confidential-unshield-v3 circuit"
                            .into(),
                    ));
                }
                let vk_box = record.key.as_ref().ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "vk_unshield verifying key bytes are missing".into(),
                    )
                })?;
                let result = if is_v2 {
                    crate::zk::confidential_v2::ensure_confidential_unshield_v2_canonical_vk_box(
                        vk_box,
                    )
                } else {
                    crate::zk::confidential_v2::ensure_confidential_unshield_v3_canonical_vk_box(
                        vk_box,
                    )
                };
                result.map_err(|err| {
                    InstructionExecutionError::InvariantViolation(
                        format!("invalid vk_unshield verifying key: {err}").into(),
                    )
                })?;
            }
            if let Some(binding) = vk_shield_binding.as_ref() {
                let record = state_transaction
                    .world
                    .verifying_keys
                    .get(&binding.id)
                    .expect("binding was resolved from the verifying-key registry");
                if !crate::zk::confidential_v2::is_kagemusha_topup_shield_v2_circuit_id(
                    &record.circuit_id,
                ) {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "vk_shield must name the canonical Kagemusha top-up shield circuit".into(),
                    ));
                }
                let vk_box = record.key.as_ref().ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "vk_shield verifying key bytes are missing".into(),
                    )
                })?;
                crate::zk::confidential_v2::ensure_kagemusha_topup_shield_v2_canonical_vk_box(
                    vk_box,
                )
                .map_err(|err| {
                    InstructionExecutionError::InvariantViolation(
                        format!("invalid vk_shield verifying key: {err}").into(),
                    )
                })?;
            }
            let mut derived_tree_profile = None;
            for (role, binding) in [
                ("vk_unshield", vk_unshield_binding.as_ref()),
                ("vk_shield", vk_shield_binding.as_ref()),
            ] {
                let Some(binding) = binding else {
                    continue;
                };
                let record = state_transaction
                    .world
                    .verifying_keys
                    .get(&binding.id)
                    .expect("binding was resolved from the verifying-key registry");
                let profile = crate::state::ConfidentialTreeProfile::for_circuit_id(
                    &record.circuit_id,
                )
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        format!(
                            "{role} circuit `{}` does not authenticate a supported confidential tree profile",
                            record.circuit_id,
                        )
                        .into(),
                    )
                })?;
                if derived_tree_profile.is_some_and(|current| current != profile) {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "configured confidential verifier roles authenticate different tree profiles"
                            .into(),
                    ));
                }
                derived_tree_profile = Some(profile);
            }
            let derived_tree_profile = derived_tree_profile.unwrap_or_default();
            let already_registered = existing_state.is_some();
            let mut st = existing_state.unwrap_or_default();
            st.validate_tree_metadata().map_err(|err| {
                InstructionExecutionError::InvariantViolation(
                    format!("invalid persisted confidential tree state: {err}").into(),
                )
            })?;
            if already_registered && st.tree_profile != derived_tree_profile {
                return Err(InstructionExecutionError::InvariantViolation(
                    "confidential tree profile is immutable after asset registration".into(),
                ));
            }
            st.tree_profile = derived_tree_profile;
            let mut vk_fingerprints: Vec<String> =
                [self.vk_unshield().clone(), self.vk_shield().clone()]
                    .into_iter()
                    .flatten()
                    .map(|vk| format!("{}::{}", vk.backend, vk.name))
                    .collect();
            vk_fingerprints.sort();
            let vk_set_hash = if vk_fingerprints.is_empty() {
                None
            } else {
                let joined = vk_fingerprints.join("|");
                Some(iroha_crypto::Hash::new(joined.as_bytes()))
            };
            let policy_struct = AssetConfidentialPolicy {
                mode: policy_mode,
                vk_set_hash,
                poseidon_params_id: state_transaction.zk.poseidon_params_id,
                pedersen_params_id: state_transaction.zk.pedersen_params_id,
                pending_transition: current_policy.pending_transition,
            };
            {
                let asset_definition = state_transaction
                    .world
                    .asset_definition_mut(&asset_def_id)
                    .map_err(Error::from)?;
                asset_definition.set_confidential_policy(policy_struct);
            }
            let metadata_context = PolicyMetadataContext {
                vk_unshield: self.vk_unshield().clone(),
                vk_unshield_commitment: vk_unshield_binding
                    .as_ref()
                    .map(|binding| binding.commitment),
                vk_shield: self.vk_shield().clone(),
                vk_shield_commitment: vk_shield_binding.as_ref().map(|binding| binding.commitment),
            };
            persist_policy_metadata(
                state_transaction,
                &asset_def_id,
                &policy_struct,
                &metadata_context,
            )?;
            // Persist/Update internal ZK policy state
            st.vk_unshield = vk_unshield_binding;
            st.vk_shield = vk_shield_binding;
            state_transaction
                .world
                .zk_assets
                .remove(asset_def_id.clone());
            state_transaction
                .world
                .zk_assets
                .insert(asset_def_id.clone(), st);
            Ok(())
        }
    }
    impl Execute for zk::ScheduleConfidentialPolicyTransition {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let asset_def_id = self.asset().clone();
            ensure_can_modify_confidential_policy(authority, state_transaction, &asset_def_id)?;
            let effective_height = *self.effective_height();
            let scheduled_at_height = state_transaction
                .world
                .confidential_policy_transition_count(effective_height);
            let maximum = state_transaction.zk.policy_transition_max_per_height;
            if scheduled_at_height >= maximum.get() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "confidential policy transition limit reached at effective height {effective_height}: scheduled={scheduled_at_height} maximum={maximum}"
                    )),
                ));
            }
            let mut policy = apply_policy_if_due(state_transaction, &asset_def_id)?;
            if policy.pending_transition().is_some() {
                return Err(InstructionExecutionError::InvariantViolation(
                    "confidential policy transition already scheduled".into(),
                ));
            }
            let st = state_transaction
                .world
                .zk_assets
                .get(&asset_def_id)
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "asset has no confidential state".into(),
                    )
                })?;
            let context = metadata_context_from_state(Some(st));
            let validation = PolicyTransitionValidation {
                current_mode: policy.mode(),
                new_mode: *self.new_mode(),
                block_height: state_transaction.block_height(),
                effective_height,
                delay_blocks: state_transaction.zk.policy_transition_delay_blocks,
                window_blocks: state_transaction.zk.policy_transition_window_blocks,
                requested_window: *self.conversion_window(),
            };
            validate_policy_transition(&validation)?;
            let transition = ConfidentialPolicyTransition {
                new_mode: *self.new_mode(),
                effective_height,
                previous_mode: policy.mode(),
                transition_id: *self.transition_id(),
                conversion_window: *self.conversion_window(),
            };
            policy.pending_transition = Some(transition);
            {
                let asset_definition = state_transaction
                    .world
                    .asset_definition_mut(&asset_def_id)
                    .map_err(Error::from)?;
                asset_definition.set_confidential_policy(policy);
            }
            state_transaction
                .world
                .track_confidential_policy_transition(&asset_def_id, transition.effective_height());
            persist_policy_metadata(state_transaction, &asset_def_id, &policy, &context)?;
            Ok(())
        }
    }
    impl Execute for zk::CancelConfidentialPolicyTransition {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let asset_def_id = self.asset().clone();
            ensure_can_modify_confidential_policy(authority, state_transaction, &asset_def_id)?;
            let mut policy = apply_policy_if_due(state_transaction, &asset_def_id)?;
            let context =
                metadata_context_from_state(state_transaction.world.zk_assets.get(&asset_def_id));
            let pending = policy.pending_transition().ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "no confidential policy transition scheduled".into(),
                )
            })?;
            if pending.transition_id() != self.transition_id() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "transition id does not match pending transition".into(),
                    ),
                ));
            }
            state_transaction
                .world
                .untrack_confidential_policy_transition(&asset_def_id, pending.effective_height());
            policy.pending_transition = None;
            {
                let asset_definition = state_transaction
                    .world
                    .asset_definition_mut(&asset_def_id)
                    .map_err(Error::from)?;
                asset_definition.set_confidential_policy(policy);
            }
            persist_policy_metadata(state_transaction, &asset_def_id, &policy, &context)?;
            Ok(())
        }
    }
    // --- ZK Voting ---
    fn election_vk_commitment(
        vk_id: &iroha_data_model::proof::VerifyingKeyId,
        label: &str,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<[u8; 32], Error> {
        let record = state_transaction
            .world
            .verifying_keys
            .get(vk_id)
            .cloned()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    format!("{label} verifying key not found").into(),
                )
            })?;
        if !record.is_active_at(state_transaction.block_height()) {
            return Err(InstructionExecutionError::InvariantViolation(
                format!("{label} verifying key is not Active").into(),
            ));
        }
        let vk_box = record.key.clone().ok_or_else(|| {
            InstructionExecutionError::InvariantViolation(
                format!("{label} verifying key bytes missing").into(),
            )
        })?;
        let commitment = hash_vk(&vk_box);
        if record.commitment != commitment {
            return Err(InstructionExecutionError::InvariantViolation(
                format!("{label} verifying key commitment mismatch").into(),
            ));
        }
        Ok(commitment)
    }
    fn resolve_ballot_vk(
        st: &crate::state::ElectionState,
        attachment: &iroha_data_model::proof::ProofAttachment,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<
        (
            iroha_data_model::proof::VerifyingKeyId,
            iroha_data_model::proof::VerifyingKeyBox,
            VerifyingKeyRecord,
        ),
        Error,
    > {
        let vk_id = st
            .vk_ballot
            .clone()
            .or_else(|| {
                state_transaction.gov.vk_ballot.as_ref().map(|v| {
                    iroha_data_model::proof::VerifyingKeyId::new(v.backend.clone(), v.name.clone())
                })
            })
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation("verifying key not configured".into())
            })?;
        if attachment.vk_ref != vk_id {
            return Err(InstructionExecutionError::InvariantViolation(
                "ballot verifying key ref mismatch".into(),
            ));
        }
        let record = state_transaction
            .world
            .verifying_keys
            .get(&vk_id)
            .cloned()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation("verifying key not found".into())
            })?;
        if !record.is_active_at(state_transaction.block_height()) {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key is not Active".into(),
            ));
        }
        if let Some(expected) = st.vk_ballot_commitment {
            if record.commitment != expected {
                return Err(InstructionExecutionError::InvariantViolation(
                    "ballot verifying key commitment mismatch".into(),
                ));
            }
        }
        if let Some(expected) = attachment.vk_commitment {
            if record.commitment != expected {
                return Err(InstructionExecutionError::InvariantViolation(
                    "ballot verifying key commitment mismatch".into(),
                ));
            }
        }
        let vk_box = if let Some(vk) = record.key.clone() {
            let commit = hash_vk(&vk);
            if record.commitment != commit {
                return Err(InstructionExecutionError::InvariantViolation(
                    "ballot verifying key commitment mismatch".into(),
                ));
            }
            vk
        } else {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key bytes missing".into(),
            ));
        };
        let backend = vk_id.backend.as_str();
        if backend != attachment.backend.as_str() || vk_box.backend.as_str() != backend {
            return Err(InstructionExecutionError::InvariantViolation(
                "ballot verifying key backend mismatch".into(),
            ));
        }
        ensure_voting_circuit_role(
            "ballot",
            backend,
            &record.circuit_id,
            VOTING_BALLOT_CIRCUIT_ID,
        )?;
        Ok((vk_id, vk_box, record))
    }
    fn resolve_tally_vk(
        st: &crate::state::ElectionState,
        attachment: &iroha_data_model::proof::ProofAttachment,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<
        (
            iroha_data_model::proof::VerifyingKeyId,
            iroha_data_model::proof::VerifyingKeyBox,
            VerifyingKeyRecord,
        ),
        Error,
    > {
        let vk_id = st
            .vk_tally
            .clone()
            .or_else(|| {
                state_transaction.gov.vk_tally.as_ref().map(|v| {
                    iroha_data_model::proof::VerifyingKeyId::new(v.backend.clone(), v.name.clone())
                })
            })
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation("verifying key not configured".into())
            })?;
        if attachment.vk_ref != vk_id {
            return Err(InstructionExecutionError::InvariantViolation(
                "tally verifying key ref mismatch".into(),
            ));
        }
        let record = state_transaction
            .world
            .verifying_keys
            .get(&vk_id)
            .cloned()
            .ok_or_else(|| {
                InstructionExecutionError::InvariantViolation(
                    "verifying key for tally not found".into(),
                )
            })?;
        if !record.is_active_at(state_transaction.block_height()) {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key is not Active".into(),
            ));
        }
        if let Some(expected) = st.vk_tally_commitment {
            if record.commitment != expected {
                return Err(InstructionExecutionError::InvariantViolation(
                    "tally verifying key commitment mismatch".into(),
                ));
            }
        }
        if let Some(expected) = attachment.vk_commitment {
            if record.commitment != expected {
                return Err(InstructionExecutionError::InvariantViolation(
                    "tally verifying key commitment mismatch".into(),
                ));
            }
        }
        let vk_box = if let Some(vk) = record.key.clone() {
            let commit = hash_vk(&vk);
            if record.commitment != commit {
                return Err(InstructionExecutionError::InvariantViolation(
                    "tally verifying key commitment mismatch".into(),
                ));
            }
            vk
        } else {
            return Err(InstructionExecutionError::InvariantViolation(
                "verifying key bytes missing".into(),
            ));
        };
        let backend = vk_id.backend.as_str();
        if backend != attachment.backend.as_str() || vk_box.backend.as_str() != backend {
            return Err(InstructionExecutionError::InvariantViolation(
                "tally vk backend mismatch".into(),
            ));
        }
        ensure_voting_circuit_role(
            "tally",
            backend,
            &record.circuit_id,
            VOTING_TALLY_CIRCUIT_ID,
        )?;
        Ok((vk_id, vk_box, record))
    }
    impl Execute for zk::CreateElection {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let required: Permission = CanManageParliament.into();
            if !has_exact_permission(&state_transaction.world, authority, &required) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanManageParliament".into(),
                ));
            }
            ensure_valid_governance_selector_v1("election_id", self.election_id())?;
            if typed_proposal_for_legacy_referendum(self.election_id(), state_transaction)?
                .is_some()
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "typed governance proposals cannot create legacy ZK elections".into(),
                ));
            }
            let options = *self.options();
            let tally_slots = zk::validate_election_options_v1(options)
                .map_err(|error| invalid_smart_contract_parameter(error.to_string()))?;
            // Insert a new election if it doesn't exist.
            let id = self.election_id().clone();
            if state_transaction.world.elections.get(&id).is_some() {
                return Err(InstructionExecutionError::InvariantViolation(
                    "election id already exists".into(),
                ));
            }
            if self.end_ts() < self.start_ts() {
                return Err(InstructionExecutionError::InvariantViolation(
                    "end_ts must be >= start_ts".into(),
                ));
            }
            // If a matching referendum is present, require Zk mode; otherwise seed one in Zk mode using config windows.
            if let Some(existing) = state_transaction.world.governance_referenda.get(&id) {
                if existing.mode != crate::state::GovernanceReferendumMode::Zk {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "referendum mode mismatch for election (expected Zk)".into(),
                    ));
                }
            } else {
                let start = state_transaction
                    ._curr_block
                    .height()
                    .get()
                    .saturating_add(state_transaction.gov.min_enactment_delay);
                let span = state_transaction.gov.window_span.max(1);
                let end = start.saturating_add(span.saturating_sub(1));
                state_transaction.world.governance_referenda.insert(
                    id.clone(),
                    crate::state::GovernanceReferendumRecord {
                        h_start: start,
                        h_end: end,
                        status: crate::state::GovernanceReferendumStatus::Proposed,
                        mode: crate::state::GovernanceReferendumMode::Zk,
                    },
                );
            }
            // Require ballot/tally verifying keys to be attested and active.
            let ballot_vk_id = self.vk_ballot().clone();
            let ballot_rec = state_transaction
                .world
                .verifying_keys
                .get(&ballot_vk_id)
                .cloned()
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "ballot verifying key not found".into(),
                    )
                })?;
            ensure_voting_circuit_role(
                "ballot",
                ballot_vk_id.backend.as_str(),
                &ballot_rec.circuit_id,
                VOTING_BALLOT_CIRCUIT_ID,
            )?;
            let ballot_commitment =
                election_vk_commitment(&ballot_vk_id, "ballot", state_transaction)?;
            let tally_vk_id = self.vk_tally().clone();
            let tally_rec = state_transaction
                .world
                .verifying_keys
                .get(&tally_vk_id)
                .cloned()
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation(
                        "tally verifying key not found".into(),
                    )
                })?;
            if !tally_rec.is_active_at(state_transaction.block_height()) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "tally verifying key is not Active".into(),
                ));
            }
            ensure_voting_circuit_role(
                "tally",
                tally_vk_id.backend.as_str(),
                &tally_rec.circuit_id,
                VOTING_TALLY_CIRCUIT_ID,
            )?;
            let tally_commitment =
                election_vk_commitment(&tally_vk_id, "tally", state_transaction)?;
            let st = crate::state::ElectionState {
                options,
                eligible_root: *self.eligible_root(),
                start_ts: *self.start_ts(),
                end_ts: *self.end_ts(),
                finalized: false,
                tally: vec![0; tally_slots],
                ballot_nullifiers: std::collections::BTreeSet::default(),
                ciphertexts: Vec::new(),
                vk_ballot: Some(self.vk_ballot().clone()),
                vk_ballot_commitment: Some(ballot_commitment),
                vk_tally: Some(self.vk_tally().clone()),
                vk_tally_commitment: Some(tally_commitment),
                domain_tag: self.domain_tag().clone(),
            };
            state_transaction.world.elections.insert(id, st);
            Ok(())
        }
    }
    impl Execute for zk::SubmitBallot {
        #[allow(clippy::too_many_lines)]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_exact_governance_ballot_permission(
                authority,
                &self.election_id,
                state_transaction,
            )?;
            if typed_proposal_for_legacy_referendum(&self.election_id, state_transaction)?.is_some()
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "typed governance proposals cannot use legacy ZK ballots".into(),
                ));
            }
            ensure_citizen_for_ballot(authority, &self.election_id, state_transaction)?;
            let id = self.election_id().clone();
            let mut st = state_transaction
                .world
                .elections
                .get(&id)
                .cloned()
                .ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation("unknown election id".into())
                })?;
            if st.finalized {
                return Err(InstructionExecutionError::InvariantViolation(
                    "election already finalized".into(),
                ));
            }
            let ballot_corpus_cap = state_transaction.zk.ballot_history_cap.clamp(1, 1_000);
            if st.ciphertexts.len() >= ballot_corpus_cap {
                return Err(InstructionExecutionError::InvariantViolation(
                    "governance ballot corpus is full".into(),
                ));
            }
            let now_ms = u64::try_from(state_transaction._curr_block.creation_time().as_millis())
                .unwrap_or(u64::MAX);
            if now_ms < st.start_ts || now_ms > st.end_ts {
                return Err(InstructionExecutionError::InvariantViolation(
                    "election not active".into(),
                ));
            }
            if self.ballot_proof.backend != self.ballot_proof.proof.backend {
                return Err(InstructionExecutionError::InvariantViolation(
                    "proof backend mismatch".into(),
                ));
            }
            let (vk_id, vk_box, vk_rec) =
                resolve_ballot_vk(&st, &self.ballot_proof, state_transaction)?;
            let backend = vk_id.backend.as_str();
            if crate::zk::is_stark_fri_v1_backend(backend) && !state_transaction.zk.stark.enabled {
                return Err(InstructionExecutionError::InvariantViolation(
                    "stark verification is disabled in node configuration".into(),
                ));
            }
            let proof_len = self.ballot_proof.proof.bytes.len();
            enforce_vk_max_proof_bytes("ballot", &vk_rec, proof_len)?;
            state_transaction.register_confidential_proof(proof_len)?;
            let report = crate::zk::verify_backend_with_timing_checked(
                backend,
                &self.ballot_proof.proof,
                Some(&vk_box),
                &state_transaction.zk,
            );
            if !report.ok {
                return Err(InstructionExecutionError::InvariantViolation(
                    "invalid ballot proof".into(),
                ));
            }
            let inputs = extract_vote_public_inputs(backend, &self.ballot_proof.proof.bytes)?;
            validate_open_verify_envelope_metadata("ballot", backend, &inputs.envelope, &vk_rec)?;
            let (commit_bytes, root_bytes) = ballot_inputs_from_columns(&inputs.columns)?;
            if root_bytes != st.eligible_root {
                return Err(InstructionExecutionError::InvariantViolation(
                    "stale or unknown eligibility root".into(),
                ));
            }
            let domain_tag = if st.domain_tag.is_empty() {
                DEFAULT_NULLIFIER_DOMAIN_TAG.to_string()
            } else {
                st.domain_tag.clone()
            };
            let expected_nullifier = derive_ballot_nullifier(
                &domain_tag,
                &state_transaction.network_id,
                &id,
                &commit_bytes,
            );
            if *self.nullifier() != expected_nullifier {
                return Err(InstructionExecutionError::InvariantViolation(
                    "ballot nullifier does not match proof".into(),
                ));
            }
            if self.ciphertext().len() != commit_bytes.len()
                || self.ciphertext().as_slice() != commit_bytes.as_slice()
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "ciphertext does not match proof".into(),
                ));
            }
            if !st.ballot_nullifiers.insert(expected_nullifier) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "duplicate ballot nullifier".into(),
                ));
            }
            st.ciphertexts.push(self.ciphertext().clone());
            state_transaction.world.elections.remove(id.clone());
            state_transaction.world.elections.insert(id, st);
            Ok(())
        }
    }
    impl Execute for zk::FinalizeElection {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let required: Permission = CanEnactGovernance.into();
            if !has_exact_permission(&state_transaction.world, authority, &required) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanEnactGovernance".into(),
                ));
            }
            ensure_valid_governance_selector_v1("election_id", self.election_id())?;
            if typed_proposal_for_legacy_referendum(self.election_id(), state_transaction)?
                .is_some()
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "typed governance proposals cannot finalize legacy ZK elections".into(),
                ));
            }
            let id = self.election_id().clone();
            let now_ms = u64::try_from(state_transaction._curr_block.creation_time().as_millis())
                .unwrap_or(u64::MAX);
            let (mut st, expected_tally_len) = {
                let st = state_transaction.world.elections.get(&id).ok_or_else(|| {
                    InstructionExecutionError::InvariantViolation("unknown election id".into())
                })?;
                if st.finalized {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "election already finalized".into(),
                    ));
                }
                if now_ms < st.end_ts {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "election still active".into(),
                    ));
                }
                let expected_tally_len = zk::validate_election_tally_v1(st.options, st.tally.len())
                    .map_err(|error| {
                        InstructionExecutionError::InvariantViolation(
                            format!("invalid stored election shape: {error}").into(),
                        )
                    })?;
                ((*st).clone(), expected_tally_len)
            };
            if self.tally().len() != expected_tally_len {
                return Err(InstructionExecutionError::InvariantViolation(
                    "tally length does not match options".into(),
                ));
            }
            let att = self.tally_proof();
            if att.backend != att.proof.backend {
                return Err(InstructionExecutionError::InvariantViolation(
                    "proof backend mismatch".into(),
                ));
            }
            let (vk_id, vk_box, vk_rec) = resolve_tally_vk(&st, att, state_transaction)?;
            let backend = vk_id.backend.as_str();
            if crate::zk::is_stark_fri_v1_backend(backend) && !state_transaction.zk.stark.enabled {
                return Err(InstructionExecutionError::InvariantViolation(
                    "stark verification is disabled in node configuration".into(),
                ));
            }
            let proof_len = att.proof.bytes.len();
            enforce_vk_max_proof_bytes("tally", &vk_rec, proof_len)?;
            state_transaction.register_confidential_proof(proof_len)?;
            let report = crate::zk::verify_backend_with_timing_checked(
                backend,
                &att.proof,
                Some(&vk_box),
                &state_transaction.zk,
            );
            if !report.ok {
                return Err(InstructionExecutionError::InvariantViolation(
                    "invalid tally proof".into(),
                ));
            }
            let inputs = extract_vote_public_inputs(backend, &att.proof.bytes)?;
            validate_open_verify_envelope_metadata("tally", backend, &inputs.envelope, &vk_rec)?;
            let expected_tally = tally_from_columns(&inputs.columns, expected_tally_len)?;
            if expected_tally != *self.tally() {
                return Err(InstructionExecutionError::InvariantViolation(
                    "tally does not match proof".into(),
                ));
            }
            st.tally.clone_from(self.tally());
            st.finalized = true;
            state_transaction.world.elections.remove(id.clone());
            state_transaction.world.elections.insert(id, st);
            Ok(())
        }
    }
    impl Execute for smart_contract_code::RegisterSmartContractCode {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_contract_lifecycle_authority(authority, state_transaction)?;
            let manifest = self.manifest().clone();
            let Some(key @ Hash { .. }) = manifest.code_hash else {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract("manifest.code_hash missing".into()),
                ));
            };
            if manifest.abi_hash.is_none() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract("manifest.abi_hash missing".into()),
                ));
            }
            let provenance = ensure_manifest_signature(&manifest)?;
            let signer_allowed = match authority.controller() {
                AccountController::Single(signatory) => signatory == &provenance.signer,
                AccountController::Multisig(policy) => policy
                    .members()
                    .iter()
                    .any(|member| member.public_key() == &provenance.signer),
            };
            if !signer_allowed {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "manifest signer is not authorised for the submitting account".into(),
                    ),
                ));
            }
            let _code_bytes = verify_registered_contract_artifact_for_manifest(
                &state_transaction.world,
                &key,
                &manifest,
            )?;
            if let Some(existing) = state_transaction.world.contract_manifests.get(&key) {
                if existing == &manifest {
                    return Ok(());
                }
                return Err(InstructionExecutionError::InvariantViolation(
                    "different contract manifest already stored for this code_hash".into(),
                ));
            }
            // A code hash has one immutable manifest. In particular, a later submitter cannot
            // re-sign the same bytecode with a broader entrypoint/trigger surface and change the
            // behavior of an already reviewed active instance.
            state_transaction
                .world
                .contract_manifests
                .insert(key, manifest);
            Ok(())
        }
    }
    impl ValidSingularQuery
        for iroha_data_model::query::smart_contract::prelude::FindContractManifestByCodeHash
    {
        #[metrics(+"find_contract_manifest_by_code_hash")]
        fn execute(
            &self,
            state_ro: &impl StateReadOnly,
        ) -> Result<
            iroha_data_model::smart_contract::manifest::ContractManifest,
            iroha_data_model::query::error::QueryExecutionFail,
        > {
            state_ro
                .world()
                .contract_manifests()
                .get(&self.code_hash)
                .ok_or(iroha_data_model::query::error::QueryExecutionFail::NotFound)
                .and_then(crate::smartcontracts::isi::query::own_singular_query_value)
        }
    }
    /// Collect consensus key identifiers bound to a public key.
    fn consensus_key_ids_for_public_key(
        world: &WorldTransaction<'_, '_>,
        public_key_label: &str,
    ) -> Vec<ConsensusKeyId> {
        world
            .consensus_keys_by_pk
            .get(public_key_label)
            .cloned()
            .unwrap_or_default()
    }
    /// Register a peer (BLS-normal with `PoP`)
    impl Execute for iroha_data_model::isi::register::RegisterPeerWithPop {
        #[metrics(+"register_peer")]
        fn execute(
            self,
            _authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            fn peer_key_policy_reason(
                err: &InstructionExecutionError,
            ) -> Option<PeerKeyPolicyRejectReason> {
                let InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(msg),
                ) = err
                else {
                    return None;
                };
                if msg.contains("lead-time policy") {
                    Some(PeerKeyPolicyRejectReason::LeadTimeViolation)
                } else if msg.contains("activation height cannot be in the past") {
                    Some(PeerKeyPolicyRejectReason::ActivationInPast)
                } else if msg.contains("expiry must exceed activation height") {
                    Some(PeerKeyPolicyRejectReason::ExpiryBeforeActivation)
                } else if msg.contains("algorithm") && msg.contains("not allowed") {
                    Some(PeerKeyPolicyRejectReason::DisallowedAlgorithm)
                } else if msg.contains("HSM binding required") {
                    Some(PeerKeyPolicyRejectReason::MissingHsm)
                } else if msg.contains("HSM provider") {
                    Some(PeerKeyPolicyRejectReason::DisallowedProvider)
                } else if msg.contains("identifier collision") {
                    Some(PeerKeyPolicyRejectReason::IdentifierCollision)
                } else {
                    None
                }
            }
            // Validators must support BLS batching: require non-zero cap in pipeline config.
            if state_transaction.pipeline.signature_batch_max_bls == 0 {
                iroha_logger::error!(
                    peer = %self.peer,
                    cap = state_transaction.pipeline.signature_batch_max_bls,
                    "RegisterPeerWithPop rejected: signature_batch_max_bls is zero"
                );
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "signature_batch_max_bls must be > 0 to register a validator peer".into(),
                    ),
                ));
            }
            let peer_id = self.peer.clone();
            // Enforce BLS-normal only for consensus peers.
            if !crate::sumeragi::is_bls_normal_public_key(peer_id.public_key()) {
                crate::sumeragi::status::record_peer_key_policy_reject(
                    PeerKeyPolicyRejectReason::DisallowedAlgorithm,
                );
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "peer public_key must use BLS-Normal (BLS-Small unsupported for peers)"
                            .into(),
                    ),
                ));
            }
            // Verify PoP
            if let Err(err) = iroha_crypto::bls_normal_pop_verify(peer_id.public_key(), &self.pop) {
                iroha_logger::error!(
                    %peer_id,
                    ?err,
                    "RegisterPeerWithPop rejected: invalid BLS PoP"
                );
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "invalid BLS proof-of-possession: {err}"
                    )),
                ));
            }
            let (activation_lead_blocks, sumeragi_params) = {
                let params = state_transaction.world.parameters.get();
                (
                    params.sumeragi.key_activation_lead_blocks,
                    params.sumeragi.clone(),
                )
            };
            let world = &mut state_transaction.world;
            if world.peers.iter().any(|id| id == &peer_id) {
                if state_transaction._curr_block.is_genesis() {
                    iroha_logger::debug!(
                        %peer_id,
                        "Duplicate RegisterPeerWithPop during genesis; treating as no-op"
                    );
                    return Ok(());
                }
                return Err(RepetitionError {
                    instruction: InstructionType::Register,
                    id: IdBox::PeerId(peer_id),
                }
                .into());
            }
            let block_height = state_transaction._curr_block.height().get();
            let activation_expected = if state_transaction._curr_block.is_genesis() {
                block_height
            } else {
                block_height.saturating_add(activation_lead_blocks)
            };
            let activation_height = self.activation_at.unwrap_or(activation_expected);
            if activation_height < block_height {
                crate::sumeragi::status::record_peer_key_policy_reject(
                    PeerKeyPolicyRejectReason::ActivationInPast,
                );
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "consensus key activation height cannot be in the past".into(),
                    ),
                ));
            }
            if activation_height != activation_expected
                && !(state_transaction._curr_block.is_genesis()
                    && activation_height == block_height)
            {
                crate::sumeragi::status::record_peer_key_policy_reject(
                    PeerKeyPolicyRejectReason::LeadTimeViolation,
                );
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "activation height {activation_height} violates lead-time policy; expected {activation_expected}"
                    )),
                ));
            }
            let status = if activation_height > block_height {
                ConsensusKeyStatus::Pending
            } else {
                ConsensusKeyStatus::Active
            };
            let hsm_binding = match (self.hsm.clone(), sumeragi_params.key_require_hsm) {
                (Some(binding), _) => Some(binding),
                (None, true) => {
                    crate::sumeragi::status::record_peer_key_policy_reject(
                        PeerKeyPolicyRejectReason::MissingHsm,
                    );
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "HSM binding required for consensus key".into(),
                        ),
                    ));
                }
                (None, false) => None,
            };
            let key_label = peer_id.public_key().to_string();
            let candidate_id = derive_validator_key_id(peer_id.public_key());
            if let Some(conflict) = consensus_key_ids_for_public_key(world, &key_label)
                .into_iter()
                .find(|id| id != &candidate_id)
            {
                crate::sumeragi::status::record_peer_key_policy_reject(
                    PeerKeyPolicyRejectReason::IdentifierCollision,
                );
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "consensus key identifier collision for peer public key; existing id: {conflict}"
                    )),
                ));
            }
            if let Some(existing) = world.consensus_keys.get(&candidate_id) {
                if existing.public_key != *peer_id.public_key() {
                    crate::sumeragi::status::record_peer_key_policy_reject(
                        PeerKeyPolicyRejectReason::IdentifierCollision,
                    );
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "consensus key identifier collision for peer public key".into(),
                        ),
                    ));
                }
            }
            let lifecycle_record = ConsensusKeyRecord {
                id: candidate_id,
                public_key: peer_id.public_key().clone(),
                pop: Some(self.pop.clone()),
                activation_height,
                expiry_height: self.expiry_at,
                hsm: hsm_binding,
                replaces: None,
                status,
            };
            if let Err(err) = validate_consensus_key_record(
                &lifecycle_record,
                &sumeragi_params,
                None,
                block_height,
                state_transaction._curr_block.is_genesis(),
            ) {
                if let Some(reason) = peer_key_policy_reason(&err) {
                    crate::sumeragi::status::record_peer_key_policy_reject(reason);
                }
                return Err(err);
            }
            if let PushResult::Duplicate(duplicate) = world.peers.push(peer_id.clone()) {
                if state_transaction._curr_block.is_genesis() {
                    iroha_logger::debug!(
                        %duplicate,
                        "Duplicate RegisterPeerWithPop during genesis; treating as no-op"
                    );
                    return Ok(());
                }
                return Err(RepetitionError {
                    instruction: InstructionType::Register,
                    id: IdBox::PeerId(duplicate),
                }
                .into());
            }
            upsert_consensus_key(world, &lifecycle_record.id, lifecycle_record.clone());
            world.emit_events(Some(PeerEvent::Added(peer_id)));
            Ok(())
        }
    }
    impl Execute for Unregister<Peer> {
        #[metrics(+"unregister_peer")]
        fn execute(
            self,
            _authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let peer_id = self.object().clone();
            let world = &mut state_transaction.world;
            let Some(index) = world.peers.iter().position(|id| id == &peer_id) else {
                return Err(FindError::Peer(peer_id).into());
            };
            world.peers.remove(index);
            // Mark any validators tied to this peer as exited to avoid dangling roster entries.
            let exited_keys: Vec<_> = world
                .public_lane_validators
                .iter()
                .filter(|(key, record)| {
                    public_lane_validator_record_matches_key(key, record)
                        && record
                            .validator
                            .try_signatory()
                            .is_some_and(|pk| pk == peer_id.public_key())
                })
                .map(|(key, _)| key.clone())
                .collect();
            for key in exited_keys {
                if let Some(record) = world.public_lane_validators.get_mut(&key) {
                    record.status = iroha_data_model::nexus::PublicLaneValidatorStatus::Exited;
                    // Prune stake shares so roster/state snapshots do not retain exited validators.
                    let share_keys: Vec<_> = world
                        .public_lane_stake_shares
                        .iter()
                        .filter(|((lane, validator_id, _), _)| {
                            *lane == key.0 && validator_id == &record.validator
                        })
                        .map(|(share_key, _)| share_key.clone())
                        .collect();
                    for share_key in share_keys {
                        world.public_lane_stake_shares.remove(share_key);
                    }
                }
            }
            let key_label = peer_id.public_key().to_string();
            let block_height = state_transaction._curr_block.height().get();
            let candidate_id = derive_validator_key_id(peer_id.public_key());
            let existing_pop = world
                .consensus_keys
                .get(&candidate_id)
                .and_then(|record| record.pop.clone());
            let lifecycle_record = ConsensusKeyRecord {
                id: candidate_id,
                public_key: peer_id.public_key().clone(),
                pop: existing_pop,
                activation_height: block_height,
                expiry_height: Some(block_height),
                hsm: None,
                replaces: None,
                status: ConsensusKeyStatus::Disabled,
            };
            upsert_consensus_key(world, &lifecycle_record.id, lifecycle_record.clone());
            let mut ids = consensus_key_ids_for_public_key(world, &key_label);
            if !ids.contains(&lifecycle_record.id) {
                ids.push(lifecycle_record.id.clone());
            }
            ids.sort();
            ids.dedup();
            world.consensus_keys_by_pk.insert(key_label, ids.clone());
            for id in ids {
                if id == lifecycle_record.id {
                    continue;
                }
                if let Some(mut record) = world.consensus_keys.get(&id).cloned() {
                    if !matches!(record.status, ConsensusKeyStatus::Disabled) {
                        record.status = ConsensusKeyStatus::Disabled;
                        record.expiry_height.get_or_insert(block_height);
                        world.consensus_keys.insert(id.clone(), record);
                    }
                }
            }
            world.emit_events(Some(PeerEvent::Removed(peer_id)));
            Ok(())
        }
    }
    impl Execute for Register<Domain> {
        #[metrics("register_domain")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let Register { object: new_domain } = self;
            let raw_domain_id = new_domain.id.clone();
            let canonical_id = DomainId::try_new(raw_domain_id.name(), raw_domain_id.dataspace())
                .map_err(|err| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    err.reason().into(),
                ))
            })?;
            if canonical_id == *iroha_genesis::GENESIS_DOMAIN_ID {
                return Err(InstructionExecutionError::InvariantViolation(
                    "Not allowed to register genesis domain".to_owned().into(),
                ));
            }
            if state_transaction.world.domains.get(&canonical_id).is_some() {
                return Err(RepetitionError {
                    instruction: InstructionType::Register,
                    id: IdBox::DomainId(canonical_id.clone()),
                }
                .into());
            }
            let now_ms = state_transaction.block_unix_timestamp_ms();
            let bootstrap_domain_name_lease = state_transaction.block_hashes.is_empty();
            let active_domain_owner =
                crate::sns::active_domain_owner(state_transaction.world(), &canonical_id, now_ms)
                    .map_err(|err| {
                    InstructionExecutionError::InvariantViolation(
                    format!(
                        "failed to resolve active SNS domain-name lease for `{canonical_id}`: {err}"
                    )
                    .into(),
                )
                })?;
            let should_seed_domain_name_lease = match active_domain_owner {
                Some(owner) if owner == *authority => false,
                Some(owner) => {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "active SNS domain-name lease for `{canonical_id}` is owned by `{owner}`, not `{authority}`"
                        )
                        .into(),
                    ));
                }
                None if bootstrap_domain_name_lease => true,
                None => {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "active SNS domain-name lease is required before registering `{canonical_id}`"
                        )
                        .into(),
                    ));
                }
            };
            let mut domain = new_domain.build(authority);
            domain.id = canonical_id.clone();
            if let Some((key, _)) = domain.metadata.iter().find(|(key, _)| {
                crate::smartcontracts::isi::kaigi::is_reserved_kaigi_metadata_key(key)
            }) {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!("domain metadata key `{key}` is reserved for native Kaigi state")
                        .into(),
                ));
            }
            if let Some((key, value)) = domain
                .metadata
                .iter()
                .find(|(key, _)| key.as_ref() == "kaigi_relay_allowlist")
            {
                crate::smartcontracts::isi::kaigi::validate_kaigi_relay_allowlist_metadata(
                    key, value,
                )?;
            }
            let requires_endorsement = state_transaction
                .world
                .domain_endorsement_policies
                .get(&canonical_id)
                .map_or(state_transaction.nexus.endorsement.quorum > 0, |policy| {
                    policy.required
                });
            if requires_endorsement {
                validate_domain_endorsement(&canonical_id, &domain.metadata, state_transaction)?;
            }
            let event_domain = domain.clone();
            let world = &mut state_transaction.world;
            if world.domains.get(&canonical_id).is_some() {
                return Err(RepetitionError {
                    instruction: InstructionType::Register,
                    id: IdBox::DomainId(canonical_id.clone()),
                }
                .into());
            }
            world.insert_domain_entry(canonical_id.clone(), domain);
            if should_seed_domain_name_lease {
                let lease_selector =
                    crate::sns::selector_for_domain(&canonical_id).map_err(|err| {
                        InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(err.to_string()),
                        )
                    })?;
                let address = iroha_data_model::account::AccountAddress::from_account_id(authority)
                    .map_err(|err| {
                        InstructionExecutionError::InvariantViolation(
                            format!(
                                "failed to derive genesis account address for SNS bootstrap: {err}"
                            )
                            .into(),
                        )
                    })?;
                let record = iroha_data_model::sns::NameRecordV1::new(
                    lease_selector.clone(),
                    authority.clone(),
                    vec![iroha_data_model::sns::NameControllerV1::account(&address)],
                    0,
                    0,
                    u64::MAX,
                    u64::MAX,
                    u64::MAX,
                    Metadata::default(),
                );
                world.smart_contract_state.insert(
                    crate::sns::record_storage_key(&lease_selector),
                    norito::codec::Encode::encode(&record),
                );
            }
            world.emit_events(Some(DomainEvent::Created(event_domain)));
            Ok(())
        }
    }
    fn endorsement_error(message: impl Into<String>) -> InstructionExecutionError {
        InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
            message.into(),
        ))
    }
    fn validate_domain_endorsement(
        canonical_id: &DomainId,
        metadata: &Metadata,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) -> Result<(), InstructionExecutionError> {
        const ENDORSEMENT_KEY: &str = "endorsement";
        let key = Name::from_str(ENDORSEMENT_KEY).map_err(|err| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                format!("invalid endorsement metadata key: {err}"),
            ))
        })?;
        let Some(raw) = metadata.get(&key) else {
            return Err(endorsement_error(
                "domain endorsement required (nexus.endorsement.quorum > 0)",
            ));
        };
        let endorsement: DomainEndorsement = raw.clone().try_into_any_norito().map_err(|err| {
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                format!("invalid domain endorsement payload: {err}"),
            ))
        })?;
        verify_domain_endorsement_payload(canonical_id, endorsement, state_transaction, None)
    }
    fn ensure_endorsement_identity(
        domain_id: &DomainId,
        endorsement: &DomainEndorsement,
    ) -> Result<(), InstructionExecutionError> {
        if endorsement.domain_id != *domain_id {
            return Err(endorsement_error("domain endorsement domain_id mismatch"));
        }
        let expected_hash = Hash::new(domain_id.to_string().as_bytes());
        if endorsement.statement_hash != expected_hash {
            return Err(endorsement_error(
                "domain endorsement statement_hash mismatch",
            ));
        }
        if endorsement.version != iroha_data_model::nexus::DOMAIN_ENDORSEMENT_VERSION_V1 {
            return Err(endorsement_error("domain endorsement version unsupported"));
        }
        Ok(())
    }
    fn resolve_endorsement_policy(
        domain_id: &DomainId,
        policy_override: Option<DomainEndorsementPolicy>,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<DomainEndorsementPolicy, InstructionExecutionError> {
        policy_override
            .or_else(|| {
                state_transaction
                    .world
                    .domain_endorsement_policies
                    .get(domain_id)
                    .cloned()
            })
            .or_else(|| {
                if state_transaction.nexus.endorsement.quorum > 0 {
                    Some(DomainEndorsementPolicy {
                        committee_id: "default".to_owned(),
                        max_endorsement_age: u64::MAX,
                        required: true,
                    })
                } else {
                    None
                }
            })
            .ok_or_else(|| endorsement_error("domain endorsement policy missing"))
    }
    fn validate_endorsement_scope(
        endorsement: &DomainEndorsement,
        policy: &DomainEndorsementPolicy,
        height: u64,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), InstructionExecutionError> {
        if endorsement.committee_id != policy.committee_id {
            return Err(endorsement_error(
                "domain endorsement committee_id mismatch",
            ));
        }
        if endorsement.expires_at_height <= height {
            return Err(endorsement_error("domain endorsement expired"));
        }
        if height < endorsement.issued_at_height {
            return Err(endorsement_error(
                "domain endorsement issued_at_height in future",
            ));
        }
        if height.saturating_sub(endorsement.issued_at_height) > policy.max_endorsement_age {
            return Err(endorsement_error("domain endorsement is stale"));
        }
        if let (Some(start), Some(end)) =
            (endorsement.scope.block_start, endorsement.scope.block_end)
        {
            if start > end {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "domain endorsement scope start exceeds end".into(),
                    ),
                ));
            }
        }
        if !endorsement.scope.contains_height(height) {
            return Err(endorsement_error(
                "domain endorsement outside declared block window",
            ));
        }
        if let Some(dataspace) = endorsement.scope.dataspace {
            let known = state_transaction
                .nexus
                .dataspace_catalog
                .entries()
                .iter()
                .any(|entry| entry.id == dataspace);
            if !known {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "domain endorsement dataspace unknown".into(),
                    ),
                ));
            }
        }
        Ok(())
    }
    fn resolve_endorsement_committee(
        policy: &DomainEndorsementPolicy,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<DomainCommittee, InstructionExecutionError> {
        state_transaction
            .world
            .domain_committees
            .get(&policy.committee_id)
            .cloned()
            .or_else(|| {
                let keys = &state_transaction.nexus.endorsement.committee_keys;
                if keys.is_empty() {
                    None
                } else {
                    Some(DomainCommittee {
                        committee_id: policy.committee_id.clone(),
                        members: keys.iter().cloned().collect(),
                        quorum: state_transaction.nexus.endorsement.quorum,
                        metadata: Metadata::default(),
                    })
                }
            })
            .ok_or_else(|| endorsement_error("domain endorsement committee not found"))
    }
    fn ensure_unique_endorsement(
        msg_hash: &iroha_crypto::HashOf<DomainEndorsement>,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), InstructionExecutionError> {
        if state_transaction
            .world
            .domain_endorsements
            .get(msg_hash)
            .is_some()
        {
            return Err(endorsement_error("domain endorsement already recorded"));
        }
        Ok(())
    }
    fn count_endorsement_approvals(
        endorsement: &DomainEndorsement,
        committee: &DomainCommittee,
        height: u64,
        overlap: u64,
        expiry_grace: u64,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<u16, InstructionExecutionError> {
        let committee_keys: BTreeSet<_> = committee.members.iter().cloned().collect();
        if committee_keys.is_empty() {
            return Err(endorsement_error(
                "domain endorsement committee has no members",
            ));
        }
        let msg_hash = endorsement.body_hash();
        let mut seen = BTreeSet::new();
        let mut approvals: u16 = 0;
        for sig in &endorsement.signatures {
            if !committee_keys.contains(&sig.signer) {
                continue;
            }
            if !seen.insert(sig.signer.clone()) {
                continue;
            }
            let key_ids = state_transaction
                .world
                .consensus_keys_by_pk
                .get(&sig.signer.to_string())
                .cloned()
                .unwrap_or_default();
            let mut signature_valid = false;
            for key_id in key_ids {
                let Some(rec) = state_transaction.world.consensus_keys.get(&key_id) else {
                    continue;
                };
                if rec.id.role != ConsensusKeyRole::Endorsement {
                    continue;
                }
                if !rec.is_live_at(height, overlap, expiry_grace) {
                    continue;
                }
                if verify_signature_for_signer(&sig.signature, &rec.public_key, msg_hash.as_ref())
                    .is_ok()
                {
                    signature_valid = true;
                    break;
                }
            }
            if signature_valid {
                approvals = approvals.saturating_add(1);
            }
        }
        Ok(approvals)
    }
    fn persist_endorsement_record(
        domain_id: &DomainId,
        endorsement: DomainEndorsement,
        height: u64,
        msg_hash: iroha_crypto::HashOf<DomainEndorsement>,
        state_transaction: &mut StateTransaction<'_, '_>,
    ) {
        state_transaction.world.domain_endorsements.insert(
            msg_hash,
            DomainEndorsementRecord {
                endorsement,
                accepted_at_height: height,
            },
        );
        let mut domain_index = state_transaction
            .world
            .domain_endorsements_by_domain
            .get(domain_id)
            .cloned()
            .unwrap_or_default();
        if !domain_index.contains(&msg_hash) {
            domain_index.push(msg_hash);
            state_transaction
                .world
                .domain_endorsements_by_domain
                .insert(domain_id.clone(), domain_index);
        }
    }
    fn verify_domain_endorsement_payload(
        domain_id: &DomainId,
        endorsement: DomainEndorsement,
        state_transaction: &mut StateTransaction<'_, '_>,
        policy_override: Option<DomainEndorsementPolicy>,
    ) -> Result<(), InstructionExecutionError> {
        let height = state_transaction.block_height();
        ensure_endorsement_identity(domain_id, &endorsement)?;
        let policy = resolve_endorsement_policy(domain_id, policy_override, state_transaction)?;
        if !policy.required {
            return Ok(());
        }
        validate_endorsement_scope(&endorsement, &policy, height, state_transaction)?;
        let committee = resolve_endorsement_committee(&policy, state_transaction)?;
        if !committee.is_valid() {
            return Err(InstructionExecutionError::InvariantViolation(
                "domain endorsement committee invalid (quorum/members)".into(),
            ));
        }
        let params = state_transaction.world.parameters.get();
        let overlap = params.sumeragi.key_overlap_grace_blocks;
        let expiry_grace = params.sumeragi.key_expiry_grace_blocks;
        let msg_hash = endorsement.body_hash();
        ensure_unique_endorsement(&msg_hash, state_transaction)?;
        let approvals = count_endorsement_approvals(
            &endorsement,
            &committee,
            height,
            overlap,
            expiry_grace,
            state_transaction,
        )?;
        if approvals < committee.quorum {
            return Err(InstructionExecutionError::InvariantViolation(
                "domain endorsement does not meet quorum".into(),
            ));
        }
        persist_endorsement_record(domain_id, endorsement, height, msg_hash, state_transaction);
        Ok(())
    }
    impl Execute for endorsement::RegisterDomainCommittee {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_can_manage_consensus_keys(authority, state_transaction)?;
            let committee = self.committee().clone();
            if !committee.is_valid() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "invalid domain committee shape (members/quorum)".into(),
                    ),
                ));
            }
            let mut seen = BTreeSet::new();
            let params = state_transaction.world.parameters.get();
            let overlap = params.sumeragi.key_overlap_grace_blocks;
            let expiry_grace = params.sumeragi.key_expiry_grace_blocks;
            for member in &committee.members {
                if !seen.insert(member.clone()) {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "duplicate domain committee member".into(),
                        ),
                    ));
                }
                let key_ids = state_transaction
                    .world
                    .consensus_keys_by_pk
                    .get(&member.to_string())
                    .cloned()
                    .unwrap_or_default();
                let mut has_live_endorsement_key = false;
                for key_id in key_ids {
                    let Some(rec) = state_transaction.world.consensus_keys.get(&key_id) else {
                        continue;
                    };
                    if rec.id.role != ConsensusKeyRole::Endorsement {
                        continue;
                    }
                    if rec.is_live_at(state_transaction.block_height(), overlap, expiry_grace) {
                        has_live_endorsement_key = true;
                        break;
                    }
                }
                if !has_live_endorsement_key {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(
                            "committee member lacks a live endorsement key".into(),
                        ),
                    ));
                }
            }
            if state_transaction
                .world
                .domain_committees
                .get(&committee.committee_id)
                .is_some()
            {
                return Err(RepetitionError {
                    instruction: InstructionType::Register,
                    id: IdBox::Permission(Permission::new(
                        "DomainCommittee".into(),
                        iroha_primitives::json::Json::from(committee.committee_id.as_str()),
                    )),
                }
                .into());
            }
            state_transaction
                .world
                .domain_committees
                .insert(committee.committee_id.clone(), committee);
            Ok(())
        }
    }
    impl Execute for endorsement::SetDomainEndorsementPolicy {
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            ensure_can_manage_consensus_keys(authority, state_transaction)?;
            let domain = self.domain().clone();
            if state_transaction.world.domains.get(&domain).is_none() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "domain not found for endorsement policy".into(),
                    ),
                ));
            }
            let mut policy = self.policy().clone();
            if policy.max_endorsement_age == 0 {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "max_endorsement_age must be positive".into(),
                    ),
                ));
            }
            let Some(committee) = state_transaction
                .world
                .domain_committees
                .get(&policy.committee_id)
                .cloned()
            else {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "committee not registered for endorsement policy".into(),
                    ),
                ));
            };
            if !committee.is_valid() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "committee invalid for endorsement policy".into(),
                    ),
                ));
            }
            // Normalize committee id casing to avoid duplicates.
            policy.committee_id.clone_from(&committee.committee_id);
            state_transaction
                .world
                .domain_endorsement_policies
                .insert(domain, policy);
            Ok(())
        }
    }
    impl Execute for endorsement::SubmitDomainEndorsement {
        fn execute(
            self,
            _authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let endorsement = self.endorsement().clone();
            let domain_id = endorsement.domain_id.clone();
            verify_domain_endorsement_payload(&domain_id, endorsement, state_transaction, None)?;
            Ok(())
        }
    }
    impl Execute for nexus::SetLaneRelayEmergencyValidators {
        #[metrics(+"set_lane_relay_emergency_validators")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let required: Permission = CanManageLaneRelayEmergency.into();
            if !has_exact_permission(&state_transaction.world, authority, &required) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanManageLaneRelayEmergency".into(),
                ));
            }
            if !state_transaction.nexus.lane_relay_emergency.enabled {
                return Err(InstructionExecutionError::InvariantViolation(
                    "lane relay emergency override requires nexus.lane_relay_emergency.enabled=true"
                        .into(),
                ));
            }
            let required_threshold = state_transaction
                .nexus
                .lane_relay_emergency
                .multisig_threshold;
            let required_members = state_transaction
                .nexus
                .lane_relay_emergency
                .multisig_members;
            let Some(policy) = authority.controller().multisig_policy() else {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!(
                        "lane relay emergency override requires multisig authority (threshold >= {required_threshold}, members >= {required_members})"
                    )
                    .into(),
                ));
            };
            if policy.threshold() < required_threshold.get()
                || policy.members().len() < usize::from(required_members.get())
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!(
                        "lane relay emergency override requires multisig authority (threshold >= {required_threshold}, members >= {required_members})"
                    )
                    .into(),
                ));
            }
            let lane_id = *self.lane_id();
            let current_height = state_transaction.block_height();
            if nexus_active_lane_dataspace_at_height(
                lane_id,
                &state_transaction.nexus,
                current_height,
            )
            .is_none()
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "unknown lane id {}",
                        lane_id.as_u32()
                    )),
                ));
            }
            let mut peers = self.peers().clone();
            peers.sort();
            peers.dedup();
            if peers.is_empty() {
                iroha_logger::info!(
                    %authority,
                    lane_id = lane_id.as_u32(),
                    "clearing lane relay emergency override"
                );
                state_transaction
                    .world
                    .lane_relay_emergency_validators
                    .remove(lane_id);
                return Ok(());
            }
            let expires_at_height = self.expires_at_height().ok_or_else(|| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    "lane relay emergency override requires expires_at_height for non-empty peer rosters"
                        .into(),
                ))
            })?;
            if expires_at_height < current_height {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "lane relay emergency override expiry {} is already in the past at current height {}",
                        expires_at_height, current_height
                    )),
                ));
            }
            let max_ttl_blocks = u64::from(
                state_transaction
                    .nexus
                    .lane_relay_emergency
                    .max_ttl_blocks
                    .get(),
            );
            if expires_at_height.saturating_sub(current_height) > max_ttl_blocks {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "lane relay emergency override expiry {} exceeds max_ttl_blocks {} at current height {}",
                        expires_at_height, max_ttl_blocks, current_height
                    )),
                ));
            }
            let present_peers: BTreeSet<_> =
                state_transaction.world.peers().iter().cloned().collect();
            let topology_peers: BTreeSet<_> = state_transaction
                .commit_topology()
                .get()
                .iter()
                .cloned()
                .collect();
            let enforce_topology_membership = !topology_peers.is_empty();
            for peer in &peers {
                if !present_peers.contains(peer) {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!(
                            "lane relay emergency peer {} is not registered",
                            peer.public_key()
                        )),
                    ));
                }
                if enforce_topology_membership && !topology_peers.contains(peer) {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!(
                            "lane relay emergency peer {} is not in the current commit topology",
                            peer.public_key()
                        )),
                    ));
                }
                if crate::state::live_consensus_key_pop_for_peer(
                    &state_transaction.world,
                    peer,
                    current_height,
                )
                .is_none()
                {
                    return Err(InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!(
                            "lane relay emergency peer {} does not have a live consensus key",
                            peer.public_key()
                        )),
                    ));
                }
            }
            iroha_logger::warn!(
                %authority,
                lane_id = lane_id.as_u32(),
                peer_count = peers.len(),
                expires_at_height,
                "setting lane relay emergency override"
            );
            state_transaction
                .world
                .lane_relay_emergency_validators
                .insert(
                    lane_id,
                    LaneRelayEmergencyValidatorSet {
                        peers,
                        expires_at_height,
                        metadata: self.metadata().clone(),
                    },
                );
            Ok(())
        }
    }
    impl Execute for nexus::RegisterVerifiedLaneRelay {
        #[metrics(+"register_verified_lane_relay")]
        fn execute(
            self,
            _authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            // Registration is permissionless transport. Durable authority comes exclusively from
            // the finalized lane-committee QC authenticated before either state key is written.
            if self.effect_proof_blob.is_some() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay business-effect promotion is disabled until an effect-specific statement is derived from a finalized, QC-anchored settlement ledger entry"
                            .into(),
                    ),
                )
                .into());
            }
            let envelope = self.envelope().clone();
            envelope.verify().map_err(|err| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    format!("lane relay envelope failed verification: {err}"),
                ))
            })?;
            envelope.validate_fastpq_proof_metadata().map_err(|err| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    format!("lane relay envelope FastPQ metadata is invalid: {err}"),
                ))
            })?;
            let Some(lane_dataspace_id) =
                nexus_catalog_geometry_lane_dataspace(envelope.lane_id, &state_transaction.nexus)
            else {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "unknown lane id {}",
                        envelope.lane_id.as_u32()
                    )),
                )
                .into());
            };
            if lane_dataspace_id != envelope.dataspace_id {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "lane {} belongs to dataspace {}, not {}",
                        envelope.lane_id.as_u32(),
                        lane_dataspace_id.as_u64(),
                        envelope.dataspace_id.as_u64()
                    )),
                )
                .into());
            }
            if !state_transaction
                .nexus
                .dataspace_catalog
                .entries()
                .iter()
                .any(|entry| entry.id == envelope.dataspace_id)
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "unknown dataspace id {}",
                        envelope.dataspace_id.as_u64()
                    )),
                )
                .into());
            }
            let proposal_height = envelope.block_header.height().get();
            let verified_at_height = state_transaction.block_height();
            if proposal_height > verified_at_height {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "lane relay proposal height is in the future".into(),
                    ),
                )
                .into());
            }
            let expected_incarnation = state_transaction
                .lane_incarnation_at_height(envelope.lane_id, proposal_height)
                .ok_or_else(|| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!(
                            "lane {} has no active incarnation at proposal height {proposal_height}",
                            envelope.lane_id.as_u32()
                        )),
                    )
                })?;
            if envelope.lane_incarnation != expected_incarnation {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "lane {} relay incarnation does not match the active proposal-height incarnation",
                        envelope.lane_id.as_u32()
                    )),
                )
                .into());
            }
            let manifest_root = envelope.manifest_root.ok_or_else(|| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    "lane relay envelope is missing manifest_root".into(),
                ))
            })?;
            if manifest_root.iter().all(|byte| *byte == 0) {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "lane relay manifest_root cannot be zeroed".into(),
                    ),
                )
                .into());
            }
            // Derive the exact post-execution effect before consulting either
            // proof carrier. The QC vote preimage commits this hash through its
            // strict mode tag; authentication is required before state mutation.
            let lane_finality_statement_hash =
                envelope.lane_finality_statement_hash().map_err(|err| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!(
                            "lane relay finality statement is invalid: {err}"
                        )),
                    )
                })?;
            let relay_ref = envelope.relay_ref();
            let key = verified_lane_relay_state_key(&relay_ref)?;
            let contract_map_key = verified_lane_relay_contract_map_state_key(&key)?;
            // The durable identity is one effect per
            // (lane, dataspace, incarnation, lane-local height). Never allow a
            // second effect to hide behind a proof-controlled settlement hash.
            for existing_key in [&key, &contract_map_key] {
                let Some(existing) = state_transaction
                    .world
                    .smart_contract_state
                    .get(existing_key)
                else {
                    continue;
                };
                let decoded = decode_verified_lane_relay_record_state(existing).map_err(|err| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!("stored {err}")),
                    )
                })?;
                let existing_statement_hash = decoded
                    .relay_envelope
                    .lane_finality_statement_hash()
                    .map_err(|err| {
                        InstructionExecutionError::InvariantViolation(
                            format!("stored lane relay finality statement is invalid: {err}")
                                .into(),
                        )
                    })?;
                if decoded.relay_ref != relay_ref
                    || existing_statement_hash != lane_finality_statement_hash
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "conflicting verified lane relay effect already exists".into(),
                    )
                    .into());
                }
            }
            let proof_blob = self.proof_blob();
            if proof_blob.payload.is_empty() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay proof payload is empty".into(),
                    ),
                )
                .into());
            }
            if crate::fastpq::axt_proof_payload_exceeds_decode_limit(&proof_blob.payload) {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "verified lane relay proof payload exceeds the {}-byte decode limit",
                        fastpq_prover::MAX_AXT_PROOF_BLOB_PAYLOAD_BYTES,
                    )),
                )
                .into());
            }
            let proof_payload_hash = CryptoHash::new(&proof_blob.payload);
            let Some(fastpq_material) = envelope.fastpq_proof.as_ref() else {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay proof material is missing".into(),
                    ),
                )
                .into());
            };
            if fastpq_material.proof_digest != proof_payload_hash {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay proof digest does not match proof_blob payload".into(),
                    ),
                )
                .into());
            }
            let material_verified_at_height = fastpq_material.verified_at_height;
            if material_verified_at_height > verified_at_height {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay proof metadata height is in the future".into(),
                    ),
                )
                .into());
            }
            if let Some(expiry_slot) = proof_blob.expiry_slot
                && verified_at_height > expiry_slot
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(format!(
                        "verified lane relay proof expired at slot {expiry_slot}"
                    )),
                )
                .into());
            }
            let proof_envelope = norito::decode_canonical::<AxtProofEnvelope>(&proof_blob.payload)
                .map_err(|err| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!(
                            "verified lane relay proof envelope decode failed: {err}"
                        )),
                    )
                })?;
            if proof_envelope.dsid != envelope.dataspace_id
                || proof_envelope.manifest_root != manifest_root
                || proof_envelope.da_commitment
                    != envelope
                        .da_commitment_hash
                        .map(|commitment| Hash::from(commitment).into())
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay proof does not match the declared manifest_root or DA commitment"
                            .into(),
                    ),
                )
                .into());
            }
            let Some(binding) = proof_envelope.fastpq_binding.clone() else {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay proof is missing fastpq_binding".into(),
                    ),
                )
                .into());
            };
            if binding.source_dsid != envelope.dataspace_id.as_u64() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay proof source_dsid mismatch".into(),
                    ),
                )
                .into());
            }
            if binding.verified_effect_type != LANE_RELAY_FASTPQ_EFFECT_TYPE {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay proof effect must be lane_relay_block".into(),
                    ),
                )
                .into());
            }
            if binding.effect_binding.is_some() {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay block proof must not carry a business-effect binding"
                            .into(),
                    ),
                )
                .into());
            }
            let expected_claim_digest =
                lane_relay_fastpq_claim_digest(&envelope).map_err(|err| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!(
                            "verified lane relay claim digest failed: {err}"
                        )),
                    )
                })?;
            if binding.claim_digest != hex::encode(expected_claim_digest.as_ref()) {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay proof claim_digest mismatch".into(),
                    ),
                )
                .into());
            }
            let verified_fastpq = fastpq_prover::verify_axt_proof_envelope_with_outer_metadata(
                &proof_envelope,
                proof_blob.expiry_slot,
            )
            .map_err(|err| {
                InstructionExecutionError::InvariantViolation(
                    format!("verified lane relay FASTPQ verification failed: {err}").into(),
                )
            })?;
            let execution_commitment = state_transaction
                .finalized_lane_relay_execution_commitment(&envelope)
                .map_err(|err| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!(
                            "lane relay finality authentication failed: {err}"
                        )),
                    )
                })?;
            let expected_old_root: [u8; 32] = execution_commitment.parent_state_root.into();
            let expected_new_root: [u8; 32] = execution_commitment.post_state_root.into();
            let expected_tx_set_hash: [u8; 32] = lane_finality_statement_hash.into();
            if verified_fastpq.old_root != expected_old_root
                || verified_fastpq.new_root != expected_new_root
                || verified_fastpq.tx_set_hash != expected_tx_set_hash
            {
                return Err(InstructionExecutionError::InvalidParameter(
                    InvalidParameterError::SmartContract(
                        "verified lane relay FastPQ roots do not match the finalized lane effect"
                            .into(),
                    ),
                )
                .into());
            }
            let record_statement_digest = verified_fastpq.statement_digest;
            let record_proof_digest = verified_fastpq.proof_digest;
            let record_binding = binding;
            let record = VerifiedLaneRelayRecord::new(
                envelope,
                proof_payload_hash,
                record_statement_digest,
                lane_finality_statement_hash,
                verified_fastpq.old_root,
                verified_fastpq.new_root,
                verified_fastpq.tx_set_hash,
                record_proof_digest,
                verified_at_height,
                manifest_root,
                record_binding,
            );
            let encoded = encode_verified_lane_relay_record_state(&record).map_err(|err| {
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
                    err,
                ))
            })?;
            let contract_map_encoded =
                encode_verified_lane_relay_record_contract_map_state(&record).map_err(|err| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(err),
                    )
                })?;
            for existing_key in [&key, &contract_map_key] {
                let Some(existing) = state_transaction
                    .world
                    .smart_contract_state
                    .get(existing_key)
                else {
                    continue;
                };
                let decoded = decode_verified_lane_relay_record_state(existing).map_err(|err| {
                    InstructionExecutionError::InvalidParameter(
                        InvalidParameterError::SmartContract(format!("stored {err}")),
                    )
                })?;
                if decoded != record {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "conflicting verified lane relay already exists".into(),
                    )
                    .into());
                }
            }
            let mut inserted = false;
            if state_transaction
                .world
                .smart_contract_state
                .get(&key)
                .is_none()
            {
                state_transaction
                    .world
                    .smart_contract_state
                    .insert(key, encoded.clone());
                inserted = true;
            }
            if state_transaction
                .world
                .smart_contract_state
                .get(&contract_map_key)
                .is_none()
            {
                state_transaction
                    .world
                    .smart_contract_state
                    .insert(contract_map_key, contract_map_encoded);
                inserted = true;
            }
            if inserted {
                state_transaction.stage_verified_lane_relay_record(record);
                return Ok(());
            }
            state_transaction.stage_verified_lane_relay_record(record);
            Ok(())
        }
    }
    impl Execute for nexus::RegisterVerifiedFeeSponsorVaultAllocation {
        #[metrics(+"register_verified_fee_sponsor_vault_allocation")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            if *self.program_revision() == 0 {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault allocation revision must be non-zero",
                ));
            }
            let program_id = self.program_id().clone();
            let revision_key =
                FeeSponsorProgramRevisionKey::new(program_id.clone(), *self.program_revision());
            let program = state_transaction
                .world
                .fee_sponsor_programs
                .get(&program_id)
                .cloned()
                .ok_or_else(|| {
                    invalid_fee_sponsor_program(
                        "verified fee sponsor vault allocation references an unknown program",
                    )
                })?;
            ensure_fee_sponsor_program_owner(authority, &program_id, state_transaction)?;
            if program.lifecycle != iroha_data_model::nexus::FeeSponsorProgramLifecycle::Active
                || program.active_revision != Some(*self.program_revision())
                || state_transaction
                    .world
                    .fee_sponsor_program_revisions
                    .get(&revision_key)
                    .is_none()
            {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault allocation requires the exact active program revision",
                ));
            }
            let definition = state_transaction
                .world
                .asset_definitions
                .get(self.asset_definition_id())
                .ok_or_else(|| {
                    invalid_fee_sponsor_program(
                        "verified fee sponsor vault allocation references an unknown fee asset",
                    )
                })?;
            ensure_global_fee_sponsor_asset(definition, "verified fee sponsor vault allocation")?;
            if self.verified_allocation().is_zero() {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault allocation must be positive",
                ));
            }
            let vault_key = iroha_data_model::nexus::FeeSponsorVaultKey {
                program_id: program_id.clone(),
                asset_definition_id: self.asset_definition_id().clone(),
            };
            let vault = state_transaction
                .world
                .fee_sponsor_vaults
                .get(&vault_key)
                .ok_or_else(|| {
                    invalid_fee_sponsor_program(
                        "verified fee sponsor vault allocation references an unfunded vault",
                    )
                })?;
            let verified_at_height = state_transaction.block_height();
            if *self.source_height() == 0
                || *self.source_height() > verified_at_height
                || self
                    .source_state_root()
                    .as_ref()
                    .iter()
                    .all(|byte| *byte == 0)
                || self.lease_id().as_ref().iter().all(|byte| *byte == 0)
            {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault allocation has an invalid source height, state root, or lease id",
                ));
            }
            let expected_source_state_root = fee_sponsor_vault_source_state_root(
                &program_id,
                *self.program_revision(),
                self.asset_definition_id(),
                &vault.balance,
                *self.source_dataspace_id(),
                *self.source_height(),
            );
            if *self.source_state_root() != expected_source_state_root {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault allocation source snapshot does not match the authoritative vault",
                ));
            }
            if *self.expires_at_height() < verified_at_height {
                return Err(invalid_fee_sponsor_program(format!(
                    "verified fee sponsor vault allocation expired at height {}",
                    self.expires_at_height()
                )));
            }
            if self.manifest_root().iter().all(|byte| *byte == 0) {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault allocation manifest root cannot be zeroed",
                ));
            }
            let frozen_policy = state_transaction
                .axt_execution_policy_snapshot()
                .ok_or_else(|| {
                    invalid_fee_sponsor_program(
                        "verified fee sponsor vault allocation requires a frozen AXT policy snapshot",
                    )
                })?
                .entries
                .into_iter()
                .find(|entry| entry.dsid == *self.source_dataspace_id())
                .ok_or_else(|| {
                    invalid_fee_sponsor_program(
                        "verified fee sponsor vault allocation source dataspace has no frozen AXT policy",
                    )
                })?;
            if frozen_policy.policy.manifest_root != *self.manifest_root() {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault allocation manifest root does not match the frozen AXT policy",
                ));
            }
            let proof_blob = self.proof_blob();
            if proof_blob.payload.is_empty() {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault allocation proof payload is empty",
                ));
            }
            if crate::fastpq::axt_proof_payload_exceeds_decode_limit(&proof_blob.payload) {
                return Err(invalid_fee_sponsor_program(format!(
                    "verified fee sponsor vault allocation proof payload exceeds the {}-byte decode limit",
                    fastpq_prover::MAX_AXT_PROOF_BLOB_PAYLOAD_BYTES,
                )));
            }
            if let Some(expiry_slot) = proof_blob.expiry_slot
                && verified_at_height > expiry_slot
            {
                return Err(invalid_fee_sponsor_program(format!(
                    "verified fee sponsor vault allocation proof expired at slot {expiry_slot}",
                )));
            }
            if proof_blob.expiry_slot != Some(*self.expires_at_height()) {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault proof expiry must equal the allocation lease expiry",
                ));
            }
            let proof_envelope = norito::decode_canonical::<AxtProofEnvelope>(&proof_blob.payload)
                .map_err(|err| {
                    invalid_fee_sponsor_program(format!(
                        "verified fee sponsor vault allocation proof decode failed: {err}",
                    ))
                })?;
            if proof_envelope.dsid != *self.source_dataspace_id()
                || proof_envelope.manifest_root != *self.manifest_root()
            {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault proof source dataspace or manifest root mismatch",
                ));
            }
            if proof_envelope.da_commitment.is_some() {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault proof must not carry a DA commitment",
                ));
            }
            if let Some(committed_amount) = proof_envelope.committed_amount {
                let expected = self
                    .verified_allocation()
                    .as_numeric()
                    .try_mantissa_u128()
                    .ok_or_else(|| {
                        invalid_fee_sponsor_program(
                            "verified fee sponsor vault allocation is outside the u128 proof domain",
                        )
                    })?;
                if self.verified_allocation().scale() != 0 || committed_amount != expected {
                    return Err(invalid_fee_sponsor_program(
                        "verified fee sponsor vault committed amount mismatch",
                    ));
                }
            }
            let claim = FeeSponsorVaultAllocationClaim {
                program_id: program_id.clone(),
                program_revision: *self.program_revision(),
                asset_definition_id: self.asset_definition_id().clone(),
                verified_allocation: self.verified_allocation().clone(),
                source_dataspace_id: *self.source_dataspace_id(),
                source_height: *self.source_height(),
                source_state_root: *self.source_state_root(),
                expires_at_height: *self.expires_at_height(),
                lease_id: *self.lease_id(),
            };
            let binding = proof_envelope.fastpq_binding.clone().ok_or_else(|| {
                invalid_fee_sponsor_program(
                    "verified fee sponsor vault proof is missing fastpq_binding",
                )
            })?;
            if binding.source_dsid != self.source_dataspace_id().as_u64()
                || binding.verified_effect_type != "fee_sponsor_vault_allocation"
            {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault proof has the wrong source or effect type",
                ));
            }
            let expected_policy_commitment =
                fee_sponsor_vault_policy_commitment(self.manifest_root());
            if binding.policy_commitment != hex::encode(expected_policy_commitment.as_ref()) {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault proof policy commitment mismatch",
                ));
            }
            let expected_claim_digest = fee_sponsor_vault_allocation_claim_digest(&claim);
            if binding.claim_digest != hex::encode(expected_claim_digest.as_ref()) {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault proof claim digest mismatch",
                ));
            }
            if binding
                .effect_binding
                .as_ref()
                .and_then(|effect| effect.source_asset_definition_id.as_deref())
                != Some(self.asset_definition_id().to_string().as_str())
            {
                return Err(invalid_fee_sponsor_program(
                    "verified fee sponsor vault proof asset binding mismatch",
                ));
            }
            let verified_fastpq = fastpq_prover::verify_axt_proof_envelope_with_outer_metadata(
                &proof_envelope,
                proof_blob.expiry_slot,
            )
            .map_err(|err| {
                InstructionExecutionError::InvariantViolation(
                    format!("verified fee sponsor vault FASTPQ verification failed: {err}",).into(),
                )
            })?;
            let record = VerifiedFeeSponsorVaultAllocation::new(
                program_id.clone(),
                *self.program_revision(),
                self.asset_definition_id().clone(),
                self.verified_allocation().clone(),
                *self.source_dataspace_id(),
                *self.source_height(),
                *self.source_state_root(),
                *self.expires_at_height(),
                *self.lease_id(),
                CryptoHash::new(&proof_blob.payload),
                verified_fastpq.statement_digest,
                verified_fastpq.proof_digest,
                verified_at_height,
                *self.manifest_root(),
                binding,
            );
            let key = verified_fee_sponsor_vault_allocation_state_key(
                &program_id,
                self.asset_definition_id(),
                self.lease_id(),
            )?;
            let encoded = encode_verified_fee_sponsor_vault_allocation_state(&record)
                .map_err(invalid_fee_sponsor_program)?;
            for (existing_key, payload) in state_transaction.world.smart_contract_state.iter() {
                if !existing_key
                    .to_string()
                    .starts_with(VERIFIED_FEE_SPONSOR_VAULT_ALLOCATION_STATE_KEY_PREFIX)
                {
                    continue;
                }
                let existing = decode_verified_fee_sponsor_vault_allocation_state(payload)
                    .map_err(invalid_fee_sponsor_program)?;
                if existing.lease_id == record.lease_id && existing != record {
                    return Err(InstructionExecutionError::InvariantViolation(
                        "fee sponsor vault spend lease id is already bound to another allocation"
                            .into(),
                    )
                    .into());
                }
                if fee_sponsor_vault_allocation_conflicts_on_live_route(
                    &existing,
                    &record,
                    verified_at_height,
                ) {
                    return Err(invalid_fee_sponsor_program(format!(
                        "fee sponsor vault route already has an unexpired spend lease through height {}",
                        existing.expires_at_height
                    )));
                }
            }
            if let Some(existing) = state_transaction.world.smart_contract_state.get(&key) {
                let existing = decode_verified_fee_sponsor_vault_allocation_state(existing)
                    .map_err(invalid_fee_sponsor_program)?;
                if existing == record {
                    return Ok(());
                }
                return Err(InstructionExecutionError::InvariantViolation(
                    "conflicting verified fee sponsor vault allocation already exists".into(),
                )
                .into());
            }
            if let Some(activation) = program.scheduled_activation
                && record.expires_at_height >= activation.activate_at_height
            {
                return Err(invalid_fee_sponsor_program(format!(
                    "fee sponsor vault spend lease must expire before scheduled revision activation height {}",
                    activation.activate_at_height
                )));
            }
            let locked = locked_fee_sponsor_vault_capacity(
                &state_transaction.world,
                &program_id,
                self.asset_definition_id(),
                verified_at_height,
            )
            .map_err(invalid_fee_sponsor_program)?;
            let required = locked
                .checked_add(self.verified_allocation())
                .map_err(|_| {
                    invalid_fee_sponsor_program(
                        "verified fee sponsor vault allocation lock arithmetic overflow",
                    )
                })?;
            if required > vault.balance {
                return Err(invalid_fee_sponsor_program(format!(
                    "verified fee sponsor vault allocations exceed source capacity: requires {required}, available {}",
                    vault.balance
                )));
            }
            state_transaction
                .world
                .smart_contract_state
                .insert(key, encoded);
            Ok(())
        }
    }
    fn invalid_fee_sponsor_program(message: impl Into<String>) -> Error {
        InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(
            message.into().into(),
        ))
    }
    fn ensure_global_fee_sponsor_asset(
        definition: &AssetDefinition,
        operation: &str,
    ) -> Result<(), Error> {
        if definition.balance_scope_policy() == AssetBalancePolicy::Global {
            return Ok(());
        }
        // TODO: Carry balance scope through sponsor vault keys, queue reservations, relay leases,
        // and settlement accounting before permitting DataspaceRestricted sponsorship.
        Err(invalid_fee_sponsor_program(format!(
            "{operation} requires global-balance fee assets; `{}` is DataspaceRestricted",
            definition.id()
        )))
    }
    fn ensure_fee_sponsor_program_owner(
        authority: &AccountId,
        program_id: &iroha_data_model::nexus::FeeSponsorProgramId,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        if crate::executor::is_initial_genesis_context(state_transaction) {
            return Ok(());
        }
        let delegated = state_transaction
            .world
            .account_permissions
            .get(authority)
            .is_some_and(|permissions| {
                permissions.iter().any(|permission| {
                    CanManageFeeSponsorProgram::try_from(permission).is_ok_and(|token| {
                        token.sponsor.subject_id() == program_id.sponsor.subject_id()
                    })
                })
            })
            || state_transaction
                .world
                .account_roles_iter(authority)
                .filter_map(|role_id| state_transaction.world.roles.get(role_id))
                .any(|role| {
                    role.permissions.iter().any(|permission| {
                        CanManageFeeSponsorProgram::try_from(permission).is_ok_and(|token| {
                            token.sponsor.subject_id() == program_id.sponsor.subject_id()
                        })
                    })
                });
        if authority != &program_id.sponsor && !delegated {
            return Err(InstructionExecutionError::InvariantViolation(
                format!("authority `{authority}` cannot manage fee sponsor program `{program_id}`")
                    .into(),
            ));
        }
        Ok(())
    }
    fn ensure_fee_sponsor_enrollment_authority(
        authority: &AccountId,
        program_id: &iroha_data_model::nexus::FeeSponsorProgramId,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        if ensure_fee_sponsor_program_owner(authority, program_id, state_transaction).is_ok() {
            return Ok(());
        }
        let allowed = state_transaction
            .world
            .account_permissions
            .get(authority)
            .is_some_and(|permissions| {
                permissions.iter().any(|permission| {
                    CanEnrollFeeSponsorProgram::try_from(permission)
                        .is_ok_and(|token| &token.program_id == program_id)
                })
            })
            || state_transaction
                .world
                .account_roles_iter(authority)
                .filter_map(|role_id| state_transaction.world.roles.get(role_id))
                .any(|role| {
                    role.permissions.iter().any(|permission| {
                        CanEnrollFeeSponsorProgram::try_from(permission)
                            .is_ok_and(|token| &token.program_id == program_id)
                    })
                });
        if allowed {
            Ok(())
        } else {
            Err(InstructionExecutionError::InvariantViolation(
                format!(
                    "authority `{authority}` cannot manage enrollments for fee sponsor program `{program_id}`"
                )
                .into(),
            ))
        }
    }
    fn ensure_fee_sponsor_withdrawal_authority(
        authority: &AccountId,
        program_id: &iroha_data_model::nexus::FeeSponsorProgramId,
    ) -> Result<(), Error> {
        if authority == &program_id.sponsor {
            return Ok(());
        }
        Err(InstructionExecutionError::InvariantViolation(
            format!(
                "only sponsor `{}` may withdraw from fee sponsor program `{program_id}`; authority was `{authority}`",
                program_id.sponsor
            )
            .into(),
        ))
    }
    fn validate_fee_sponsor_revision(
        revision: &iroha_data_model::nexus::FeeSponsorProgramRevision,
        state_transaction: &StateTransaction<'_, '_>,
    ) -> Result<(), Error> {
        use iroha_data_model::nexus::{FeeSponsorRuleEffect, FeeSponsorRuleSelector};
        revision
            .validate()
            .map_err(|error| invalid_fee_sponsor_program(error.to_string()))?;
        if revision.revision == 0 {
            return Err(invalid_fee_sponsor_program(
                "fee sponsor program revision must be non-zero",
            ));
        }
        if revision.rules.is_empty()
            || !revision
                .rules
                .iter()
                .any(|rule| rule.effect == FeeSponsorRuleEffect::Allow)
        {
            return Err(invalid_fee_sponsor_program(
                "fee sponsor program revision must contain an allow rule",
            ));
        }
        let mut rule_ids = BTreeSet::new();
        for rule in &revision.rules {
            if !rule_ids.insert(rule.id.clone()) {
                return Err(invalid_fee_sponsor_program(format!(
                    "duplicate fee sponsor rule id `{}`",
                    rule.id
                )));
            }
            if rule.selectors.is_empty() {
                return Err(invalid_fee_sponsor_program(format!(
                    "fee sponsor rule `{}` has no selectors",
                    rule.id
                )));
            }
            for selector in &rule.selectors {
                match selector {
                    FeeSponsorRuleSelector::NativeInstruction(selector) => {
                        if selector.wire_id.trim().is_empty()
                            || !iroha_data_model::isi::registry::is_instruction_wire_id_registered(
                                &selector.wire_id,
                            )
                        {
                            return Err(invalid_fee_sponsor_program(format!(
                                "fee sponsor rule `{}` references unknown instruction wire id `{}`",
                                rule.id, selector.wire_id
                            )));
                        }
                        if let Some(asset_definition_id) = &selector.asset_definition_id
                            && state_transaction
                                .world
                                .asset_definitions
                                .get(asset_definition_id)
                                .is_none()
                        {
                            return Err(invalid_fee_sponsor_program(format!(
                                "fee sponsor rule `{}` references unknown asset definition `{asset_definition_id}`",
                                rule.id
                            )));
                        }
                    }
                    FeeSponsorRuleSelector::ContractCall(selector) => {
                        if state_transaction
                            .world
                            .contract_instances
                            .get(&selector.contract_address)
                            != Some(&selector.code_hash)
                        {
                            return Err(invalid_fee_sponsor_program(format!(
                                "fee sponsor rule `{}` contract selector does not match a live address/code binding",
                                rule.id
                            )));
                        }
                        if selector
                            .entrypoints
                            .iter()
                            .any(|entrypoint| entrypoint.trim().is_empty())
                        {
                            return Err(invalid_fee_sponsor_program(format!(
                                "fee sponsor rule `{}` contains an empty contract entrypoint",
                                rule.id
                            )));
                        }
                    }
                    FeeSponsorRuleSelector::Multisig(_) => {}
                    FeeSponsorRuleSelector::Ivm(_) | FeeSponsorRuleSelector::IvmProved(_) => {}
                }
            }
        }
        if revision.asset_budgets.is_empty() {
            return Err(invalid_fee_sponsor_program(
                "fee sponsor program revision must contain an asset budget",
            ));
        }
        let mut previous_asset = None;
        for budget in &revision.asset_budgets {
            if previous_asset
                .as_ref()
                .is_some_and(|previous| previous >= &budget.asset_definition_id)
            {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor asset budgets must be uniquely sorted by asset definition",
                ));
            }
            previous_asset = Some(budget.asset_definition_id.clone());
            let definition = state_transaction
                .world
                .asset_definitions
                .get(&budget.asset_definition_id)
                .ok_or_else(|| {
                    invalid_fee_sponsor_program(format!(
                        "fee sponsor budget references unknown asset definition `{}`",
                        budget.asset_definition_id
                    ))
                })?;
            ensure_global_fee_sponsor_asset(definition, "fee sponsor program revision")?;
            if budget.per_transaction.is_zero()
                || budget.per_block.is_zero()
                || budget.per_program_epoch.is_zero()
                || budget.per_beneficiary_epoch.is_zero()
            {
                return Err(invalid_fee_sponsor_program(format!(
                    "fee sponsor budget for `{}` contains a zero spending limit",
                    budget.asset_definition_id
                )));
            }
            if budget.per_transaction > budget.per_block
                || budget.per_transaction > budget.per_program_epoch
                || budget.per_transaction > budget.per_beneficiary_epoch
                || budget.per_beneficiary_epoch > budget.per_program_epoch
            {
                return Err(invalid_fee_sponsor_program(format!(
                    "fee sponsor budget limits for `{}` are internally inconsistent",
                    budget.asset_definition_id
                )));
            }
        }
        Ok(())
    }
    fn fee_sponsor_asset_scope(
        definition: &AssetDefinition,
        dataspace: iroha_data_model::nexus::DataSpaceId,
    ) -> AssetBalanceScope {
        match definition.balance_scope_policy() {
            AssetBalancePolicy::Global => AssetBalanceScope::Global,
            AssetBalancePolicy::DataspaceRestricted => AssetBalanceScope::Dataspace(dataspace),
        }
    }
    impl Execute for nexus::CreateFeeSponsorProgram {
        #[metrics(+"create_fee_sponsor_program")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::nexus::FeeSponsorProgramLifecycle;
            let program = self.program().clone();
            ensure_fee_sponsor_program_owner(authority, &program.id, state_transaction)?;
            if state_transaction
                .world
                .accounts
                .get(&program.id.sponsor)
                .is_none()
            {
                return Err(invalid_fee_sponsor_program(format!(
                    "unknown fee sponsor account `{}`",
                    program.id.sponsor
                )));
            }
            if state_transaction
                .world
                .accounts
                .get(&program.payout_account)
                .is_none()
            {
                return Err(invalid_fee_sponsor_program(format!(
                    "unknown fee sponsor payout account `{}`",
                    program.payout_account
                )));
            }
            if program.lifecycle != FeeSponsorProgramLifecycle::Staged
                || program.active_revision.is_some()
                || program.staged_revision.is_some()
                || program.scheduled_activation.is_some()
            {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor programs must be created staged with no revisions",
                ));
            }
            if state_transaction
                .world
                .fee_sponsor_programs
                .get(&program.id)
                .is_some()
            {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor program already exists or is a closed tombstone",
                ));
            }
            state_transaction
                .world
                .fee_sponsor_programs
                .insert(program.id.clone(), program);
            Ok(())
        }
    }
    impl Execute for nexus::StageFeeSponsorProgramRevision {
        #[metrics(+"stage_fee_sponsor_program_revision")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::nexus::FeeSponsorProgramLifecycle;
            let revision = self.revision().clone();
            ensure_fee_sponsor_program_owner(authority, &revision.program_id, state_transaction)?;
            let mut program = state_transaction
                .world
                .fee_sponsor_programs
                .get(&revision.program_id)
                .cloned()
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor program not found"))?;
            if matches!(
                program.lifecycle,
                FeeSponsorProgramLifecycle::Closing | FeeSponsorProgramLifecycle::Closed
            ) {
                return Err(invalid_fee_sponsor_program(
                    "closing or closed fee sponsor program cannot stage revisions",
                ));
            }
            if program.staged_revision.is_some() || program.scheduled_activation.is_some() {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor program already has a staged revision",
                ));
            }
            if state_transaction
                .world
                .fee_sponsor_program_revisions
                .get(&FeeSponsorProgramRevisionKey::new(
                    revision.program_id.clone(),
                    revision.revision,
                ))
                .is_some()
            {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor program revision is immutable and already exists",
                ));
            }
            if program
                .active_revision
                .is_some_and(|active| revision.revision <= active)
            {
                return Err(invalid_fee_sponsor_program(
                    "staged fee sponsor program revision must increase monotonically",
                ));
            }
            validate_fee_sponsor_revision(&revision, state_transaction)?;
            state_transaction
                .world
                .fee_sponsor_program_revisions
                .insert(
                    FeeSponsorProgramRevisionKey::new(
                        revision.program_id.clone(),
                        revision.revision,
                    ),
                    revision.clone(),
                );
            program.staged_revision = Some(revision.revision);
            state_transaction
                .world
                .fee_sponsor_programs
                .insert(program.id.clone(), program);
            Ok(())
        }
    }
    impl Execute for nexus::ActivateFeeSponsorProgramRevision {
        #[metrics(+"activate_fee_sponsor_program_revision")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::nexus::{
                FeeSponsorEligibility, FeeSponsorProgramActivation, FeeSponsorProgramLifecycle,
            };
            let program_id = self.program_id().clone();
            ensure_fee_sponsor_program_owner(authority, &program_id, state_transaction)?;
            if *self.activate_at_height() < state_transaction.block_height() {
                return Err(invalid_fee_sponsor_program(format!(
                    "fee sponsor revision activation height cannot precede executing block height {}",
                    state_transaction.block_height()
                )));
            }
            let mut program = state_transaction
                .world
                .fee_sponsor_programs
                .get(&program_id)
                .cloned()
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor program not found"))?;
            if program.staged_revision != Some(*self.revision()) {
                return Err(invalid_fee_sponsor_program(
                    "requested fee sponsor revision is not staged",
                ));
            }
            if matches!(
                program.lifecycle,
                FeeSponsorProgramLifecycle::Closing | FeeSponsorProgramLifecycle::Closed
            ) {
                return Err(invalid_fee_sponsor_program(
                    "closing or closed fee sponsor program cannot activate",
                ));
            }
            let revision = state_transaction
                .world
                .fee_sponsor_program_revisions
                .get(&FeeSponsorProgramRevisionKey::new(
                    program_id.clone(),
                    *self.revision(),
                ))
                .cloned()
                .ok_or_else(|| invalid_fee_sponsor_program("staged revision record is missing"))?;
            for budget in &revision.asset_budgets {
                let vault_key = iroha_data_model::nexus::FeeSponsorVaultKey {
                    program_id: program_id.clone(),
                    asset_definition_id: budget.asset_definition_id.clone(),
                };
                let minimum = budget
                    .reserve_floor
                    .checked_add(&budget.per_transaction)
                    .map_err(|_| {
                        invalid_fee_sponsor_program("fee sponsor readiness sum overflow")
                    })?;
                let balance = state_transaction
                    .world
                    .fee_sponsor_vaults
                    .get(&vault_key)
                    .map_or_else(Quantity::zero, |vault| vault.balance.clone());
                if balance < minimum {
                    return Err(invalid_fee_sponsor_program(format!(
                        "fee sponsor vault `{}` requires at least {minimum} before activation; available {balance}",
                        budget.asset_definition_id
                    )));
                }
            }
            let has_enrollment = state_transaction
                .world
                .fee_sponsor_enrollments
                .iter()
                .any(|(key, _)| key.program_id == program_id);
            let is_route_default = state_transaction
                .nexus
                .dataspace_fee_sponsor_program_ids
                .values()
                .any(|default| default == &program_id);
            if !has_enrollment
                && (revision.eligibility == FeeSponsorEligibility::EnrolledOnly
                    || !is_route_default)
            {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor program has no eligible beneficiary or exact route-default binding",
                ));
            }
            let safe_activation_height = fee_sponsor_revision_safe_activation_height(
                &state_transaction.world,
                &program_id,
                revision.revision,
                state_transaction.block_height(),
                *self.activate_at_height(),
            )
            .map_err(invalid_fee_sponsor_program)?;
            if safe_activation_height == state_transaction.block_height() {
                program.active_revision = Some(revision.revision);
                program.staged_revision = None;
                program.scheduled_activation = None;
                program.lifecycle = FeeSponsorProgramLifecycle::Active;
            } else {
                program.scheduled_activation = Some(FeeSponsorProgramActivation {
                    revision: revision.revision,
                    activate_at_height: safe_activation_height,
                });
            }
            state_transaction
                .world
                .fee_sponsor_programs
                .insert(program_id, program);
            Ok(())
        }
    }
    impl Execute for nexus::PauseFeeSponsorProgram {
        #[metrics(+"pause_fee_sponsor_program")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::nexus::FeeSponsorProgramLifecycle;
            let program_id = self.program_id().clone();
            ensure_fee_sponsor_program_owner(authority, &program_id, state_transaction)?;
            let mut program = state_transaction
                .world
                .fee_sponsor_programs
                .get(&program_id)
                .cloned()
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor program not found"))?;
            if program.lifecycle != FeeSponsorProgramLifecycle::Active {
                return Err(invalid_fee_sponsor_program(
                    "only an active fee sponsor program can be paused",
                ));
            }
            program.lifecycle = FeeSponsorProgramLifecycle::Paused;
            program.scheduled_activation = None;
            state_transaction
                .world
                .fee_sponsor_programs
                .insert(program_id, program);
            Ok(())
        }
    }
    impl Execute for nexus::BeginCloseFeeSponsorProgram {
        #[metrics(+"begin_close_fee_sponsor_program")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::nexus::FeeSponsorProgramLifecycle;
            let program_id = self.program_id().clone();
            ensure_fee_sponsor_program_owner(authority, &program_id, state_transaction)?;
            let mut program = state_transaction
                .world
                .fee_sponsor_programs
                .get(&program_id)
                .cloned()
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor program not found"))?;
            if program.lifecycle != FeeSponsorProgramLifecycle::Paused {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor program must be paused before closing",
                ));
            }
            program.lifecycle = FeeSponsorProgramLifecycle::Closing;
            program.staged_revision = None;
            program.scheduled_activation = None;
            state_transaction
                .world
                .fee_sponsor_programs
                .insert(program_id, program);
            Ok(())
        }
    }
    impl Execute for nexus::CloseFeeSponsorProgram {
        #[metrics(+"close_fee_sponsor_program")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::nexus::FeeSponsorProgramLifecycle;
            let program_id = self.program_id().clone();
            ensure_fee_sponsor_program_owner(authority, &program_id, state_transaction)?;
            let mut program = state_transaction
                .world
                .fee_sponsor_programs
                .get(&program_id)
                .cloned()
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor program not found"))?;
            if program.lifecycle != FeeSponsorProgramLifecycle::Closing {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor program must be closing before final closure",
                ));
            }
            if state_transaction
                .world
                .fee_sponsor_enrollments
                .iter()
                .any(|(key, _)| key.program_id == program_id)
                || state_transaction
                    .world
                    .fee_sponsor_vaults
                    .iter()
                    .any(|(key, vault)| key.program_id == program_id && !vault.balance.is_zero())
            {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor program cannot close until enrollments and vaults are empty",
                ));
            }
            if fee_sponsor_program_has_unsettled_relay_usage(&state_transaction.world, &program_id)
                .map_err(invalid_fee_sponsor_program)?
            {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor program cannot close while relay receipts remain unsettled",
                ));
            }
            program.lifecycle = FeeSponsorProgramLifecycle::Closed;
            program.active_revision = None;
            program.staged_revision = None;
            program.scheduled_activation = None;
            state_transaction
                .world
                .fee_sponsor_programs
                .insert(program_id, program);
            Ok(())
        }
    }
    impl Execute for nexus::EnrollFeeSponsorBeneficiary {
        #[metrics(+"enroll_fee_sponsor_beneficiary")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::nexus::{
                FeeSponsorEnrollment, FeeSponsorEnrollmentKey, FeeSponsorProgramLifecycle,
            };
            let program_id = self.program_id().clone();
            ensure_fee_sponsor_enrollment_authority(authority, &program_id, state_transaction)?;
            let program = state_transaction
                .world
                .fee_sponsor_programs
                .get(&program_id)
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor program not found"))?;
            if program.lifecycle == FeeSponsorProgramLifecycle::Closed {
                return Err(invalid_fee_sponsor_program(
                    "closed fee sponsor program cannot enroll beneficiaries",
                ));
            }
            if state_transaction
                .world
                .accounts
                .get(self.beneficiary())
                .is_none()
            {
                return Err(invalid_fee_sponsor_program(format!(
                    "unknown fee sponsor beneficiary `{}`",
                    self.beneficiary()
                )));
            }
            let key = FeeSponsorEnrollmentKey {
                program_id,
                beneficiary: self.beneficiary().clone(),
            };
            if state_transaction
                .world
                .fee_sponsor_enrollments
                .get(&key)
                .is_none()
            {
                state_transaction.world.fee_sponsor_enrollments.insert(
                    key.clone(),
                    FeeSponsorEnrollment {
                        key,
                        enrolled_at_height: state_transaction.block_height(),
                    },
                );
            }
            Ok(())
        }
    }
    impl Execute for nexus::UnenrollFeeSponsorBeneficiary {
        #[metrics(+"unenroll_fee_sponsor_beneficiary")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let program_id = self.program_id().clone();
            ensure_fee_sponsor_enrollment_authority(authority, &program_id, state_transaction)?;
            if state_transaction
                .world
                .fee_sponsor_programs
                .get(&program_id)
                .is_none()
            {
                return Err(invalid_fee_sponsor_program("fee sponsor program not found"));
            }
            state_transaction.world.fee_sponsor_enrollments.remove(
                iroha_data_model::nexus::FeeSponsorEnrollmentKey {
                    program_id,
                    beneficiary: self.beneficiary().clone(),
                },
            );
            Ok(())
        }
    }
    impl Execute for nexus::FundFeeSponsorProgram {
        #[metrics(+"fund_fee_sponsor_program")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::nexus::{
                FeeSponsorProgramLifecycle, FeeSponsorVault, FeeSponsorVaultKey,
            };
            let program_id = self.program_id().clone();
            ensure_fee_sponsor_program_owner(authority, &program_id, state_transaction)?;
            if self.amount().is_zero() {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor vault funding amount must be positive",
                ));
            }
            let program = state_transaction
                .world
                .fee_sponsor_programs
                .get(&program_id)
                .cloned()
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor program not found"))?;
            if matches!(
                program.lifecycle,
                FeeSponsorProgramLifecycle::Closing | FeeSponsorProgramLifecycle::Closed
            ) {
                return Err(invalid_fee_sponsor_program(
                    "closing or closed fee sponsor program cannot be funded",
                ));
            }
            let definition = state_transaction
                .world
                .asset_definitions
                .get(self.asset_definition_id())
                .cloned()
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor vault asset not found"))?;
            ensure_global_fee_sponsor_asset(&definition, "fee sponsor vault funding")?;
            if state_transaction
                .world
                .accounts
                .get(
                    &state_transaction
                        .nexus
                        .fees
                        .sponsor_vault_custody_account_id,
                )
                .is_none()
            {
                return Err(invalid_fee_sponsor_program(
                    "configured sponsor vault custody account is not registered",
                ));
            }
            let dataspace = state_transaction
                .current_dataspace_id
                .unwrap_or(iroha_data_model::nexus::DataSpaceId::UNIVERSAL);
            let source = AssetId::with_scope(
                self.asset_definition_id().clone(),
                program_id.sponsor.clone(),
                fee_sponsor_asset_scope(&definition, dataspace),
            );
            if crate::executor::is_initial_genesis_context(state_transaction) {
                crate::smartcontracts::isi::asset::isi::execute_initial_genesis_fee_sponsor_funding_transfer(
                    state_transaction,
                    authority,
                    &program_id,
                    source,
                    self.amount().clone(),
                )?;
            } else {
                Transfer::<Asset, Quantity, Account>::asset_quantity(
                    source,
                    self.amount().clone(),
                    state_transaction
                        .nexus
                        .fees
                        .sponsor_vault_custody_account_id
                        .clone(),
                )
                .execute(authority, state_transaction)?;
            }
            let key = FeeSponsorVaultKey {
                program_id: program_id.clone(),
                asset_definition_id: self.asset_definition_id().clone(),
            };
            let balance = state_transaction
                .world
                .fee_sponsor_vaults
                .get(&key)
                .map_or_else(Quantity::zero, |vault| vault.balance.clone())
                .checked_add(self.amount())
                .map_err(|_| invalid_fee_sponsor_program("fee sponsor vault balance overflow"))?;
            state_transaction
                .world
                .fee_sponsor_vaults
                .insert(key.clone(), FeeSponsorVault { key, balance });
            Ok(())
        }
    }
    impl Execute for nexus::WithdrawFeeSponsorProgram {
        #[metrics(+"withdraw_fee_sponsor_program")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            use iroha_data_model::nexus::{FeeSponsorProgramLifecycle, FeeSponsorVaultKey};
            let program_id = self.program_id().clone();
            ensure_fee_sponsor_withdrawal_authority(authority, &program_id)?;
            if self.amount().is_zero() {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor vault withdrawal amount must be positive",
                ));
            }
            let program = state_transaction
                .world
                .fee_sponsor_programs
                .get(&program_id)
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor program not found"))?;
            let payout_account = program.payout_account.clone();
            if !matches!(
                program.lifecycle,
                FeeSponsorProgramLifecycle::Paused | FeeSponsorProgramLifecycle::Closing
            ) {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor program must be paused or closing before withdrawal",
                ));
            }
            if program.scheduled_activation.is_some() {
                return Err(invalid_fee_sponsor_program(
                    "fee sponsor program cannot withdraw while activation is scheduled",
                ));
            }
            if state_transaction
                .world
                .accounts
                .get(&payout_account)
                .is_none()
            {
                return Err(invalid_fee_sponsor_program(
                    "registered fee sponsor payout account is no longer present",
                ));
            }
            let definition = state_transaction
                .world
                .asset_definitions
                .get(self.asset_definition_id())
                .cloned()
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor vault asset not found"))?;
            let key = FeeSponsorVaultKey {
                program_id: program_id.clone(),
                asset_definition_id: self.asset_definition_id().clone(),
            };
            let mut vault = state_transaction
                .world
                .fee_sponsor_vaults
                .get(&key)
                .cloned()
                .ok_or_else(|| invalid_fee_sponsor_program("fee sponsor vault is not funded"))?;
            let remaining = vault
                .balance
                .checked_sub(self.amount())
                .map_err(|_| invalid_fee_sponsor_program("fee sponsor vault is insufficient"))?;
            let locked = locked_fee_sponsor_vault_capacity(
                &state_transaction.world,
                &program_id,
                self.asset_definition_id(),
                state_transaction.block_height(),
            )
            .map_err(invalid_fee_sponsor_program)?;
            if remaining < locked {
                return Err(invalid_fee_sponsor_program(format!(
                    "fee sponsor vault withdrawal would consume {locked} of unexpired relay allocation capacity"
                )));
            }
            vault.balance = remaining;
            let dataspace = state_transaction
                .current_dataspace_id
                .unwrap_or(iroha_data_model::nexus::DataSpaceId::UNIVERSAL);
            let source = AssetId::with_scope(
                self.asset_definition_id().clone(),
                state_transaction
                    .nexus
                    .fees
                    .sponsor_vault_custody_account_id
                    .clone(),
                fee_sponsor_asset_scope(&definition, dataspace),
            );
            let withdrawal = VerifiedFeeSponsorVaultWithdrawal::new(
                authority.clone(),
                program_id.clone(),
                source,
                payout_account,
                self.amount().clone(),
            );
            crate::smartcontracts::isi::asset::isi::execute_verified_fee_sponsor_vault_withdrawal(
                state_transaction,
                withdrawal,
            )?;
            if vault.balance.is_zero() {
                state_transaction.world.fee_sponsor_vaults.remove(key);
            } else {
                state_transaction
                    .world
                    .fee_sponsor_vaults
                    .insert(key, vault);
            }
            Ok(())
        }
    }
    fn parse_config_asset_definition_id(
        world: &impl crate::state::WorldReadOnly,
        raw: &str,
        now_ms: u64,
    ) -> Option<AssetDefinitionId> {
        crate::block::parse_asset_definition_literal_with_world(world, raw, now_ms)
    }
    fn is_permission_domain_associated(
        permission: &Permission,
        domain_id: &DomainId,
        asset_definition_ids: &BTreeSet<AssetDefinitionId>,
        domain_dataspace: Option<DataSpaceId>,
    ) -> bool {
        let asset_definition_matches_domain = |asset_definition: &AssetDefinitionId| -> bool {
            asset_definition_ids.contains(asset_definition)
        };
        if let Ok(permission) = CanUnregisterDomain::try_from(permission) {
            return &permission.domain == domain_id;
        }
        if let Ok(permission) = CanModifyDomainMetadata::try_from(permission) {
            return &permission.domain == domain_id;
        }
        if let Ok(permission) = CanRegisterAccount::try_from(permission) {
            return &permission.domain == domain_id;
        }
        if let Ok(permission) = CanResolveAccountAlias::try_from(permission) {
            return match &permission.scope {
                AccountAliasPermissionScope::Domain(domain) => domain == domain_id,
                AccountAliasPermissionScope::Alias(alias) => {
                    alias.canonical_name.domain.as_ref() == Some(domain_id.name())
                        && &alias.canonical_name.dataspace == domain_id.dataspace()
                }
                AccountAliasPermissionScope::Dataspace(_) => false,
            };
        }
        if let Ok(permission) = CanDelegateAccountAliasResolution::try_from(permission) {
            return match &permission.scope {
                AccountAliasPermissionScope::Domain(domain) => domain == domain_id,
                AccountAliasPermissionScope::Alias(alias) => {
                    alias.canonical_name.domain.as_ref() == Some(domain_id.name())
                        && &alias.canonical_name.dataspace == domain_id.dataspace()
                }
                AccountAliasPermissionScope::Dataspace(_) => false,
            };
        }
        if let Ok(permission) = CanManageAccountAlias::try_from(permission) {
            return match &permission.scope {
                AccountAliasPermissionScope::Domain(domain) => domain == domain_id,
                AccountAliasPermissionScope::Alias(alias) => {
                    alias.canonical_name.domain.as_ref() == Some(domain_id.name())
                        && &alias.canonical_name.dataspace == domain_id.dataspace()
                }
                AccountAliasPermissionScope::Dataspace(_) => false,
            };
        }
        if let Ok(permission) = CanManageAssetDefinitionAlias::try_from(permission) {
            return match &permission.scope {
                AssetDefinitionAliasPermissionScope::Domain(domain) => domain == domain_id,
                AssetDefinitionAliasPermissionScope::Alias(alias) => {
                    alias.canonical_name.domain_segment() == Some(domain_id.name().as_ref())
                        && alias.canonical_name.dataspace_segment()
                            == domain_id.dataspace().as_ref()
                }
                AssetDefinitionAliasPermissionScope::Dataspace(_) => false,
            };
        }
        if let Ok(permission) = CanUnregisterAssetDefinition::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition);
        }
        if let Ok(permission) = CanModifyAssetDefinitionMetadata::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition);
        }
        if let Ok(permission) = CanManageAssetDefinitionConfidentialPolicy::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition);
        }
        if let Ok(permission) = CanMintAssetWithDefinition::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition);
        }
        if let Ok(permission) = CanBurnAssetWithDefinition::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition);
        }
        if let Ok(permission) = CanTransferAssetWithDefinition::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition);
        }
        if let Ok(permission) = CanModifyAssetMetadataWithDefinition::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition);
        }
        if let Ok(permission) = CanMintAssetToAccount::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition);
        }
        if let Ok(permission) = CanBurnAsset::try_from(permission) {
            return asset_definition_matches_domain(permission.asset.definition());
        }
        if let Ok(permission) = CanTransferAsset::try_from(permission) {
            return asset_definition_matches_domain(permission.asset.definition());
        }
        if let Ok(permission) = CanModifyAssetMetadata::try_from(permission) {
            return asset_definition_matches_domain(permission.asset.definition());
        }
        if let Ok(permission) = CanSetAssetTransferAvailability::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition);
        }
        if let Ok(permission) = CanSetAssetTransferDailyLimit::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition)
                || domain_dataspace.is_some_and(|dataspace| {
                    permission.account_dataspace == dataspace
                        && permission.account_domain.name() == domain_id.name()
                });
        }
        if let Ok(permission) = CanSetAssetHoldingLimit::try_from(permission) {
            return asset_definition_matches_domain(&permission.asset_definition);
        }
        if let Ok(permission) = CanExecuteSettlement::try_from(permission) {
            return asset_definition_matches_domain(permission.debited_asset.definition());
        }
        if let Ok(permission) =
            CanPublishSpaceDirectoryManifestForAccountDomain::try_from(permission)
        {
            return &permission.domain == domain_id;
        }
        if let Ok(permission) = CanRegisterNft::try_from(permission) {
            return &permission.domain == domain_id;
        }
        if let Ok(permission) = CanUnregisterNft::try_from(permission) {
            return permission.nft.domain() == domain_id;
        }
        if let Ok(permission) = CanTransferNft::try_from(permission) {
            return permission.nft.domain() == domain_id;
        }
        if let Ok(permission) = CanModifyNftMetadata::try_from(permission) {
            return permission.nft.domain() == domain_id;
        }
        false
    }
    fn remove_domain_associated_permissions(
        state_transaction: &mut StateTransaction<'_, '_>,
        domain_id: &DomainId,
        asset_definition_ids: &BTreeSet<AssetDefinitionId>,
        domain_dataspace: Option<DataSpaceId>,
    ) {
        let account_ids: Vec<AccountId> = state_transaction
            .world
            .account_permissions
            .iter()
            .map(|(account_id, _)| account_id.clone())
            .collect();
        for account_id in account_ids {
            let should_remove = state_transaction
                .world
                .account_permissions
                .get(&account_id)
                .is_some_and(|permissions| {
                    permissions.iter().any(|permission| {
                        is_permission_domain_associated(
                            permission,
                            domain_id,
                            asset_definition_ids,
                            domain_dataspace,
                        )
                    })
                });
            if !should_remove {
                continue;
            }
            let remove_entry = if let Some(permissions) = state_transaction
                .world
                .account_permissions
                .get_mut(&account_id)
            {
                permissions.retain(|permission| {
                    !is_permission_domain_associated(
                        permission,
                        domain_id,
                        asset_definition_ids,
                        domain_dataspace,
                    )
                });
                permissions.is_empty()
            } else {
                false
            };
            if remove_entry {
                state_transaction
                    .world
                    .account_permissions
                    .remove(account_id.clone());
            }
            state_transaction.invalidate_permission_cache_for_account(&account_id);
        }
        let role_ids: Vec<RoleId> = state_transaction
            .world
            .roles
            .iter()
            .map(|(role_id, _)| role_id.clone())
            .collect();
        for role_id in role_ids {
            let should_remove = state_transaction
                .world
                .roles
                .get(&role_id)
                .is_some_and(|role| {
                    role.permissions().any(|permission| {
                        is_permission_domain_associated(
                            permission,
                            domain_id,
                            asset_definition_ids,
                            domain_dataspace,
                        )
                    })
                });
            if !should_remove {
                continue;
            }
            let impacted_accounts = state_transaction.accounts_with_role(&role_id);
            if let Some(role) = state_transaction.world.roles.get_mut(&role_id) {
                role.permissions.retain(|permission| {
                    !is_permission_domain_associated(
                        permission,
                        domain_id,
                        asset_definition_ids,
                        domain_dataspace,
                    )
                });
                role.permission_epochs
                    .retain(|permission, _| role.permissions.contains(permission));
            }
            if !impacted_accounts.is_empty() {
                state_transaction.invalidate_permission_cache_for(impacted_accounts.iter());
            }
        }
    }
    impl Execute for Unregister<Domain> {
        #[metrics("unregister_domain")]
        fn execute(
            self,
            _authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let domain_id = self.object().clone();
            crate::smartcontracts::isi::kaigi::ensure_kaigi_domain_can_unregister(
                state_transaction,
                &domain_id,
            )?;
            let relabeled_accounts: Vec<AccountId> = state_transaction
                .world
                .accounts_in_domain_iter(&domain_id)
                .map(|account| account.id().clone())
                .collect();
            // This reverse index is rebuilt from the persisted authoritative mapping at restore
            // and maintained atomically by the world mutators. Enumerating it keeps teardown
            // proportional to the domain being removed instead of scanning every definition.
            let remove_asset_definitions: BTreeSet<AssetDefinitionId> = state_transaction
                .world
                .domain_asset_definitions
                .get(&domain_id)
                .cloned()
                .unwrap_or_default();
            if let Some((proposal_id, reference_kind, asset_definition_id)) =
                crate::validation_fee::retained_enacted_validation_fee_asset_reference_in(
                    state_transaction,
                    &remove_asset_definitions,
                )
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!(
                        "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is retained as the enacted validation-fee {reference_kind} by proposal {}",
                        hex::encode(proposal_id)
                    )
                    .into(),
                )
                .into());
            }
            let remove_assets = state_transaction
                .world
                .assets_by_domain
                .get(&domain_id)
                .cloned()
                .unwrap_or_default();
            let mut assets_from_definitions = BTreeSet::new();
            for asset_definition_id in &remove_asset_definitions {
                if state_transaction
                    .world
                    .asset_definitions
                    .get(asset_definition_id)
                    .is_none()
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: domain asset-definition index references missing definition {asset_definition_id}"
                        )
                        .into(),
                    )
                    .into());
                }
                if state_transaction
                    .world
                    .asset_definition_domains
                    .get(asset_definition_id)
                    != Some(&domain_id)
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} has inconsistent authoritative domain context"
                        )
                        .into(),
                    )
                    .into());
                }
                let definition_assets = state_transaction
                    .world
                    .asset_definition_assets
                    .get(asset_definition_id)
                    .cloned()
                    .unwrap_or_default();
                let mut expected_holders = BTreeSet::new();
                let mut expected_nonzero_holders = BTreeSet::new();
                for asset_id in &definition_assets {
                    if asset_id.definition() != asset_definition_id {
                        return Err(InstructionExecutionError::InvariantViolation(
                            format!(
                                "cannot unregister domain {domain_id}: asset-definition index for {asset_definition_id} contains foreign asset {asset_id}"
                            )
                            .into(),
                        )
                        .into());
                    }
                    let Some(value) = state_transaction.world.assets.get(asset_id) else {
                        return Err(InstructionExecutionError::InvariantViolation(
                            format!(
                                "cannot unregister domain {domain_id}: asset-definition index references missing asset {asset_id}"
                            )
                            .into(),
                        )
                        .into());
                    };
                    if !state_transaction
                        .world
                        .assets_by_account
                        .get(asset_id.account())
                        .is_some_and(|assets| assets.contains(asset_id))
                    {
                        return Err(InstructionExecutionError::InvariantViolation(
                            format!(
                                "cannot unregister domain {domain_id}: account asset index omits {asset_id}"
                            )
                            .into(),
                        )
                        .into());
                    }
                    expected_holders.insert(asset_id.account().clone());
                    if !value.as_ref().is_zero() {
                        expected_nonzero_holders.insert(asset_id.account().clone());
                    }
                }
                if state_transaction
                    .world
                    .asset_definition_holders
                    .get(asset_definition_id)
                    .cloned()
                    .unwrap_or_default()
                    != expected_holders
                    || state_transaction
                        .world
                        .asset_definition_nonzero_holders
                        .get(asset_definition_id)
                        .cloned()
                        .unwrap_or_default()
                        != expected_nonzero_holders
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: holder indexes for asset definition {asset_definition_id} are inconsistent"
                        )
                        .into(),
                    )
                    .into());
                }
                assets_from_definitions.extend(definition_assets);
            }
            if remove_assets != assets_from_definitions {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!(
                        "cannot unregister domain {domain_id}: domain and asset-definition asset indexes disagree"
                    )
                    .into(),
                )
                .into());
            }
            let orchard_pool_references =
                crate::privacy_state::load_privacy_orchard_pool_references_v1(
                    &state_transaction.world.privacy_commitments,
                )
                .map_err(|message| {
                    InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: persisted Orchard pool state is invalid: {message}"
                        )
                        .into(),
                    )
                })?;
            if let Some(reference) = orchard_pool_references.iter().find(|reference| {
                remove_asset_definitions.contains(reference.asset_definition_id())
            }) {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!(
                        "cannot unregister domain {domain_id}: asset definition {} backs governed Orchard pool {:?}",
                        reference.asset_definition_id(),
                        reference.namespace()
                    )
                    .into(),
                )
                .into());
            }
            for account_id in &relabeled_accounts {
                if account_id == &state_transaction.gov.bond_escrow_account
                    || account_id == &state_transaction.gov.slash_receiver_account
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: account {account_id} is configured as active governance bond custody; update governance config first"
                        )
                        .into(),
                    )
                    .into());
                }
                if let Some((referendum_id, _)) = state_transaction
                    .world
                    .governance_locks
                    .iter()
                    .find(|(_, locks)| {
                        locks.locks.values().any(|record| {
                            record.custody.bond_escrow_account == *account_id
                                || record.custody.slash_receiver_account == *account_id
                        })
                    })
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: account {account_id} is retained by immutable governance lock custody (referendum {referendum_id}); clear the governance locks first"
                        )
                        .into(),
                    )
                    .into());
                }
            }
            for asset_definition_id in &remove_asset_definitions {
                if let Some((referendum_id, _)) = state_transaction
                    .world
                    .governance_locks
                    .iter()
                    .find(|(_, locks)| {
                        locks.locks.values().any(|record| {
                            record.custody.asset_definition_id == *asset_definition_id
                        })
                    })
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is retained by immutable governance lock custody (referendum {referendum_id}); clear the governance locks first"
                        )
                        .into(),
                    )
                    .into());
                }
            }
            let domain_dataspace = state_transaction
                .nexus
                .dataspace_catalog
                .by_alias(domain_id.dataspace().as_ref())
                .map(|entry| entry.id);
            remove_domain_associated_permissions(
                state_transaction,
                &domain_id,
                &remove_asset_definitions,
                domain_dataspace,
            );
            state_transaction
                .world
                .domain_endorsement_policies
                .remove(domain_id.clone());
            let mut endorsement_hashes = BTreeSet::new();
            if let Some(hashes) = state_transaction
                .world
                .domain_endorsements_by_domain
                .remove(domain_id.clone())
            {
                endorsement_hashes.extend(hashes);
            }
            for (hash, record) in state_transaction.world.domain_endorsements.iter() {
                if record.endorsement.domain_id == domain_id {
                    endorsement_hashes.insert(*hash);
                }
            }
            for hash in endorsement_hashes {
                state_transaction.world.domain_endorsements.remove(hash);
            }
            let remove_nfts: BTreeSet<NftId> = state_transaction
                .world
                .nfts_in_domain_iter(&domain_id)
                .map(|nft| nft.id().clone())
                .collect();
            if let Some(rwa_id) = state_transaction
                .world
                .rwas_in_domain_iter(&domain_id)
                .map(|rwa| rwa.id().clone())
                .next()
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!(
                        "cannot unregister domain {domain_id}: RWA {rwa_id} still exists in the domain; transfer or redeem all RWAs first"
                    )
                    .into(),
                )
                .into());
            }
            for nft_id in remove_nfts {
                crate::smartcontracts::isi::nft::isi::remove_nft_associated_permissions(
                    state_transaction,
                    &nft_id,
                );
                state_transaction.world.remove_nft_entry(&nft_id);
                state_transaction
                    .world
                    .emit_events(Some(DomainEvent::Nft(NftEvent::Deleted(nft_id))));
            }
            for asset_definition_id in &remove_asset_definitions {
                if asset_definition_id == &state_transaction.gov.voting_asset_id {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is configured as governance voting asset definition (`gov.voting_asset_id`); update governance config first"
                        )
                        .into(),
                    )
                    .into());
                }
                if asset_definition_id == &state_transaction.gov.citizenship_asset_id {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is configured as governance citizenship asset definition (`gov.citizenship_asset_id`); update governance config first"
                        )
                        .into(),
                    )
                    .into());
                }
                if asset_definition_id == &state_transaction.gov.parliament_eligibility_asset_id {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is configured as governance parliament eligibility asset definition (`gov.parliament_eligibility_asset_id`); update governance config first"
                        )
                        .into(),
                    )
                    .into());
                }
                if asset_definition_id
                    == &state_transaction
                        .gov
                        .viral_incentives
                        .reward_asset_definition_id
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is configured as governance viral reward asset definition (`gov.viral_incentives.reward_asset_definition_id`); update governance config first"
                        )
                        .into(),
                    )
                    .into());
                }
                if asset_definition_id == &state_transaction.oracle.economics.reward_asset {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is configured as oracle reward asset definition (`oracle.economics.reward_asset`); update oracle config first"
                        )
                        .into(),
                    )
                    .into());
                }
                if asset_definition_id == &state_transaction.oracle.economics.slash_asset {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is configured as oracle slash asset definition (`oracle.economics.slash_asset`); update oracle config first"
                        )
                        .into(),
                    )
                    .into());
                }
                if asset_definition_id == &state_transaction.oracle.economics.dispute_bond_asset {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is configured as oracle dispute bond asset definition (`oracle.economics.dispute_bond_asset`); update oracle config first"
                        )
                        .into(),
                    )
                    .into());
                }
                if parse_config_asset_definition_id(
                    &state_transaction.world,
                    &state_transaction.nexus.fees.fee_asset_id,
                    state_transaction.block_unix_timestamp_ms(),
                )
                .is_some_and(|configured| &configured == asset_definition_id)
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is configured as nexus fee asset definition (`nexus.fees.fee_asset_id`); update nexus config first"
                        )
                        .into(),
                    )
                    .into());
                }
                if parse_config_asset_definition_id(
                    &state_transaction.world,
                    &state_transaction.nexus.staking.stake_asset_id,
                    state_transaction.block_unix_timestamp_ms(),
                )
                .is_some_and(|configured| &configured == asset_definition_id)
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is configured as nexus staking asset definition (`nexus.staking.stake_asset_id`); update nexus config first"
                        )
                        .into(),
                    )
                    .into());
                }
                if let Some((agreement_id, _)) = state_transaction
                    .world
                    .repo_agreements
                    .iter()
                    .find(|(_, agreement)| {
                        agreement.cash_leg().asset_definition_id() == asset_definition_id
                            || agreement.collateral_leg().asset_definition_id()
                                == asset_definition_id
                    })
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is referenced by repo agreement state ({agreement_id}); retain asset definition for settlement audit references"
                        )
                        .into(),
                    )
                    .into());
                }
                if let Some((settlement_id, _)) = state_transaction
                    .world
                    .settlement_receipts
                    .iter()
                    .find(|(_, receipt)| {
                        receipt
                            .legs
                            .iter()
                            .any(|leg| leg.leg.asset_definition_id() == asset_definition_id)
                    })
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} is referenced by committed settlement receipt {settlement_id}"
                        )
                        .into(),
                    )
                    .into());
                }
                if let Some(((lane_id, epoch), _)) = state_transaction
                    .world
                    .public_lane_rewards
                    .iter()
                    .find(|(key, record)| {
                        public_lane_reward_record_matches_key(key, record)
                            && record.asset.definition() == asset_definition_id
                    })
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} has active public-lane reward ledger state (lane {lane_id}, epoch {epoch}); settle or prune rewards first"
                        )
                        .into(),
                    )
                    .into());
                }
                if let Some(((lane_id, claimant, asset_id), _)) = state_transaction
                    .world
                    .public_lane_reward_claims
                    .iter()
                    .find(|((_, _, asset_id), _)| asset_id.definition() == asset_definition_id)
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset definition {asset_definition_id} has pending public-lane reward claim state (lane {lane_id}, account {claimant}, asset {asset_id}); claim or clear rewards first"
                        )
                        .into(),
                    )
                    .into());
                }
            }
            for asset_id in &remove_assets {
                state_transaction
                    .world
                    .remove_asset_and_metadata_with_total(asset_id)?;
            }
            if state_transaction
                .world
                .assets_by_domain
                .get(&domain_id)
                .is_some()
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    format!(
                        "cannot unregister domain {domain_id}: domain asset index remained after exact asset removal"
                    )
                    .into(),
                )
                .into());
            }
            for asset_id in &remove_assets {
                if state_transaction
                    .world
                    .assets_by_account
                    .get(asset_id.account())
                    .is_some_and(|assets| assets.contains(asset_id))
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: account asset index retained removed asset {asset_id}"
                        )
                        .into(),
                    )
                    .into());
                }
            }
            for asset_definition_id in &remove_asset_definitions {
                if state_transaction
                    .world
                    .asset_definition_assets
                    .get(asset_definition_id)
                    .is_some()
                    || state_transaction
                        .world
                        .asset_definition_holders
                        .get(asset_definition_id)
                        .is_some()
                    || state_transaction
                        .world
                        .asset_definition_nonzero_holders
                        .get(asset_definition_id)
                        .is_some()
                {
                    return Err(InstructionExecutionError::InvariantViolation(
                        format!(
                            "cannot unregister domain {domain_id}: asset indexes remained after removing assets for definition {asset_definition_id}"
                        )
                        .into(),
                    )
                    .into());
                }
            }
            for asset_definition_id in remove_asset_definitions {
                state_transaction
                    .settlement
                    .offline
                    .escrow_accounts
                    .remove(&asset_definition_id);
                state_transaction
                    .world
                    .zk_assets
                    .remove(asset_definition_id.clone());
                state_transaction
                    .world
                    .remove_asset_definition_entry(&asset_definition_id);
            }
            for account_id in relabeled_accounts {
                let alias_matches_domain =
                    |label: &AccountAlias| -> Result<bool, InstructionExecutionError> {
                        label
                            .domain_id(&state_transaction.nexus.dataspace_catalog)
                            .map(|resolved| resolved.as_ref() == Some(&domain_id))
                            .map_err(|err| {
                                InstructionExecutionError::InvariantViolation(
                                    format!(
                                        "account alias `{:?}` could not resolve its qualified domain: {err}",
                                        label
                                    )
                                    .into(),
                                )
                            })
                    };
                let labels = state_transaction
                    .world
                    .account_aliases_by_account
                    .get(&account_id)
                    .cloned()
                    .unwrap_or_default()
                    .into_iter()
                    .filter_map(|label| match alias_matches_domain(&label) {
                        Ok(true) => Some(Ok(label)),
                        Ok(false) => None,
                        Err(err) => Some(Err(err)),
                    })
                    .collect::<Result<Vec<_>, _>>()?;
                let clear_primary_label = state_transaction
                    .world
                    .accounts
                    .get(&account_id)
                    .and_then(|account| account.label().cloned())
                    .map_or(Ok(false), |label| alias_matches_domain(&label))?;
                if clear_primary_label
                    && let Some(account) = state_transaction.world.accounts.get_mut(&account_id)
                {
                    account.set_label(None);
                }
                for label in labels {
                    state_transaction.world.remove_account_rekey_record(&label);
                    state_transaction.world.remove_account_alias_binding(&label);
                }
            }
            if state_transaction
                .world
                .remove_domain_entry(&domain_id)
                .is_none()
            {
                return Err(FindError::Domain(domain_id).into());
            }
            state_transaction
                .world
                .emit_events(Some(DomainEvent::Deleted(domain_id)));
            Ok(())
        }
    }
    impl Execute for Register<Role> {
        #[metrics(+"register_role")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            // Preserve the requested initial owner before building the role.
            let new_role = self.object().clone();
            let initial_owner = new_role.grant_to().clone();
            let mut role = new_role.build(authority);
            role.ensure_permission_epochs(state_transaction.block_height());
            if role.permissions().any(|permission| {
                !crate::alias::asset_definition_alias_permission_targets_active_binding(
                    &state_transaction.world,
                    permission,
                    state_transaction.block_unix_timestamp_ms(),
                )
            }) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "exact asset-definition alias role permission does not target its current live binding"
                        .into(),
                ));
            }
            if role.permissions().any(|permission| {
                crate::validation_fee::permission_targets_enacted_validation_fee_payout_trigger(
                    state_transaction,
                    permission,
                ) || crate::validation_fee::enacted_validation_fee_payout_runtime_permission_owner(
                    state_transaction,
                    permission,
                )
                .is_some()
            }) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "an enacted validation-fee payout lifecycle forbids role delegation of its trigger or exact runtime permissions"
                        .into(),
                ));
            }
            if state_transaction.world.roles.get(role.id()).is_some() {
                return Err(RepetitionError {
                    instruction: InstructionType::Register,
                    id: IdBox::RoleId(role.id().clone()),
                }
                .into());
            }
            let world = &mut state_transaction.world;
            let role_id = role.id().clone();
            world.roles.insert(role_id.clone(), role.clone());
            // Emit the RoleCreated event first so the observable order matches
            // how clients expect to see events related to this role.
            world.emit_events(Some(RoleEvent::Created(role)));
            // Auto‑grant the newly created role to the designated initial owner
            // to reflect the semantic of `NewRole { grant_to, .. }`.
            // Reuse the existing Grant<RoleId, Account> execution to keep
            // validation and event emission consistent.
            // If the `initial_owner` account does not exist, surface a precise
            // "find account" error to the caller via the Grant path.
            Grant::account_role(role_id, initial_owner).execute(authority, state_transaction)?;
            Ok(())
        }
    }
    impl Execute for Unregister<Role> {
        #[metrics("unregister_role")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let role_id = self.object().clone();
            let accounts_with_role = state_transaction
                .world
                .account_roles
                .iter()
                .map(|(role, ())| role)
                .filter(|role| role.id.eq(&role_id))
                .map(|role| &role.account)
                .cloned()
                .collect::<Vec<_>>();
            for account_id in accounts_with_role {
                let revoke = Revoke::account_role(role_id.clone(), account_id);
                revoke.execute(authority, state_transaction)?
            }
            let world = &mut state_transaction.world;
            if world.roles.remove(role_id.clone()).is_none() {
                return Err(FindError::Role(role_id).into());
            }
            world.emit_events(Some(RoleEvent::Deleted(role_id)));
            Ok(())
        }
    }
    impl Execute for Grant<Permission, Role> {
        #[metrics(+"grant_role_permission")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let role_id = self.destination().clone();
            let permission = self.object().clone();
            let current_epoch = state_transaction.block_height();
            if !crate::alias::asset_definition_alias_permission_targets_active_binding(
                &state_transaction.world,
                &permission,
                state_transaction.block_unix_timestamp_ms(),
            ) {
                return Err(InstructionExecutionError::InvariantViolation(
                    "exact asset-definition alias role permission does not target its current live binding"
                        .into(),
                ));
            }
            if crate::validation_fee::permission_targets_enacted_validation_fee_payout_trigger(
                state_transaction,
                &permission,
            ) || crate::validation_fee::enacted_validation_fee_payout_runtime_permission_owner(
                state_transaction,
                &permission,
            )
            .is_some()
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "an enacted validation-fee payout lifecycle forbids role delegation of its trigger or exact runtime permissions"
                        .into(),
                ));
            }
            let Some(existing_role) = state_transaction.world.roles.get(&role_id) else {
                return Err(FindError::Role(role_id).into());
            };
            if existing_role.permissions().any(|p| p == &permission) {
                return Err(RepetitionError {
                    instruction: InstructionType::Grant,
                    id: permission.clone().into(),
                }
                .into());
            }
            let impacted_accounts = state_transaction.accounts_with_role(&role_id);
            // Rebuild role with added permission
            let mut new_role = Role::new(existing_role.id().clone(), authority.clone());
            for p in existing_role.permissions() {
                let epoch = existing_role.permission_epoch(p).unwrap_or_default();
                new_role = new_role.add_permission_with_epoch(p.clone(), epoch);
            }
            new_role = new_role.add_permission_with_epoch(permission.clone(), current_epoch);
            let new_role = new_role.build(authority);
            state_transaction
                .world
                .roles
                .insert(role_id.clone(), new_role);
            state_transaction
                .world
                .emit_events(Some(RoleEvent::PermissionAdded(RolePermissionChanged {
                    role: role_id,
                    permission,
                })));
            state_transaction.invalidate_permission_cache_for(impacted_accounts.iter());
            Ok(())
        }
    }
    impl Execute for Revoke<Permission, Role> {
        #[metrics(+"grant_role_permission")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let role_id = self.destination().clone();
            let permission = self.object().clone();
            let Some(existing_role) = state_transaction.world.roles.get(&role_id) else {
                return Err(FindError::Role(role_id).into());
            };
            if existing_role.permissions().all(|p| p != &permission) {
                return Err(FindError::Permission(permission.clone().into()).into());
            }
            let impacted_accounts = state_transaction.accounts_with_role(&role_id);
            // Rebuild role with removed permission
            let mut new_role = Role::new(existing_role.id().clone(), authority.clone());
            for p in existing_role.permissions() {
                if p != &permission {
                    let epoch = existing_role.permission_epoch(p).unwrap_or_default();
                    new_role = new_role.add_permission_with_epoch(p.clone(), epoch);
                }
            }
            let new_role = new_role.build(authority);
            state_transaction
                .world
                .roles
                .insert(role_id.clone(), new_role);
            state_transaction
                .world
                .emit_events(Some(RoleEvent::PermissionRemoved(RolePermissionChanged {
                    role: role_id,
                    permission,
                })));
            state_transaction.invalidate_permission_cache_for(impacted_accounts.iter());
            Ok(())
        }
    }
    impl Execute for SetParameter {
        #[metrics(+"set_parameter")]
        fn execute(
            self,
            _authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            crate::smartcontracts::isi::offline::validate_runtime_consensus_parameter_update(
                self.inner(),
                &state_transaction.world,
                state_transaction.kagemusha_release_catalog.is_configured(),
            )?;
            super::parameter_validation::validate_ivm_heap_parameter(self.inner())?;
            if let Parameter::Custom(custom) = self.inner() {
                validate_governed_pipeline_gas_parameter(custom)?;
                validate_hijiri_parameters(custom, state_transaction)?;
                validate_da_ingest_admission_policy(custom, state_transaction)?;
                validate_reputation_archive_retention_request(custom, state_transaction)?;
                match iroha_data_model::nexus::LaneLifecycleParameterV1::from_custom_parameter(
                    custom,
                ) {
                    Ok(Some(payload)) => state_transaction
                        .stage_consensus_lane_lifecycle(&payload)
                        .map_err(|err| {
                            InstructionExecutionError::InvalidParameter(
                                InvalidParameterError::SmartContract(format!(
                                    "invalid Nexus lane lifecycle transition: {err}"
                                )),
                            )
                        })?,
                    Ok(None) => {}
                    Err(err) => {
                        return Err(InstructionExecutionError::InvalidParameter(
                            InvalidParameterError::SmartContract(format!(
                                "invalid Nexus lane lifecycle parameter payload: {err}"
                            )),
                        ));
                    }
                }
            }
            macro_rules! set_parameter {
                ($($container:ident($param:ident.$field:ident) => $single:ident::$variant:ident),* $(,)?) => {
                    match self.inner().clone() { $(
                        Parameter::$container(iroha_data_model::parameter::$single::$variant(next)) => {
                            let params = state_transaction.world.parameters.get_mut();
                            let prev_value = params.$param.$field;
                            let prev_param = Parameter::$container(
                                iroha_data_model::parameter::$single::$variant(prev_value),
                            );
                            let new_param = Parameter::$container(
                                iroha_data_model::parameter::$single::$variant(next),
                            );
                            params.set_parameter(new_param.clone());
                            state_transaction.world.emit_events(
                                Some(ConfigurationEvent::Changed(ParameterChanged {
                                    old_value: prev_param,
                                    new_value: new_param,
                                }))
                            );
                        })*
                        Parameter::Custom(next) => {
                            if iroha_data_model::validation_fee::is_reserved_validation_fee_parameter_id(
                                next.id(),
                            ) {
                                return Err(InstructionExecutionError::InvalidParameter(
                                    InvalidParameterError::SmartContract(
                                        "validation-fee governance parameters can only be changed by an enacted SORA Parliament proposal"
                                            .to_owned(),
                                    ),
                                ));
                            }
                            if next.id()
                                == &iroha_data_model::parameter::system::consensus_metadata::handshake_meta_id()
                            {
                                if state_transaction.block_height() != 1 {
                                    return Err(InstructionExecutionError::InvalidParameter(
                                        InvalidParameterError::SmartContract(
                                            "signed consensus handshake metadata is immutable after genesis"
                                                .to_owned(),
                                        ),
                                    ));
                                }
                                let metadata: iroha_data_model::parameter::system::ConsensusHandshakeMetadata = next
                                    .payload()
                                    .try_into_any()
                                    .map_err(|error| {
                                        InstructionExecutionError::InvalidParameter(
                                            InvalidParameterError::SmartContract(format!(
                                                "invalid signed consensus handshake metadata payload: {error}"
                                            )),
                                        )
                                    })?;
                                metadata.validate().map_err(|error| {
                                    InstructionExecutionError::InvalidParameter(
                                        InvalidParameterError::SmartContract(format!(
                                            "invalid signed consensus handshake metadata: {error}"
                                        )),
                                    )
                                })?;
                                state_transaction
                                    .world
                                    .parameters
                                    .get_mut()
                                    .sumeragi
                                    .block_cadence_ms = metadata.block_cadence_ms;
                            }
                            if crate::state::is_retired_sccp_registry_parameter(&next) {
                                return Err(InstructionExecutionError::InvalidParameter(
                                    InvalidParameterError::SmartContract(
                                        "the reserved SCCP registry can only be changed by an exact due Parliament certificate"
                                            .to_owned(),
                                    ),
                                ));
                            }
                            if next.id()
                                == &iroha_data_model::isi::settlement::FxCorridorPolicyRegistry::parameter_id()
                            {
                                return Err(InstructionExecutionError::InvalidParameter(
                                    InvalidParameterError::SmartContract(
                                        "the reserved FX corridor policy registry can only be changed by SetFxCorridorPolicy"
                                            .to_owned(),
                                    ),
                                ));
                            }
                            let contract_code_cap_id = iroha_data_model::parameter::CustomParameterId(
                                "max_contract_code_bytes"
                                    .parse()
                                    .expect("static contract code cap parameter id"),
                            );
                            if next.id() == &contract_code_cap_id {
                                let cap_bytes = next
                                    .payload()
                                    .try_into_any_norito::<u64>()
                                    .map_err(|_| {
                                        invalid_smart_contract_parameter(
                                            "max_contract_code_bytes must be a Norito u64",
                                        )
                                    })?;
                                if cap_bytes > MAX_PORTABLE_CONTRACT_CODE_BYTES {
                                    return Err(invalid_smart_contract_parameter(format!(
                                        "max_contract_code_bytes exceeds the portable consensus limit: {cap_bytes} > {MAX_PORTABLE_CONTRACT_CODE_BYTES}"
                                    )));
                                }
                                validate_pending_contract_uploads_against_cap(
                                    cap_bytes,
                                    state_transaction,
                                )?;
                            }
                            if next.id()
                                == &iroha_data_model::parameter::system::SumeragiNposParameters::parameter_id()
                            {
                                let payload =
                                    norito::json::from_str::<norito::json::Value>(
                                        next.payload().get(),
                                    )
                                    .map_err(|error| {
                                        InstructionExecutionError::InvalidParameter(
                                            InvalidParameterError::SmartContract(format!(
                                                "invalid signed NPoS parameter payload: {error}"
                                            )),
                                        )
                                    })?;
                                // The typed decoder validates all reconfiguration bounds as one
                                // group. Preflight explicit numeric zeroes so callers retain the
                                // exact governed field diagnostic; typed decoding below still
                                // rejects missing, unknown, or mistyped fields.
                                for field in [
                                    "finality_margin_blocks",
                                    "evidence_horizon_blocks",
                                    "activation_lag_blocks",
                                    "slashing_delay_blocks",
                                ] {
                                    if payload.get(field).and_then(norito::json::Value::as_u64)
                                        == Some(0)
                                    {
                                        return Err(InstructionExecutionError::InvalidParameter(
                                            InvalidParameterError::SmartContract(format!(
                                                "SumeragiNposParameters.reconfig.{field} must be greater than zero"
                                            )),
                                        ));
                                    }
                                }
                                let npos = norito::json::value::from_value::<
                                    iroha_data_model::parameter::system::SumeragiNposParameters,
                                >(payload)
                                .map_err(|error| {
                                    InstructionExecutionError::InvalidParameter(
                                        InvalidParameterError::SmartContract(format!(
                                            "invalid signed NPoS parameter payload: {error}"
                                        )),
                                    )
                                })?;
                                npos.validate().map_err(|error| {
                                    InstructionExecutionError::InvalidParameter(
                                        InvalidParameterError::SmartContract(format!(
                                            "invalid signed NPoS parameters: {error}"
                                        )),
                                    )
                                })?;
                            }
                            let previous = {
                                let params = state_transaction.world.parameters.get_mut();
                                let previous = params.custom().get(next.id()).cloned();
                                params.set_parameter(Parameter::Custom(next.clone()));
                                previous
                            };
                            state_transaction.world.emit_events(Some(
                                ConfigurationEvent::Changed(ParameterChanged {
                                    old_value: Parameter::Custom(
                                        previous.unwrap_or_else(|| next.clone()),
                                    ),
                                    new_value: Parameter::Custom(next),
                                }),
                            ));
                        }
                        _ => {}
                    }
                };
            }
            set_parameter!(
                Sumeragi(sumeragi.max_clock_drift_ms) => SumeragiParameter::MaxClockDriftMs,
                Block(block.max_transactions) => BlockParameter::MaxTransactions,
                Transaction(transaction.max_instructions) => TransactionParameter::MaxInstructions,
                Transaction(transaction.ivm_bytecode_size) => TransactionParameter::IvmBytecodeSize,
                Transaction(transaction.max_tx_bytes) => TransactionParameter::MaxTxBytes,
                Transaction(transaction.max_decompressed_bytes) => TransactionParameter::MaxDecompressedBytes,
                Transaction(transaction.max_metadata_depth) => TransactionParameter::MaxMetadataDepth,
                Transaction(transaction.max_time_to_live_ms) => TransactionParameter::MaxTimeToLiveMs,
                SmartContract(smart_contract.fuel) => SmartContractParameter::Fuel,
                SmartContract(smart_contract.memory) => SmartContractParameter::Memory,
                SmartContract(smart_contract.execution_depth) => SmartContractParameter::ExecutionDepth,
                SmartContract(smart_contract.max_output_items) => SmartContractParameter::MaxOutputItems,
                SmartContract(smart_contract.max_output_bytes) => SmartContractParameter::MaxOutputBytes,
                Executor(executor.fuel) => SmartContractParameter::Fuel,
                Executor(executor.memory) => SmartContractParameter::Memory,
                Executor(executor.execution_depth) => SmartContractParameter::ExecutionDepth,
                Executor(executor.max_output_items) => SmartContractParameter::MaxOutputItems,
                Executor(executor.max_output_bytes) => SmartContractParameter::MaxOutputBytes,
            );
            Ok(())
        }
    }
    impl Execute for Upgrade {
        #[metrics(+"upgrade_executor")]
        fn execute(
            self,
            authority: &AccountId,
            state_transaction: &mut StateTransaction<'_, '_>,
        ) -> Result<(), Error> {
            let required: Permission = CanUpgradeExecutor.into();
            if !crate::executor::is_initial_genesis_context(state_transaction)
                && !has_exact_permission(&state_transaction.world, authority, &required)
            {
                return Err(InstructionExecutionError::InvariantViolation(
                    "not permitted: CanUpgradeExecutor".into(),
                ));
            }
            let raw_executor = self.executor();
            // Cloning executor to avoid multiple mutable borrows of `state_transaction`.
            let mut upgraded_executor = state_transaction.world.executor.clone();
            upgraded_executor
                .migrate(raw_executor.clone(), state_transaction, authority)
                .map_err(|migration_error| {
                    InvalidParameterError::SmartContract(format!(
                        "{:?}",
                        eyre::eyre!(migration_error).wrap_err("Migration failed"),
                    ))
                })?;
            *state_transaction.world.executor.get_mut() = upgraded_executor;
            state_transaction
                .world
                .emit_events(Some(ExecutorEvent::Upgraded(ExecutorUpgrade {
                    new_data_model: state_transaction.world.executor_data_model.clone(),
                })));
            Ok(())
        }
    }
    impl Execute for Log {
        fn execute(
            self,
            _authority: &AccountId,
            _state_transaction: &mut StateTransaction<'_, '_>,
        ) -> std::result::Result<(), Error> {
            const TARGET: &str = "log_isi";
            let Self { level, msg } = self;
            match level {
                Level::TRACE => iroha_logger::trace!(target: TARGET, "{}", msg),
                Level::DEBUG => iroha_logger::debug!(target: TARGET, "{}", msg),
                Level::INFO => iroha_logger::info!(target: TARGET, "{}", msg),
                Level::WARN => iroha_logger::warn!(target: TARGET, "{}", msg),
                Level::ERROR => iroha_logger::error!(target: TARGET, "{}", msg),
            }
            Ok(())
        }
    }
