        #[test]
        fn parliament_no_result_classification_rejects_tampered_persisted_release_pulse() {
            let state = blank_test_state();
            let header = first_test_block_header();
            let mut block = state.block(header);
            let mut state_transaction = block.transaction();
            let release_height = 41;
            let (key_record, pulse) = crate::beacon::signed_persisted_pulse_fixture_for_world(
                state_transaction.network_id,
                release_height,
            );
            state_transaction
                .world
                .global_beacon_key_sessions
                .insert(key_record.session.session_id, key_record);
            state_transaction
                .world
                .global_beacon_pulses
                .insert(pulse.pulse_id, pulse);
            state_transaction
                .world
                .global_beacon_pulse_slots
                .insert((pulse.network_id, pulse.height), pulse.pulse_id);
            let logical_session =
                iroha_data_model::governance::types::BeaconSessionId::for_network_v1(
                    &state_transaction.network_id,
                );

            assert!(parliament_verified_pulse_available_v1(
                logical_session,
                release_height,
                &state_transaction,
            ));

            let mut tampered = pulse;
            tampered.signature[0] ^= 0x01;
            state_transaction
                .world
                .global_beacon_pulses
                .insert(pulse.pulse_id, tampered);
            assert!(
                !parliament_verified_pulse_available_v1(
                    logical_session,
                    release_height,
                    &state_transaction,
                ),
                "a malformed stored signature must classify the release pulse as unavailable",
            );
        }

