        trait TestExecuteExt: Execute + Sized {
            fn expect_execute(
                self,
                authority: &AccountId,
                state_transaction: &mut StateTransaction<'_, '_>,
                expectation: &str,
            ) {
                self.execute(authority, state_transaction)
                    .expect(expectation);
            }
            fn expect_execute_err(
                self,
                authority: &AccountId,
                state_transaction: &mut StateTransaction<'_, '_>,
                expectation: &str,
            ) -> Error {
                self.execute(authority, state_transaction)
                    .expect_err(expectation)
            }
        }
        impl<T: Execute> TestExecuteExt for T {}
