        world_test!(validate_open_verify_envelope_metadata_checks_circuit_and_commitment {
            let vk_box = VerifyingKeyBox::new("halo2/ipa".into(), vec![1, 2, 3, 4]);
            let commitment = hash_vk(&vk_box);
            vk_record!(vk_rec, 1, TEST_HALO2_CIRCUIT_FULL_ID, BackendTag::Halo2IpaPasta, "pallas", [0u8; 32], commitment; status = ConfidentialStatus::Active);
            let bad_circuit = OpenVerifyEnvelope::new(
                BackendTag::Halo2IpaPasta,
                TEST_OTHER_HALO2_CIRCUIT_ID,
                commitment,
                b"schema:voting:v1".to_vec(),
                vec![0xAA],
            );
            assert!(
                validate_open_verify_envelope_metadata(
                    "ballot",
                    "halo2/ipa",
                    &bad_circuit,
                    &vk_rec
                )
                .is_err()
            );
            let mut bad_hash = commitment;
            bad_hash[0] ^= 0x01;
            let bad_commitment = OpenVerifyEnvelope::new(
                BackendTag::Halo2IpaPasta,
                TEST_HALO2_CIRCUIT_ALIAS,
                bad_hash,
                b"schema:voting:v1".to_vec(),
                vec![0xAA],
            );
            assert!(
                validate_open_verify_envelope_metadata(
                    "ballot",
                    "halo2/ipa",
                    &bad_commitment,
                    &vk_rec
                )
                .is_err()
            );
            let zero_commitment = OpenVerifyEnvelope::new(
                BackendTag::Halo2IpaPasta,
                TEST_HALO2_CIRCUIT_ALIAS,
                [0u8; 32],
                b"schema:voting:v1".to_vec(),
                vec![0xAA],
            );
            let err = validate_open_verify_envelope_metadata(
                "ballot",
                "halo2/ipa",
                &zero_commitment,
                &vk_rec,
            )
            .expect_err("zero OpenVerifyEnvelope verifier hash must reject explicitly");
            assert_contains!(err.to_string(), "verifier-key hash must be non-zero", "unexpected zero-hash rejection: {err}");
            let mut non_empty_aux = OpenVerifyEnvelope::new(
                BackendTag::Halo2IpaPasta,
                TEST_HALO2_CIRCUIT_ALIAS,
                commitment,
                b"schema:voting:v1".to_vec(),
                vec![0xAA],
            );
            non_empty_aux.aux = b"ignored-hint".to_vec();
            assert!(
                validate_open_verify_envelope_metadata(
                    "ballot",
                    "halo2/ipa",
                    &non_empty_aux,
                    &vk_rec
                )
                .is_err()
            );
            let ok = OpenVerifyEnvelope::new(
                BackendTag::Halo2IpaPasta,
                TEST_HALO2_CIRCUIT_ALIAS,
                commitment,
                b"schema:voting:v1".to_vec(),
                vec![0xAA],
            );
            assert!(
                validate_open_verify_envelope_metadata("ballot", "halo2/ipa", &ok, &vk_rec).is_ok()
            );
            for backend_tag in [BackendTag::Stark] {
                let mut bad_backend_rec = vk_rec.clone();
                bad_backend_rec.backend = backend_tag;
                let err = validate_open_verify_envelope_metadata(
                    "ballot",
                    "halo2/ipa",
                    &ok,
                    &bad_backend_rec,
                )
                .expect_err("registered backend tag must match the admitted proof backend");
                assert_contains!(err.to_string(), "verifying key backend mismatch", "unexpected backend-tag rejection for {}: {err}", backend_tag.canonical_label());
            }
            for (label, envelope, expected) in [
                (
                    "empty_circuit",
                    OpenVerifyEnvelope::new(
                        BackendTag::Halo2IpaPasta,
                        "",
                        commitment,
                        b"schema:voting:v1".to_vec(),
                        vec![0xAA],
                    ),
                    "invalid OpenVerifyEnvelope",
                ),
                (
                    "empty_public_inputs",
                    OpenVerifyEnvelope::new(
                        BackendTag::Halo2IpaPasta,
                        TEST_HALO2_CIRCUIT_ALIAS,
                        commitment,
                        Vec::new(),
                        vec![0xAA],
                    ),
                    "invalid OpenVerifyEnvelope",
                ),
                (
                    "empty_proof_bytes",
                    OpenVerifyEnvelope::new(
                        BackendTag::Halo2IpaPasta,
                        TEST_HALO2_CIRCUIT_ALIAS,
                        commitment,
                        b"schema:voting:v1".to_vec(),
                        Vec::new(),
                    ),
                    "invalid OpenVerifyEnvelope",
                ),
                (
                    "oversized_public_inputs",
                    OpenVerifyEnvelope::new(
                        BackendTag::Halo2IpaPasta,
                        TEST_HALO2_CIRCUIT_ALIAS,
                        commitment,
                        vec![
                            0xA5;
                            iroha_data_model::zk::OPEN_VERIFY_DEFAULT_MAX_PUBLIC_INPUT_BYTES + 1
                        ],
                        vec![0xAA],
                    ),
                    "invalid OpenVerifyEnvelope",
                ),
            ] {
                let err = validate_open_verify_envelope_metadata(
                    "ballot",
                    "halo2/ipa",
                    &envelope,
                    &vk_rec,
                )
                .expect_err("{label} must reject");
                assert_contains!(err.to_string(), expected, "unexpected {label} rejection: {err}");
            }
        });
