        fn bootstrap_alice_account(stx: &mut StateTransaction<'_, '_>) {
            let domain_id: DomainId =
                DomainId::try_new("wonderland", "universal").expect("domain id parses");
            seed_domain_name_lease_tx(&mut stx.world, &ALICE_ID, &domain_id);
            Register::domain(Domain::new(domain_id))
                .execute(&ALICE_ID, stx)
                .expect("register wonderland domain");
            Register::account(new_account_in_domain(&ALICE_ID))
                .execute(&ALICE_ID, stx)
                .expect("register ALICE account");
        }
        fn grant_alice_account_permission(
            stx: &mut StateTransaction<'_, '_>,
            permission: &str,
            expectation: &str,
        ) {
            bootstrap_alice_account(stx);
            let permission = Permission::new(
                permission.parse().unwrap(),
                iroha_primitives::json::Json::new(()),
            );
            Grant::account_permission(permission, ALICE_ID.clone())
                .execute(&ALICE_ID, stx)
                .expect(expectation);
        }
        fn grant_alice_typed_permission(
            stx: &mut StateTransaction<'_, '_>,
            permission: impl Into<Permission>,
            expectation: &str,
        ) {
            bootstrap_alice_account(stx);
            Grant::account_permission(permission.into(), ALICE_ID.clone())
                .execute(&ALICE_ID, stx)
                .expect(expectation);
        }
        fn configure_universal_dataspace(stx: &mut StateTransaction<'_, '_>) {
            let dataspace_catalog = DataSpaceCatalog::new(vec![DataSpaceMetadata {
                id: DataSpaceId::UNIVERSAL,
                alias: "universal".to_string(),
                description: None,
                fault_tolerance: 1,
            }])
            .expect("dataspace catalog");
            stx.nexus.dataspace_catalog = dataspace_catalog.clone();
            stx.world.dataspace_catalog = dataspace_catalog;
        }
        fn configure_active_test_lanes(stx: &mut StateTransaction<'_, '_>, lane_ids: &[LaneId]) {
            assert!(!lane_ids.is_empty(), "test lane catalog cannot be empty");
            configure_universal_dataspace(stx);
            let lanes = lane_ids
                .iter()
                .map(|lane_id| LaneConfig {
                    id: *lane_id,
                    alias: format!("lane-{}", lane_id.as_u32()),
                    ..LaneConfig::default()
                })
                .collect::<Vec<_>>();
            let lane_count = lane_ids
                .iter()
                .map(|lane_id| lane_id.as_u32())
                .max()
                .and_then(|max_lane_id| NonZeroU32::new(max_lane_id.saturating_add(1)))
                .expect("nonempty lane id set produces nonzero lane count");
            let catalog = LaneCatalog::new(lane_count, lanes).expect("active test lane catalog");
            stx.nexus.lane_config = RuntimeLaneConfig::from_catalog(&catalog);
            stx.nexus.lane_catalog = catalog;
        }
        fn test_sccp_ivm_proved_execution_binding() -> crate::state::SccpIvmProvedExecutionBindingV1
        {
            crate::state::SccpIvmProvedExecutionBindingV1 {
                contract_artifact_sha256: [0xb1; 32],
                vk_ref: iroha_data_model::proof::VerifyingKeyId::new(
                    "stark/fri/v1",
                    "ivm-execution-v1",
                ),
                vk_version: 1,
                vk_commitment: [0xb2; 32],
                gas_limit: 50_000_000,
                gas_used: 1,
            }
        }
        fn enable_sccp_recording_for_test(stx: &mut StateTransaction<'_, '_>, lane_id: LaneId) {
            stx.sccp_ivm_proved_execution_binding = Some(test_sccp_ivm_proved_execution_binding());
            stx.current_lane_id = Some(lane_id);
            stx.current_dataspace_id = Some(DataSpaceId::UNIVERSAL);
            stx.world.current_dataspace_id = Some(DataSpaceId::UNIVERSAL);
            stx.chain_id = iroha_data_model::ChainId::from(iroha_sccp::SCCP_TAIRA_CHAIN_ID_V1);
            if stx.sccp_registry.lanes().is_empty() {
                stx.sccp_registry = crate::state::ValidatedSccpRegistryV1::try_from_wire(
                    test_active_eth_registry(),
                )
                .expect("active ETH registry fixture");
            }
            *stx.world.sccp_registry.get_mut() = stx.sccp_registry.to_wire();
            let route = stx.sccp_registry.lanes()[0]
                .routes
                .first()
                .expect("active ETH route fixture");
            let settlement_asset_definition_id = route.settlement.asset_definition_id.clone();
            let route_key = route.key();
            if stx.world.account(&ALICE_ID).is_err() {
                Register::account(Account::new(ALICE_ID.clone()))
                    .execute(&ALICE_ID, stx)
                    .expect("register SCCP sender fixture");
            }
            if stx
                .world
                .asset_definition(&settlement_asset_definition_id)
                .is_err()
            {
                Register::asset_definition(AssetDefinition::numeric(
                    settlement_asset_definition_id.clone(),
                    "xor",
                    iroha_data_model::asset::AssetBalancePolicy::Global,
                    None,
                ))
                .execute(&ALICE_ID, stx)
                .expect("register SCCP settlement asset fixture");
            }
            ensure_sccp_route_escrow_account(&route_key, &settlement_asset_definition_id, stx)
                .expect("register deterministic SCCP route escrow fixture");
            let sender_asset_id = AssetId::new(settlement_asset_definition_id, ALICE_ID.clone());
            if stx.world.asset(&sender_asset_id).is_err() {
                Mint::asset_quantity(1_000_000_u64, sender_asset_id.clone())
                    .execute(&ALICE_ID, stx)
                    .expect("fund SCCP sender fixture");
            }
            let governance_permission = Permission::from(
                iroha_executor_data_model::permission::sccp::CanManageSccpGovernance,
            );
            if !has_exact_permission(&stx.world, &ALICE_ID, &governance_permission) {
                Grant::account_permission(governance_permission, ALICE_ID.clone())
                    .execute(&ALICE_ID, stx)
                    .expect("grant SCCP governance fixture permission");
            }
        }
        fn seed_sccp_test_tx_call_hash(stx: &mut StateTransaction<'_, '_>, byte: u8) {
            assert_ne!(byte, 0, "SCCP test transaction hash seed must be nonzero");
            stx.tx_call_hash = Some(Hash::prehashed([byte; Hash::LENGTH]));
        }
        fn sccp_test_settlement_ids(
            stx: &StateTransaction<'_, '_>,
        ) -> (AssetDefinitionId, AccountId) {
            let route = stx.sccp_registry.lanes()[0]
                .routes
                .first()
                .expect("active SCCP route fixture");
            let asset = route.settlement.asset_definition_id.clone();
            let custody = iroha_data_model::bridge::sccp_route_escrow_account_id_v1(
                &stx.network_id,
                &route.key(),
                &asset,
            );
            (asset, custody)
        }
